(window.GIM_TS=window.GIM_TS||{})["Arakhin.0"]={"from":0,"a":[["\u0003הכל מעריכין,\u0004 שאם נדרו ערכו של אדם — חייבים לתת להקדש את ערכו הקצוב בתורה לפי שנותיו ומינו (ויקרא כז, ג—ז), \u0003ו\u0004הכל \u0003נערכין,\u0004 שאם נדר את ערכם חייב לשלם. וכן הכל \u0003נודרין\u0004 להקדש את שוויו של אדם (כאילו היה נמכר כעבד), \u0003ו\u0004הכל \u0003נודרין,\u0004 שאם אמר \"דמיו של פלוני עלי\" — חייב לשלם להקדש: \u0003כהנים, לוים, וישראלים, נשים, ועבדים.\u0004","\u0003טומטום,\u0004 שאין לו סימני זכר או נקבה, \u0003ואנדרוגינוס,\u0004 שיש לו סימני זכר וסימני נקבה, \u0003נודרין ונידרין ומעריכין, אבל לא נערכין,\u0004 שאם אמר: \"ערכו של פלוני טומטום עלי\" — אינו חייב כלום, מפני \u0003שאינו נערך אלא הזכר ודאי ונקבה ודאית,\u0004 שנזכרו בכתוב.","\u0003חרש שוטה וקטן נידרין ונערכין, אבל לא נודרין ולא מעריכין, מפני שאין בהם דעת.\u0004","שואלים: \u0003\"הכל מעריכין\"\u0004 ששנינו במשנתנו, \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 להוסיף, את \u0005מה\u0006 הוא בא\u0005]?\u0006 ומשיבים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003מופלא סמוך לאיש\u0004 כלומר, מי שהוא בן שתים עשרה שנה ויום אחד, שעדיין אינו איש מבוגר, אבל מבין בטיב נדרים, שהנדרים והערכים שהוציא מפיו מחייבים אותו.","ושואלים: \"הכל \u0003נערכין\"\u0004 ששנינו במשנתנו, \u0003לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]?\u0006 ומשיבים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 מי שהוא \u0003מנוול\u0004 (מאוס) או \u0003מוכה שחין,\u0004 שאינו שווה מאומה אילו היה עומד למכירה; סלקא דעתך אמינא \u0005[יעלה על דעתך לומר]:\u0006","\u0003\"נדר בערכך\"\u0004 (שם ב) \u0003כתיב\u0004 \u0005[נאמר],\u0006 ובכך הקישה התורה את דיני הנערך לדיני הנידר, ולכן \u0003כל שישנו בדמים,\u0004 שאם נדר את דמיו מתחייב לשלם להקדש — \u0003ישנו\u0004 גם \u0003בערכין,\u0004 שאם נדר את ערכו של אותו אדם — חייב לשלם, \u0003וכל שאינו בדמים,\u0004 שאם נדר את דמיו אינו מתחייב — \u0003אינו\u0004 גם \u0003בערכין,\u0004 ולכן הנודר את ערכו של מנוול ומוכה שחין פטור מלשלם, מפני שאינו שווה מאומה, על כן","\u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 התנא שגם אלו נערכים, שהרי התורה אמרה \"בערכך \u0003נפשת\"\u0004 (שם), ומשמע: \u0003כל דהו\u0004 \u0005[כל שהוא],\u0006 כל שיש בו נפש חיים יש לו ערך לפי שנותיו.","ושואלים: \"הכל \u0003נודרין\"\u0004 ששנינו במשנתנו, \u0003לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]?\u0006 ומשיבים: מה ששנינו \"הכל \u0003נידרין\" איצטריך ליה\u0004 \u0005[הוצרך לו],\u0006 ומשום כך הובא גם הכלל של \"הכל נודרין\", למרות שאין בו חידוש לעצמו.","ושואלים: ו\"הכל \u0003נידרין\" לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה\u0006 הוא בא\u0005]?\u0006 \u0003אי לאתויי\u0004 \u0005[אם\u0006 תאמר \u0005להביא]\u0006 \u0003טומטום ואנדרוגינוס\u0004 — הלוא \u0003בהדיא קתני להו\u0004 \u0005[במפורש הוא שונה אותם\u0006 במשנה\u0005]!\u0006 \u0003ואי לאתויי\u0004 \u0005[ואם להביא]\u0006 \u0003חרש שוטה וקטן\u0004 — \u0003בהדיא קתני להו\u0004 \u0005[במפורש הוא שונה אותם\u0006 במשנה\u0005]!\u0006","\u0003אי לאתויי\u0004 \u0005[אם להביא]\u0006 \u0003פחות מבן חודש,\u0004 שאינו בכלל ערכין, אבל בכל זאת אפשר לנדור את דמיו — גם כן \u0003בהדיא קתני להו\u0004 \u0005[במפורש הוא שונה אותם]\u0006 בהמשך המשנה שבפרקנו! \u0003ואי לאתויי\u0004 \u0005[ואם להביא]\u0006 \u0003נכרי,\u0004 הלוא \u0003בהדיא קתני להו\u0004 \u0005[במפורש הוא שונה אותם]\u0006 בהמשך המשנה שבפרקנו! ומשיבים: \u0003לעולם\u0004 שנינו \"הכל נידרין\" \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003פחות מבן חודש, ו\u0004אף ששנינו את דינו בהמשך המשנה — \u0003תני והדר מפרש\u0004 \u0005[שונה\u0006 התנא באופן כללי \u0005וחוזר\u0006 ו\u0005מפרש]\u0006 אחר כך את הפרטים.","אחר שהתברר מדוע נקטה משנתנו לשון \"הכל מעריכין\", מבררים מה באה לשון זו להוסיף במקומות אחרים. ושואלים, מה ששנינו במסכת מנחות: \u0003\"הכל סומכין\"\u0004 על ראש הקרבן, \u0003לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה\u0006 הוא בא\u0005]?\u0006 ומשיבים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003יורש,\u0004 שסומך על ראש קרבן מורישו, כשהוא מביאו לאחר מותו, \u0003ו\u0004ש\u0003לא כ\u0004שיטת \u0003ר' יהודה,\u0004 הסבור שיורש אינו סומך.","ושואלים: \u0003\"הכל ממירין\",\u0004 ששנינו במשנה במסכת תמורה, \u0003לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]?\u0006 ומשיבים: גם כאן, \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003יורש,\u0004 שאם אמר על בהמה שתהא תמורת בהמה שהקדיש אביו — גם השניה קדושה, \u0003ו\u0004ש\u0003לא כ\u0004שיטת \u0003ר' יהודה,\u0004 הסבור שיורש אינו עושה תמורה.","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003יורש סומך\u0004 על קרבן אביו שמת, \u0003יורש מימר,\u0004 כלומר, עושה תמורה בקרבן שירש מאביו\u0003. ר' יהודה אומר: יורש אינו סומך, יורש אינו מימר.\u0004","ומבררים: \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יהודה?\u0004 שנאמר בעניין סמיכה: \u0003\"קרבנו\"\u0004 (ויקרא ג, ב) והרי זה מיעוט, \"קרבנו\" — \u0003ולא קרבן אביו, ויליף\u0004 \u0005[ו\u0006הוא \u0005לומד]\u0006 דין \u0003תחלת הקדש,\u0004 כלומר, תמורה, כשמחילים קדושה על בהמה, \u0003מסוף הקדש,\u0004 מסמיכה, שהיא נעשית סמוך לשחיטת הקרבן: \u0003מה סוף הקדש\u0004 — \u0003יורש אינו סומך, אף תחלת הקדש\u0004 — \u0003יורש אינו מימר.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 הסבורים שיורש סומך ומימר, מהיכן הם למדים? ומשיבים, ממה שנאמר לגבי תמורה: \"ואם \u0003המר ימיר\"\u0004 (שם כז, י), והם למדים מהלשון הכפולה — \u0003לרבות את היורש, ו\u0004לשיטתם, \u0003ילפינן\u0004 \u0005[אנו למדים]\u0006 דינו של \u0003סוף הקדש\u0004 (סמיכה) \u0003מתחלת הקדש\u0004 (תמורה): \u0003מה תחלת הקדש\u0004 — \u0003יורש מימר, אף סוף הקדש\u0004 — \u0003יורש סומך.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003האי\u0004 \u0005[זה]\u0006 המיעוט \u0003\"קרבנו\",\u0004 ממנו למד ר' יהודה שיורש אינו סומך, \u0003מאי עבדי ליה\u0004 \u0005[מה עושים\u0006 הם \u0005בו]?\u0006 ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריכים הם אותו]\u0006 ללמוד ממנו: \u0003\"קרבנו\"\u0004 — \u0003ולא קרבן גוי,\u0004 שאין קרבן הגוי טעון סמיכה, \u0003\"קרבנו\"\u0004 — \u0003ולא קרבן חבירו,\u0004 שאין אדם יכול לסמוך על קרבן חבירו, \u0003\"קרבנו\"\u0004 — \u0003לרבות כל בעלי חוברין לסמיכה,\u0004 שאם חברו כמה אנשים להביא קרבן — כולם חייבים לסמוך עליו.","ואומרים: \u0003ור' יהודה,\u0004 את הדין של \u0003לרבות כל בעלי חוברין לסמיכה לית ליה\u0004 \u0005[אין לו],\u0006 אינו מקבל שיטה זו, אלא לדעתו אחד סומך עבור כולם. \u0003ואי נמי אית ליה\u0004 \u0005[ואם גם כן\u0006 תאמר ש\u0005יש לו],\u0006 וגם הוא לומד מהמילה \"קרבנו\" שכל השותפים חייבים לסמוך,"],["הדין שאין סומכים על קרבן \u0003גוי, ו\u0004הדין שאין סומכים על קרבן \u0003חבירו, מחד קרא\u0004 \u0005[מכתוב אחד]\u0006 של \"קרבנו\" \u0003נפקי\u0004 \u0005[יוצאים,\u0006 נלמדים\u0005],\u0006 ואם כן \u0003אייתרי להו תרי\u0004 \u0005[נתייתרו לו שני]\u0006 \"קרבנו\", \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 בא למעט: \u0003\"קרבנו\"\u0004 — \u0003ולא קרבן אביו,\u0004 שיורש אינו סומך, \u0003ואידך\u0004 \u0005[והאחר]\u0006 — \u0003לרבות כל בעלי חוברין לסמיכה,\u0004 שכל בעלי הקרבן חייבים לסמוך.","ושואלים: \u0003ור' יהודה, האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"המר ימיר\"\u0004 (ויקרא כז, י), משם למדו חכמים כי יורש ממיר קרבן של אביו, \u0003מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006 ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003לרבות את האשה,\u0004 שאם המירה קרבן שלה בבהמת חולין — הרי זו תמורה. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003לפי שכל הענין\u0004 של תמורה האמור בכתוב \u0003אינו מדבר אלא בלשון זכר, מה סופינו\u0004 כלומר, כיצד אנו מגיעים לבסוף \u0003לרבות את האשה? תלמוד\u0004 \u0003לומר\u0004 בלשון כפולה: \u0003\"ואם המר ימיר\",\u0004 לרבות את האשה.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מהיכן הם דורשים דין זה? ומשיבים: \u0003מ\u0004הו' היתירה שבמילה \u0003\"ואם\". ו\u0004אילו \u0003ר' יהודה,\u0004 את תוספת הו' במילה \u0003\"ואם\" לא דריש\u0004 \u0005[אינו דורש].\u0006","ושואלים עוד: \u0003\"הכל חייבין בסוכה\"\u0004 ששנינו בברייתא, \u0003לאיתויי מאי\u0004 \u0005[להביא,\u0006 להוסיף את \u0005מה]\u0006 הוא בא? ומשיבים: \u0003לאיתויי\u0004 \u0005[להביא]\u0006 \u0003קטן שאינו צריך לאמו\u0004 כשמתעורר בלילה משנתו, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003קטן שאינו צריך לאמו\u0004 — \u0003חייב בסוכה.\u0004","ושואלים: \u0003\"הכל חייבין בלולב\"\u0004 ששנינו בברייתא, \u0003לאיתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]\u0006 הוא בא? ומשיבים: \u0003לאיתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 \u0003קטן היודע לנענע\u0004 בלולב, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003קטן היודע לנענע\u0004 — \u0003חייב בלולב.\u0004","ושואלים: \u0003\"הכל חייבין בציצית\"\u0004 ששנינו בברייתא, \u0003לאיתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]\u0006 הוא בא? ומשיבים: \u0003לאיתויי\u0004 \u0005[להביא]\u0006 \u0003קטן היודע להתעטף\u0004 בטלית, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003קטן היודע להתעטף\u0004 — \u0003חייב בציצית.\u0004","ושואלים: \u0003\"הכל חייבין בתפילין\"\u0004 ששנינו בברייתא, \u0003לאיתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]\u0006 הוא בא? ומשיבים: \u0003לאיתויי\u0004 \u0005[להביא]\u0006 \u0003קטן היודע לשמור תפלין\u0004 כהלכה, דתניא \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003קטן היודע לשמור תפלין\u0004 — \u0003אביו לוקח\u0004 (קונה) \u0003לו תפלין.\u0004","ושואלים, מה ששנינו במשנה: \u0003\"הכל חייבין בראייה\"\u0004 כלומר, להיראות לפני ה' במקדש ברגל, ולהביא עולת ראיה, \u0003לאיתויי מאי\u0004 \u0005[להביא,\u0006 להוסיף את \u0005מה]\u0006 הוא בא? ומשיבים: \u0003לאיתויי\u0004 \u0005[להביא]\u0006 \u0003מי שחציו עבד וחציו בן חורין,\u0004 כגון עבד כנעני של שני שותפים ששיחרר אותו אחד מהם.","\u0003ול\u0004דעת \u0003רבינא\u0004 ש\u0003אמר: מי שחציו עבד וחציו בן חורין פטור מן הראייה,\u0004 הרי זה בא \u0003לאיתויי\u0004 \u0005[להביא]\u0006 מי שהיה \u0003חיגר\u0004 (פצוע ברגלו) \u0003ביום ראשון\u0004 של החג, והיה פטור באותה שעה מן הראיה, \u0003ונתפשט\u0004 (נתיישר, נתרפא) \u0003ביום שני\u0004 של החג, ללמד שהוא חייב בראיה.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]:\u0006 \u0003כולן,\u0004 כל ימי החג, הם \u0003תשלומין זה לזה,\u0004 להביא את קרבנות החג, ולא רק תשלומים ליום הראשון, ולדעתו ייתכן שגם מי שהיה פטור ביום הראשון — יהיה חייב בשני. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003כולן,\u0004 כל ימי החג, הם רק \u0003תשלומין לראשון,\u0004 ולפיכך, מי שהיה חיגר ביום הראשון ונפטר מן הראיה שוב אינו מתחייב בקרבן, אם כן הריבוי \"הכל חייבין בראיה\" \u0003לאיתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]\u0006 הוא בא?","ומשיבים: \u0003לאיתויי\u0004 \u0005[להביא]\u0006 \u0003סומא באחת מעיניו,\u0004 שאף הוא חייב לעלות לרגל, שלא כדין סומא בשתי עיניו. ומעירים: \u0003ו\u0004דבר זה הוא ש\u0003לא כי האי תנא\u0004 \u0005[כ\u0006שיטת \u0005תנא זה],\u0006","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003יוחנן בן דהבאי אומר משום\u0004 (משמו של) \u0003ר' יהודה: סומא באחת מעיניו פטור מן הראייה, שנאמר:\u0004 \"שלש פעמים בשנה יראה כל זכורך אל פני האדון ה' \" (שמות כג, יז), ולפי הכתיב ניתן לקרוא: \u0003\"יראה\",\u0004 אבל הקריאה היא: \u0003\"יראה\",\u0004 וכך דורשים: \u0003כדרך שבא לראות כך בא ליראות, מה לראות,\u0004 אדם רואה \u0003בשתי עיניו\u0004 — \u0003אף\u0004 מה שציותה התורה \u0003ליראות\u0004 לפני ה' הרי זה \u0003בשתי עיניו.\u0004 זאת דרך אחת להסביר את הריבוי \"הכל חייבין בראיה\" לשיטת רבינא.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם\u0004 בא הריבוי \u0003לאיתויי\u0004 \u0005[להביא]\u0006 \u0003מי שחציו עבד וחציו בן חורין. ודקא קשיא לך\u0004 \u0005[ומה שהיה קשה לך]\u0006 מדברי \u0003רבינא,\u0004 שפוטר עבד כזה מן הראיה — \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003כאן\u0004 מדובר \u0003במשנה ראשונה, כאן\u0004 מדובר \u0003במשנה אחרונה.\u0004","\u0003דתנן\u0004 \u0005[ש\u0006כך \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שחציו עבד וחציו בן חורין, עובד את רבו יום אחד,\u0004 שהרי חציו עבד, \u0003ואת עצמו יום אחד,\u0004 שהרי חציו בן חורין, אלו \u0003דברי בית הלל.\u0004","\u0003אמרו להם בית שמאי: תיקנתם\u0004 בדרך זו \u0003את רבו,\u0004 שהוא מקבל את המגיע לו בעבד זה, אבל \u0003את עצמו לא תיקנתם\u0004 כראוי, שהרי \u0003לישא שפחה אינו יכול,\u0004 משום שהוא חציו בן חורין, ובן חורין אסור בשפחה, וגם לישא \u0003בת חורין אינו יכול,\u0004 משום שהוא חציו עבד שאסור בבת חורין, האם \u0003יבטל\u0004 מלשאת אשה? \u0003והלא לא נברא העולם אלא לפריה ורביה, שנאמר:\u0004 \"כי כה אמר ה'... יוצר הארץ ועושה הוא כוננה, \u0003לא תהו בראה לשבת יצרה\"\u0004 (ישעיהו מה, יח)!","\u0003אלא, מפני תיקון העולם,\u0004 כדי שיוכל העבד לעסוק ביישובו של עולם, \u0003כופין את רבו ועושה אותו בן חורין, ו\u0004הואיל ואין לעבד ממון כדי לפדות עצמו \u0003כותב\u0004 העבד \u0003שטר\u0004 חוב \u0003על חצי דמיו,\u0004 ונותן לאדון, ובמשך הזמן פורע את חובו. \u0003וחזרו בית הלל להורות כדברי בית שמאי\u0004 שחובה לשחרר עבד כזה. ומשנתנו, המחייבת עבד כזה בראיה, הולכת לשיטה זאת המחייבת את רבו לשחררו. ומה שפטר רבינא עבד זה מן הראיה, הוא לפי משנה ראשונה ששנו בית הלל, שאין כופים את רבו לשחררו.","ושואלים: \u0003\"הכל חייבין בתקיעת שופר\"\u0004 ששנינו בברייתא, \u0003לאיתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]?\u0006 ומשיבים: \u0003לאיתויי\u0004 \u0005[להביא]\u0006 \u0003קטן שהגיע לחינוך,\u0004 ועל קטן כזה הוא \u0003דתנן\u0004 \u0005[ששנינו]:\u0006 \u0003אין מעכבין את הקטן מלתקוע ביום טוב.\u0004","ושואלים: \u0003\"הכל חייבין במקרא מגילה\"\u0004 ששנינו בברייתא, ו\u0003\"הכל כשרין לקרות את המגילה\"\u0004 ששנינו במשנה, \u0003לאיתויי\u0004 \u0005[להביא]\u0006"],["\u0003מאי\u0004 \u0005[\u0006את \u0005מה]?\u0006 ומשיבים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003נשים, וכ\u0004דברי \u0003ר' יהושע בן לוי,\u0004 ש\u0003אמר ר' יהושע בן לוי: נשים חייבות במקרא מגילה, שאף הן היו באותו הנס\u0004 של פורים, שניצלו מגזירת המן.","ושואלים, מה ששנינו בברייתא: \u0003\"הכל חייבין בזימון\"\u0004 (לזמן עצמם לברך יחד ברכת המזון), \u0003לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]\u0006 הוא בא? ומשיבים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003נשים ועבדים,\u0004 וכפי \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003נשים מזמנות לעצמן,\u0004 \u0003ועבדים מזמנין לעצמן.\u0004","ושואלים, מה ששנינו בברייתא: \u0003\"הכל מצטרפין לזימון\", לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]\u0006 הוא בא? ומשיבים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003קטן היודע למי מברכין,\u0004 ש\u0003אמר רב נחמן:\u0004 קטן ש\u0003יודע למי מברכין\u0004 — \u0003מזמנין עליו,\u0004 כלומר, הריהו נחשב כחלק ממנין המזמנים.","ושואלים: \u0003\"הכל מטמאין בזיבה\"\u0004 ששנינו במשנה, \u0003לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]\u0006 הוא בא? ומשיבים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003תינוק בן יומו,\u0004 שאם יצאה זיבה מגופו הריהו טמא. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 די היה לכתוב \u0003\"איש\"\u0004 — \u0003מה תלמוד לומר \"איש איש\u0004 כי יהיה זב מבשרו זובו טמא הוא\" (ויקרא טו, ב)? הרי זה בא \u0003לרבות תינוק בן יום אחד שמטמא בזיבה,\u0004 אלו \u0003דברי ר' יהודה.\u0004","\u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר: אינו צריך\u0004 לריבוי זה, \u0003הרי הוא אומר: \"והזב את זובו לזכר ולנקבה\"\u0004 (שם לג), \u0003\"לזכר\"\u0004 — \u0003כל שהוא זכר, בין קטן בין גדול, \"לנקבה\"\u0004 — \u0003כל שהיא נקבה, בין קטנה בין גדולה. אם כן, מה תלמוד לומר \"איש איש\"? דברה תורה כלשון בני אדם,\u0004 שהם רגילים לכפול לשונם, ואין ללמוד מכך דין חדש.","ושואלים, מה ששנינו בברייתא: \u0003\"הכל מטמאין בטמא מת\"\u0004 \u0003לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]\u0006 הוא בא? ומשיבים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003קטן;\u0004 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 שמהכתוב \u0003\"איש אשר יטמא ולא יתחטא\"\u0004 (במדבר יט, כ), יש ללמוד כי \u0003\"איש\"\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 נטמא, אבל \u0003קטן,\u0004 שלא הגיע לכלל איש — \u0003לא\u0004 מקבל טומאה, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 הכתוב בטהרת הנטמאים במת: \"והזה על האהל... \u0003ועל הנפשות אשר היו שם\"\u0004 (שם יח), ומכאן שכל נפש שנמצאת שם נטמאת, בין גדול בין קטן.","ושואלים: \u0003אלא\u0004 לפי זה, \u0003\"איש\" למעוטי מאי\u0004 \u0005[למעט מה]\u0006 הוא בא? ומשיבים: \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003קטן מ\u0004עונש \u0003כרת\u0004 האמור באותו פסוק: \"ונכרתה הנפש ההיא מתוך הקהל כי את מקדש ה' טמא\" (שם כ), שאם נטמא ונכנס למקדש — אינו חייב כרת.","ושואלים, מה ששנינו במשנה: \u0003\"הכל מטמאין בנגעים\" לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]\u0006 הוא בא? ומשיבים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003קטן,\u0004 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003\"איש צרוע\u0004 הוא טמא הוא\" (ויקרא יג, מד) \u0003כתיב\u0004 \u0005[נאמר],\u0006 ונלמד מכך ש\u0003איש\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 נטמא, אבל \u0003קטן,\u0004 שלא הגיע לכלל איש — \u0003לא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 התנא שגם הוא מיטמא בנגעים.","ושואלים: \u0003ואימא הכי נמי\u0004 \u0005[ואמור כך גם כן],\u0006 שקטן אינו מיטמא בנגעים! ומשיבים: לכך נאמר \u0003\"אדם כי יהיה בעור בשרו\"\u0004 (ויקרא יג, ב) \u0003מכל מקום,\u0004 כל שהוא אדם, גם קטן שלא הגיע לכלל \"איש\".","ושואלים: \u0003ואלא\u0004 לפי זה, \u0003\"איש\u0004 צרוע הוא\" \u0003למה לי?\u0004 ומשיבים: \u0003לכדתניא\u0004 \u0005[לכמו ששנויה\u0006 \u0005בברייתא\u0006\u0005]\u0006 על פסוק זה: \u0003\"איש\u0004 צרוע הוא\" — \u0003אין לי אלא איש, אשה מנין\u0004 שניטמאת בנגעים? \u0003כשהוא אומר\u0004 מיד לאחר מכן שוב: \u0003\"והצרוע\u0004 אשר בו הנגע\" (שם מה), ואין בכך צורך — \u0003הרי כאן שנים,\u0004 כלומר, לא רק איש, אלא גם אשה.","\u0003אם כן, מה תלמוד לומר,\u0004 כלומר, לשם מה נאמר מתחילה \u0003\"איש\"\u0004 — \u0003לענין של מטה\u0004 כלומר, להמשך הכתוב: \"בגדיו יהיו פרומים וראשו יהיה פרוע\", ללמד ש\u0003איש\u0004 מצורע \u0003פורע\u0004 את שערו, \u0003ופורם\u0004 את בגדיו, \u0003ואין האשה פורעת ופורמת.\u0004","ושואלים, מה ששנינו בברייתא: \u0003\"הכל רואין את הנגעים\",\u0004 כדי לטמאם או לטהרם, וכן מה ששנינו במשנה: \u0003\"הכל כשרין לראות את הנגעים\"\u0004 לטמאם ולטהרם, \u0003לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]\u0006 הוא בא? ומשיבים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 כהן \u0003שאינו בקי בהן\u0004 במראה הנגעים \u0003ובשמותיהן.\u0004","ומקשים: \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]:\u0006 מי ש\u0003אינו בקי בהן ובשמותיהן אינו רואה את הנגעים! אמר רבינא, לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא דמסברי ליה וסבר\u0004 \u0005[זה שמסבירים לו ו\u0006הוא \u0005סובר\u0006 ומבין\u0005],\u0006 יכול לראות, ולטמא או לטהר לאחר שהסבירו לו, \u0003הא דמסברי ליה ולא סבר\u0004 \u0005[זה שמסבירים לו ואינו סובר,\u0006 מבין\u0005],\u0006 והוא אינו רואה את הנגעים.","ושואלים, מה ששנינו במשנה: \u0003\"הכל כשרין לקדש\"\u0004 (לתת אפר פרה אדומה במים החיים) \u0003לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]\u0006 הוא בא? ומשיבים: \u0003ל\u0004דעת \u0003ר' יהודה\u0004 הרי זה בא \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003קטן, ולרבנן\u0004 \u0005[ו\u0006לדעת \u0005חכמים],\u0006 הסבורים שקטן אינו מקדש — \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003אשה,\u0004 שכשרה לקדש. \u0003דתנן\u0004 \u0005[ש\u0006כך \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הכל כשרין לקדש, חוץ מחרש שוטה וקטן; ר' יהודה מכשיר בקטן, ופוסל באשה ובאנדרוגינוס\u0004 (שיש בו גם סימני זכר וגם סימני נקבה).","ושואלים, מה ששנינו במשנה: \u0003\"הכל כשירין להזות\"\u0004 ממי פרה אדומה על טמא מת, \u0003לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]\u0006 הוא בא? ומשיבים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003ערל, וכ\u0004דברי \u0003ר' אלעזר,\u0004 ש\u0003אמר ר' אלעזר: ערל שהזה\u0004 — \u0003הזאתו כשרה.\u0004","ושואלים, מה ששנינו במשנה פעמיים: \u0003\"הכל שוחטין\" לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]\u0006 הוא בא? ומשיבים: \u0003חדא לאתויי\u0004 \u0005[\u0006פעם \u0005אחת להביא]\u0006 \u0003כותי,\u0004 ששחיטתו כשירה, \u0003וחדא לאתויי\u0004 \u0005[ו\u0006פעם \u0005אחת להביא]\u0006 \u0003ישראל משומד\u0004 (עובר עבירה באופן קבוע).","ושואלים, מה ששנינו: \u0003\"הכל מעלין לארץ ישראל\",\u0004 כלומר, כופים את בני ביתם לעלות, \u0003לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]\u0006 הוא בא?"],["ומשיבים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003עבדים,\u0004 שעבד שרוצה לעלות — יכול לכפות את אדונו לעלות עמו, או למוכרו למי שעולה לשם, או לשחררו. ושואלים: \u0003ולמאן דתני\u0004 \u0005[ולמי ששונה]\u0006 דין זה של \u0003עבדים בהדיא\u0004 \u0005[במפורש],\u0006 \u0003לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]\u0006 בא \"הכל מעלין לארץ ישראל\"? ומשיבים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 שכופה אדם את בני ביתו לעלות אפילו \u0003מנוה היפה\u0004 (ממקום טוב) בחוצה לארץ \u0003לנוה הרעה\u0004 בארץ ישראל.","ומוסיפים: ומה ששנינו באותה משנה \u0003\"ואין הכל מוציאין\u0004 מן הארץ לחוצה לארץ\", הרי זה \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003עבד שברח מחוצה לארץ לארץ\u0004 ישראל, שאין אדונו יכול להחזיר אותו לחוצה לארץ.","ומה ששנינו שם: \u0003הכל מעלין לירושלים,\u0004 הרי זה בא \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003מנוה היפה לנוה הרעה\u0004 כלומר, למרות שהמקום האחר טוב יותר למגורים מירושלים. ושואלים, ומה ששנינו שם: \u0003\"ואין הכל מוציאין\",\u0004 \u0003לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]?\u0006 ומשיבים: \u0003לאתויי\u0004 \u0005[להביא],\u0006 שאינו יכול לכפות לצאת מירושלים, אפילו \u0003מנוה הרעה לנוה היפה\u0004 בארץ ישראל.","ומעתה דנים במשניות ובברייתות, שנאמרה בהן לשון \"הכל חייבים\", ונוסף להן: \"כהנים לויים וישראלים\". שנינו בברייתא: \u0003הכל חייבין בסוכה, כהנים לוים וישראלים.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005],\u0006 \u0003אי הני לא מחייבי, מאן מיחייבי\u0004 \u0005[\u0006והלא \u0005אם אלו לא חייבים, מי חייבים]?\u0006","ומשיבים: \u0003כהנים איצטריכא ליה\u0004 \u0005[הוצרך לו\u0006 להשמיע\u0005],\u0006 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"בסכות תשבו\u0004 שבעת ימים\" (ויקרא כג, מב), \u0003ואמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"תשבו שבעת ימים\"\u0004 — \u0003כעין תדורו,\u0004 כלומר, כדרך שאדם דר בביתו כל השנה, \u0003מה דירה\u0004 — דרים יחד \u0003איש ואשתו, אף סוכה\u0004 מצותה דווקא באותו אופן — \u0003איש ואשתו, והני\u0004 \u0005[ואותם]\u0006 \u0003כהנים, הואיל ו\u0004ברגל \u0003בני עבודה\u0004 במקדש \u0003נינהו\u0004 \u0005[הם],\u0006 ואינם פנויים לדור עם נשיהם — יש לומר ש\u0003לא ליחייבו\u0004 \u0005[יתחייבו]\u0006 בסוכה, על כן","\u0003קא משמע לן\u0004 \u0005[משמיע לנו]:\u0006 \u0003נהי דפטירי\u0004 \u0005[גם אם אמנם פטורים\u0006 הם\u0005]\u0006 \u0003בשעת עבודה\u0004 עצמה, \u0003בלא שעת עבודה חיובי מיחייבי\u0004 \u0005[חייבים\u0006 הם\u0005],\u0006 \u0003מידי דהוה\u0004 \u0005[כשם שהוא\u0006 הדין\u0005]\u0006 ב\u0003הולכי דרכים, דאמר מר\u0004 \u0005[שאמר החכם]\u0006 בברייתא: \u0003הולכי דרכים,\u0004 שעושים את דרכם \u0003ב\u0004שעות ה\u0003יום\u0004 — \u0003פטורין מן הסוכה ביום, וחייבים בלילה,\u0004 מפני שאז אינם הולכים.","שנינו בברייתא: \u0003הכל חייבין בציצית, כהנים לוים וישראלים.\u0004 וגם על כך שואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר שגם אלו בכלל!","ומשיבים: \u0003כהנים איצטריך ליה\u0004 \u0005[הוצרך לו\u0006 להשמיע\u0005],\u0006 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"לא תלבש שעטנז\u0004 צמר ופשתים יחדיו\", ובסמוך לכך נאמר: \u0003\"גדלים תעשה לך\u0004 על ארבע כנפות כסותך\" (דברים כב, יא—יב), יש לומר מכאן כי דווקא \u0003מאן דלא אישתרי כלאים לגביה\u0004 \u0005[מי שלא הותרו כלאים אצלו]\u0006 \u0003בלבישה\u0004 — \u0003הוא דמחייב\u0004 \u0005[שמחוייב]\u0006 \u0003במצות ציצית, והני\u0004 \u0005[ואותם]\u0006 \u0003כהנים, הואיל ואישתרי\u0004 \u0005[והותרו]\u0006 \u0003כלאים לגבייהו\u0004 \u0005[לגביהם],\u0006 שהרי האבנט של בגדי הכהונה היה שעטנז, \u0003לא לחייבו\u0004 \u0005[לא יתחייבו]\u0006 בציצית, על כן","\u0003קא משמע לן\u0004 \u0005[משמיע לנו]:\u0006 \u0003נהי דאישתרי בעידן\u0004 \u0005[אם אמנם הותר\u0006 להם השעטנז \u0005בזמן]\u0006 \u0003עבודה, בלא עידן\u0004 \u0005[שלא בזמן]\u0006 \u0003עבודה לא אישתרי\u0004 \u0005[לא הותר]\u0006 להם, ולכן חייבים בציצית כשאר ישראל.","ועוד שנינו בברייתא: \u0003הכל חייבין בתפילין, כהנים לוים וישראלים.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט],\u0006 שגם אלו בכלל! ומשיבים: \u0003כהנים איצטריך ליה\u0004 \u0005[הוצרך לו\u0006 להשמיע\u0005],\u0006 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"וקשרתם לאות על ידך והיו לטטפת בין עינך\"\u0004 (דברים ו, ח), והוקשו תפילין של יד לשל ראש, יש לומר כי \u0003כל דאיתיה\u0004 \u0005[שישנו]\u0006 \u0003ב\u0004חיוב \u0003מצוה\u0004 של \u0003יד, איתיה\u0004 \u0005[ישנו]\u0006 \u0003ב\u0004חיוב \u0003מצוה\u0004 של","\u0003ראש, והני\u0004 \u0005[ואותם]\u0006 \u0003כהנים, הואיל וליתנהו\u0004 \u0005[ואינם]\u0006 \u0003ב\u0004חיוב \u0003מצוה\u0004 של \u0003יד, דכתיב\u0004 \u0005[שנאמר]\u0006 לגבי בגדי הכהונה: \u0003\"ילבש על בשרו\"\u0004 (ויקרא ו, ג) — \u0003שלא יהא דבר חוצץ בינו\u0004 (בין בגד הכהונה) \u0003ובין בשרו,\u0004 והתפילין מהוים חציצה, \u0003אימא\u0004 \u0005[אמור]\u0006 כי \u0003במצוה\u0004 של \u0003ראש נמי לא ליחייבו\u0004 \u0005[גם כן לא יתחייבו],\u0006 על כן","\u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 \u0003דלא מעכבי אהדדי\u0004 \u0005[שאינן מעכבות זו את זו],\u0006 \u0003כדתנן\u0004 \u0005[כפי ששנינו]:\u0006 \u0003תפלה של יד אינה מעכבת של ראש, ושל ראש אינה מעכבת של יד,\u0004 והכהנים חייבים במצוות תפילין של ראש בשעת עבודתם.","ושואלים: \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 דין תפילין של \u0003יד,\u0004 שהם פטורים — מפני \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בבגד הכהונה: \u0003\"ילבש על בשרו\"\u0004 (שם), שלא יהא דבר חוצץ בין בשרו לבגד? לגבי תפילין של \u0003ראש נמי\u0004 \u0005[גם כן]\u0006 הרי \u0003כתיב\u0004 \u0005[נאמר]\u0006 לגבי הכהן הגדול: \u0003\"ושמת המצנפת על ראשו\"\u0004 (שמות כט, ו), ותפילין של ראש חוצצים בין ראשו לבין המצנפת!","ומשיבים, \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003שערו\u0004 של כהן גדול \u0003היה נראה בין ציץ,\u0004 שהיה מונח על מצחו, \u0003למצנפת, ששם\u0004 היה \u0003מניח תפילין,\u0004 ולא היתה איפוא חציצה.","שנינו בברייתא: \u0003הכל חייבין בתקיעת שופר, כהנים לוים וישראלים.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט],\u0006 גם הם חייבים! ומשיבים: \u0003כהנים איצטריכא ליה\u0004 \u0005[הוצרך לו\u0006 להשמיע\u0005],\u0006 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]\u0006 \"ובחדש השביעי באחד לחדש... \u0003יום תרועה יהיה לכם\"\u0004 (במדבר כט, א), יש לומר כי \u0003מאן דליתיה אלא בתקיעה דחד יומא\u0004 \u0005[מי שאינו\u0006 חייב \u0005אלא בתקיעה\u0006 של \u0005יום אחד\u0006 בשנה\u0005]\u0006 \u0003חייב\u0004 במצוה זו,","\u0003והני\u0004 \u0005[ואותם]\u0006 \u0003כהנים, הואיל ואיתנהו\u0004 \u0005[וישנם]\u0006 \u0003ב\u0004חיוב \u0003תקיעה\u0004 במקדש \u0003כוליה שתא\u0004 \u0005[כל השנה],\u0006 גם במועדים אחרים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ותקעתם בחצצרת על עלתיכם\"\u0004 (במדבר י, י) — \u0003אימא לא ליחייבו\u0004 \u0005[אמור\u0006 ש\u0005לא יתחייבו]\u0006 במצוה המיוחדת של תקיעת שופר בראש השנה, ולכן הוצרך להשמיענו שאף הכהנים חייבים. ותמהים על השוואה זו: \u0003מי דמי\u0004 \u0005[האם דומה]\u0006 הדבר, שהוצרך להשמיענו דין זה? \u0003התם\u0004 [\u0005שם],\u0006 התקיעות שתוקעים הכהנים במשך השנה היו ב\u0003חצוצרות,\u0004 ואילו \u0003הכא\u0004 \u0005[כאן],\u0006 בראש השנה — ב\u0003שופר!\u0004","ומשיבים: על כל פנים \u0003איצטריך\u0004 \u0005[הוצרך\u0006 להשמיענו דין זה\u0005]\u0006 מטעם אחר, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר],\u0006 \u0003הואיל ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003שוה היובל לראש השנה ל\u0004מצות ה\u0003תקיעה ולברכות\u0004 של מלכיות זכרונות ושופרות, שמוסיפים בתפילה, נאמר כי מי \u0003דאיתיה\u0004 \u0005[שישנו]\u0006 \u0003כ\u0004כל דיני \u0003מצות יובל\u0004 — \u0003איתיה\u0004 \u0005[ישנו]\u0006 \u0003ב\u0004כל דיני \u0003מצות ראש השנה,\u0004 ומי \u0003דליתיה\u0004 \u0005[שאינו]\u0006 \u0003ב\u0004כל דיני \u0003מצות יובל\u0004 — \u0003ליתיה\u0004 \u0005[אינו]\u0006 \u0003ב\u0004כל דיני \u0003מצות ראש השנה, והני כהני\u0004 \u0005[ואותם כהנים],\u0006 \u0003הואיל וליתנהו\u0004 \u0005[ואינם]\u0006 \u0003ב\u0004כל דיני \u0003מצות יובל, דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו]:\u0006 \u0003כהנים ולוים מוכרין לעולם\u0004 את שדותיהם, אפילו בשנת היובל עצמה,"],["\u0003וגואלין לעולם\u0004 שדה שמכרו, ואפילו מיד, שלא כישראלים, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003במצות\u0004 תקיעת שופר ביובל וב\u0003ראש השנה נמי לא ליחייבו\u0004 \u0005[גם כן לא יתחייבו],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]:\u0006 \u0003נהי דליתנהו\u0004 \u0005[גם אם אמנם אינם\u0006 שייכים\u0005]\u0006 \u0003בהשמטת קרקע\u0004 של יובל, \u0003בהשמטת כספים\u0004 ו\u0003בשילוח עבדים\u0004 עבריים \u0003מיהא איתנהו\u0004 \u0005[על כל פנים ישנם]\u0006 ביובל, ולכן חייבים הם בתקיעה ביובל ובראש השנה.","שנינו בברייתא: \u0003הכל חייבים במקרא מגילה, כהנים לוים וישראלים.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר! ומשיבים: \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 אלא להשמיע שחייבים \u0003ליבטיל\u0004 \u0005[לבטל]\u0006 את \u0003עבודתם\u0004 כדי לשומעה, \u0003וכ\u0004מו שאמר \u0003רב יהודה אמר שמואל,\u0004 ש\u0003אמר רב יהודה אמר שמואל: כהנים\u0004 כשהם \u0003בעבודתם\u0004 במקדש, \u0003ו\u0004כן \u0003לוים\u0004 העומדים \u0003בדוכנן\u0004 במקדש כדי לשיר, \u0003ו\u0004כן \u0003ישראל\u0004 העומדים \u0003במעמדן\u0004 על קרבנות הציבור, \u0003מבטלין עבודתם\u0004 במקדש, \u0003ובאין לשמוע מקרא מגילה.\u0004","שנינו בברייתא: \u0003הכל חייבין בזימון\u0004 להצטרף יחד לברכת המזון, \u0003כהנים לוים וישראלים.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט],\u0006 הדבר! ומשיבים: \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 הלכה זו אלא לשעה \u0003דקאכלי\u0004 \u0005[שאוכלים]\u0006 הכהנים בשר \u0003קדשים,\u0004 \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003\"ואכלו אותם אשר כפר בהם\"\u0004 (שמות כט, לג) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 שאכילת הכהנים מבשר הקרבן יש בה כפרה לבעלים, \u0003והא\u0004 \u0005[ו\u0006אכילה \u0005זו]\u0006 אכילת חובה לשם \u0003כפרה היא,\u0004 ואין זה נחשב כסעודה משותפת המחייבת בזימון, על כן","\u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 כי \u0003\"ואכלת ושבעת\u0004 וברכת\" (דברים ח, י) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 החיוב בברכה תלוי בשביעה, \u0003והא איתנהו\u0004 \u0005[והרי ישנם\u0006 בשביעה\u0005],\u0006 ולכן חייבים בזימון.","שנינו בבריתא: \u0003הכל מצטרפין\u0004 יחד \u0003לזימון, כהנים לוים וישראלים.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט],\u0006 הדבר! ומשיבים: \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 הלכה זו אלא למקרה \u0003דקאכלי\u0004 \u0005[שאוכלים]\u0006 \u0003כהנים תרומה או קדשים, ו\u0004אילו ה\u0003זר\u0004 שעימם \u0003קאכיל\u0004 \u0005[אוכל]\u0006 \u0003חולין;\u0004","\u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ואי בעי\u0004 \u0005[ואם רוצה]\u0006 ה\u0003זר למיכל בהדי\u0004 \u0005[לאכול יחד עם]\u0006 ה\u0003כהן\u0004 מהתרומה \u0003לא מצי אכיל\u0004 \u0005[אינו יכול לאכול],\u0006 שהיא אסורה עליו — \u0003אימא לא ליצטרף\u0004 \u0005[אמור שלא יצטרף עמם\u0006 לזימון\u0005],\u0006 לכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]:\u0006 \u0003נהי דזר בהדי כהן לא מצי אכיל, כהן בהדי זר מצי אכיל\u0004 \u0005[\u0006גם \u0005אם אמנם זר ביחד עם הכהן אינו יכול לאכול\u0006 מהתרומה, \u0005כהן ביחד עם הזר יכול לאכול\u0006 מהחולין\u0005],\u0006 ולכן הם מצטרפים לזימון.","שנינו במשנתנו: \u0003הכל מעריכין, כהנים לוים וישראלים.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט],\u0006 שכל אלו מעריכים! \u0003אמר רבא: לא נצרכא\u0004 \u0005[לא נצרכה]\u0006 הלכה זו \u0003אלא ל\u0004שיטת \u0003בן בוכרי,\u0004 הסבור שהכהנים פטורים מלתת מחצית השקל, ולפי זה היה מקום לומר שאינם בכלל ערכין, כאשר יבואר להלן. ומהי שיטתו? \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003אמר ר' יהודה, העיד בן בוכרי ביבנה\u0004 בשם חכמים: \u0003כל כהן ששוקל,\u0004 כלומר, שנותן מחצית השקל לצורך קרבנות הציבור — \u0003אינו חוטא,\u0004 למרות שאינו חייב לתת.","\u0003אמר לו רבן יוחנן בן זכאי: לא כן, אלא כל כהן שאינו שוקל\u0004 — \u0003חוטא,\u0004 שאף הכהנים חייבים במחצית השקל, \u0003אלא שהכהנים,\u0004 שנהגו שלא לתרום, \u0003דורשין מקרא זה ל\u0004טובת \u0003עצמן:\u0004 הלא נאמר בתורה \u0003\"וכל מנחת כהן כליל תהיה לא תאכל\"\u0004 (ויקרא ו, טז), שמנחת כהן, שלא כמנחה רגילה, אינה נאכלת אלא קריבה כולה.","ואם כן, \u0003הואיל ועומר ושתי הלחם ולחם הפנים,\u0004 שהן מנחות הציבור, גם \u0003שלנו הם,\u0004 אם ניתן מחצית השקל, היאך הם נאכלין על ידינו? הלא מנחת כהן הם! ולגופם של דברים מבררים: \u0003ולבן\u0004","\u0003בוכרי נמי\u0004 \u0005[גם כן]\u0006 קשה, \u0003כיון\u0004 ש\u0003לכתחילה לא מיחייבי לאיתויי\u0004 \u0005[אין\u0006 הכהנים \u0005מחוייבים להביא]\u0006 מחצית השקל, \u0003כי מייתי נמי\u0004 \u0005[כאשר\u0006 הכהן \u0005מביא גם כן]\u0006 — \u0003חוטא הוא, דקא מעייל\u0004 \u0005[ש\u0006הרי \u0005הוא מכניס]\u0006 \u0003חולין לעזרה!\u0004 ומשיבים: מדובר \u0003דמייתי להו\u0004 \u0005[שמביא אותם]\u0006 \u0003ומסר\u0004 \u0005[ומוסר]\u0006 אותם מנדבת ליבו \u0003לצבור.\u0004","וחוזרים לעיקר הדברים: ומפני שלדעת בן בוכרי, הכהנים פטורים מן השקלים, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"וכל ערכך יהיה בשקל הקדש\"\u0004 (ויקרא כז, כה), יש ללמוד משם כי \u0003כל דאיתיה\u0004 \u0005[שישנו]\u0006 מצות \u0003שקלים\u0004 — \u0003איתיה\u0004 \u0005[ישנו]\u0006 מצות \u0003ערכין, והני\u0004 \u0005[ואותם]\u0006 \u0003כהנים, הואיל וליתנהו\u0004 \u0005[ואינם]\u0006 \u0003בשקלים\u0004 — \u0003ליתנהו\u0004 \u0005[אינם]\u0006 \u0003בערכין,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 התנא שאפילו לשיטת בן בוכרי שייכים הכהנים בערכין.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבא: וכיצד ניתן היה לפטור את הכהנים על פי כתוב זה? והלא \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"וכל ערכך\u0004 יהיה בשקל הקדש\", ללמד \u0003לכל ערכין שאתה מעריך\u0004 ש\u0003לא יהו פחותין מסלע הוא דאתא\u0004 \u0005[שבא].\u0006 כלומר, שאם המעריך עני ונותן לפי השגת ידו אינו יוצא ידי חובתו בפחות משקל (סלע)!","\u0003אלא אמר אביי:\u0004 מטעם זה \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 התנא להשמיענו שכהנים מעריכים, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]\u0006 ביחס לפדיון הבן: \u0003\"ופדויו מבן חדש תפדה בערכך\u0004 כסף חמשת שקלים\" (במדבר יח, טז), היה מקום לומר כי \u0003כל דאיתיה\u0004 \u0005[שישנו]\u0006 \u0003ב\u0004חיוב \u0003פדיון הבן\u0004 — \u0003איתיה\u0004 \u0005[ישנו]\u0006 \u0003בערכין, והני\u0004 \u0005[ואותם]\u0006 \u0003כהנים, הואיל וליתנהו\u0004 \u0005[ואינם]\u0006 \u0003בפדיון הבן\u0004 — \u0003ליתנהו\u0004 \u0005[אינם]\u0006 \u0003בערכין,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 התנא, שגם הם בכלל ערכין.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אלא מעתה,\u0004 לשיטתך, שהיה מקום ללמוד כן מן המלה \"בערכך\" האמורה בפדיון הבן, \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003איל אשם,\u0004 שצריך להביא מי שגזל את חבירו ונשבע על כך לשקר, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"ואת אשמו יביא לה' איל תמים מן הצאן בערכך\"\u0004 (ויקרא ה, כה) — \u0003הכי נמי\u0004 \u0005[כך גם כן\u0006 נאמר\u0005]\u0006 \u0003דכל דאיתיה\u0004 \u0005[שכל שישנו]\u0006 \u0003בערכין איתיה\u0004 \u0005[ישנו]\u0006 \u0003באיל האשם,\u0004 ולכן \u0003טומטום ואנדרוגינוס דליתנהו\u0004 \u0005[שאינם]\u0006 \u0003בערכין, כמבואר במשנתנו\u0004 שאינם נערכים — \u0003ליתנהו\u0004 \u0005[אינם]\u0006 חייבים \u0003באיל האשם?\u0004 והרי אין חולק על כך שגם הם חייבים באיל אשם!","\u0003אלא אמר רבא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב אשי: איצטריך\u0004 \u0005[הוצרך]\u0006 להשמיענו שגם כהנים מעריכים, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]\u0006 בענין ערכין: \"ואם מך הוא מערכך \u0003והעמידו לפני הכהן\"\u0004 (ויקרא כז, ח), יש לדייק משם שמעמידים את העני לפני כהן — \u0003ולא\u0004 מעמידים \u0003כהן לפני כהן,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 התנא שגם כהנים חייבים בערכין.","ושבים למה שדייקנו בתחילת פרק זה, ש\"הכל \u0003נערכין\"\u0004 שנאמר במשנתנו בא \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003מנוול ומוכה שחין,\u0004 שמעריכים אותם לפי הערך הקצוב בתורה לפי גילם ומינם, למרות שאינם שווים מאומה בשוק. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה]?\u0006","ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \"איש כי יפליא נדר \u0003בערכך\u0004 נפשות לה' \" (ויקרא כז, ב) — \u0003להביא ערך סתום,\u0004 כלומר, שלא פירש ערכו של מי, אלא אמר סתם: \"הרי עלי ערך\". \u0003דבר אחר: \"בערכך\"\u0004 — \u0003ערך כולו הוא נותן ולא ערך אברים,\u0004 ואם אמר \"ערך ידי עלי\" — אינו נותן כלום.","\u0003יכול שאני מוציא אף דבר שהנשמה תלויה בו,\u0004 כגון שאמר: \"ערך כבדי עלי\"? \u0003תלמוד לומר:\u0004 \u0003\"נפשת\",\u0004 ואם העריך איבר שהנפש תלויה בו — חייב בכל הערך. ועוד דורשים: \u0003\"נפשת\"\u0004 — \u0003ולא המת,\u0004 ואם העריך את המת — פטור.","ועדיין יש לשאול: שמא \u0003אוציא\u0004 רק \u0003את המת, ולא אוציא\u0004 גם \u0003את הגוסס\u0004 העומד למות, שהרי הוא עדיין בכלל \"נפשות\"? \u0003תלמוד לומר: \"והעמיד... והעריך\"\u0004 (\"והעמידו לפני הכהן והעריך אותו הכהן\", שם פסוק ח) ומשם יש ללמוד כי \u0003כל שישנו בהעמדה,\u0004 שניתן להעמידו — \u0003ישנו בהערכה, וכל שאינו בהעמדה,\u0004 כגון גוסס שאינו מסוגל לעמוד — \u0003אינו בהערכה,\u0004 ולפיכך גם המעריך את הגוסס פטור.","\u0003דבר אחר: \"נפשת\"\u0004 מדוע נאמר בלשון רבים? שאם היה נאמר \"נפש\" \u0003אין לי\u0004 ללמוד \u0003אלא\u0004 על \u0003אחד שהעריך אחד, אחד שהעריך מאה מנין\u0004 שמביא ערך של כל אחד ואחד? \u0003תלמוד לומר: \"נפשת\",\u0004 בלשון רבים. \u0003דבר אחר:\u0004 מדוע נאמר \u0003\"נפשת\"\u0004 בלשון רבים?"],["\u0003אין לי\u0004 ללמוד \u0003אלא\u0004 על \u0003איש שהעריך\u0004 כל נפש, \u0003בין\u0004 שהנערך \u0003איש בין\u0004 שהוא \u0003אשה,\u0004 שהרי נאמר מתחילה \"איש כי יפליא נדר\" (ויקרא כז, ב), אבל \u0003אשה שהעריכה איש,\u0004 או \u0003אשה שהעריכה אשה, מנין\u0004 שמתחייבת? \u0003תלמוד לומר\u0004 מיד לאחר מכן: \"בערכך \u0003נפשת\"\u0004 (שם ב), ומקרא זה מרבה גם אשה בכלל המעריכים.","\u0003דבר אחר:\u0004 נאמר \u0003\"נפשת\"\u0004 — \u0003לרבות מנוול ומוכה שחין,\u0004 שמי שהעריכם חייב לשלם את הערך הקצוב לגילם.","\u0003ש\u0004כן \u0003יכול\u0004 היית ללמוד מן הביטוי \u0003\"נדר בערכך\"\u0004 (שם) האמור מתחילה, המקיש ערכין לנדרי דמים: \u0003כל שישנו בדמים,\u0004 שאם נדר את דמיו (כמה הוא שווה כעבד) חייב לשלם להקדש — \u0003ישנו בערכין, וכל שאינו ב\u0004נדר \u0003דמים,\u0004 כמנוול ומוכה שחין, שאין להם דמים — \u0003אינו בערכין,\u0004 על כן \u0003תלמוד לומר:\u0004 \"בערכך \u0003נפשת\",\u0004 לומר שכל שהוא נפש, שיש בו חיות — הריהו בכלל ערכין.","נאמר: \u0003\"והיה ערכך\"\u0004 (שם ג), ומביטוי זה, שהוא מיותר, למדים הויה נוספת — \u0003לרבות טומטום\u0004 (שסימני המין שלו מכוסים) ואנדרוגינוס (שיש לו סימני זכר ונקבה) \u0003לדמים,\u0004 שמי שנדר את דמיהם — חייב, למרות שאינם נערכים. \u0003שיכול\u0004 היית ללמוד מן הביטוי \u0003\"נדר בערכך\"\u0004 (שם ב) המקיש נדרים לערכין, ש\u0003כל שישנו ב\u0004דין \u0003ערכין\u0004 — \u0003ישנו ב\u0004דין נדר \u0003דמים, וכל שאינו בערכין\u0004 — \u0003אינו בדמים,\u0004 על כן \u0003תלמוד לומר: \"והיה ערכך\",\u0004 לרבות את הטומטום והאנדרוגינוס לדמים. ומנין שטומטום ואנדרוגינוס אינם בכלל הנערכים?","שנאמר \u0003\"הזכר\",\u0004 וה' הידיעה מדגישה: דוקא \u0003זכר, ולא טומטום ואנדרוגינוס.\u0004 \u0003יכול לא יהו\u0004 טומטום ואנדרוגינוס נערכים \u0003בערך איש, אבל יהיו בערך אשה? תלמוד לומר: \"והיה ערכך הזכר... ואם נקבה היא\"\u0004 (שם ג—ד), לומר: \u0003זכר ודאי, נקבה ודאית, ולא טומטום ואנדרוגינוס.\u0004","עד כאן לשון הברייתא, ומעתה מבררים אותה לפרטיה. \u0003אמר מר\u0004 \u0005[החכם]\u0006 בתחילת הברייתא: \"איש כי יפליא נדר \u0003בערכך\"\u0004 (ויקרא כז, ב) — \u0003לרבות ערך סתום.\u0004 ומבארים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003ערך סתום?\u0004","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003האומר \"ערך סתום עלי\",\u0004 שלא פירש ערכו של מי — \u0003נותן כפחות שבערכין, וכמה פחות שבערכין? שלשת שקלים,\u0004 שהוא ערכה של נקבה בת פחות מחמש שנים (שם ו).","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003חמשים\u0004 שקלים, כערך הגדול ביותר, של זכר מבן עשרים ועד בן ששים (שם ג)! ומשיבים, יש ללכת בענין זה אחרי הכלל: \u0003תפשתה מרובה\u0004 — \u0003לא תפשתה,\u0004 אבל \u0003תפשתה מועט\u0004 — \u0003תפשתה,\u0004 שהמרובה — ספק הוא, שמא הולכים אחר המועט, אבל המועט הוא ודאי, שהרי הוא בכלל המרובה.","ושואלים, \u0003ואימא\u0004 \u0005[ואמור]\u0006 שפחות שבערכין הוא \u0003שקל, דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"וכל ערכך יהיה בשקל הקדש\"\u0004 (שם כה)! ומשיבים: \u0003ההוא\u0004 \u0005[אותו\u0006 כתוב\u0005]\u0006 \u0003בהשג יד הוא דכתיב\u0004 \u0005[שנאמר],\u0006 שעני שהעריך אדם, ואין ידו משגת לשלם את ערכו — אינו נותן פחות משקל.","ושואלים: \u0003ואלא\u0004 הואיל וחיוב שלושה שקלים בערך סתום נלמד מן הסברה (\"תפשת מועט\"), \u0003קרא\u0004 \u0005[המקרא]\u0006 \"בערכך\" \u0003למה לי?\u0004 \u0003אמר רב נחמן אמר רבה בר אבוה: לומר, ש\u0004להבדיל משאר הערכים, שבהם עני שהשיגה ידו לתת שקל נותנו לכהן ויוצא ידי חובתו, הרי שמעריך ערך סתום \u0003אינו נידון בהשג יד,\u0004 וגם עני אינו יוצא ידי חובתו בפחות משלושה שקלים; \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 מפני ש\u0003כמפרש דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 כאילו אמר: \"הרי עלי שלושה שקלים\", שהרי הגדיר בעצמו את חובו, ולא נאמר דין השג יד אלא בנדר ערכין, שמקבל על עצמו ערך שקצבה התורה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 להיפך, \u0003אמר רב נחמן אמר רבה בר אבוה:\u0004 המקרא \"בערכך\" בא להשמיע שאף ערך סתום \u0003נידון בהשג יד,\u0004 ועני שהעריך ערך סתום, ואין ידו משגת לתת שלושה שקלים — נותן שקל, ויוצא ידי חובתו. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005]!\u0006 ומשיבים: \u0003מהו דתימא\u0004 \u0005[מהו שתאמר]\u0006 שהמעריך סתם \u0003כמפרש דמי\u0004 \u0005[נחשב],\u0006 כאילו אמר במפורש \"הרי עלי שלושה שקלים\", ולא יתן פחות, על כן \u0003קמשמע לן\u0004 \u0005[משמיע לנו]\u0006 שהוא כשאר המעריכים.","ועוד נאמר בברייתא, \u0003דבר אחר:\u0004 מה שנאמר \u0003\"בערכך\"\u0004 (ויקרא כז, ב), ומשמעו: ערך כולך, בא לומר: \u0003ערך כולו הוא נותן, ואינו נותן ערך דמי אברים,\u0004 שאם אמר \"ערך ידי עלי\" — אינו נותן כלום. ושואלים: \u0003והא אפיקתיה\u0004 \u0005[והרי הוצאת אותו,\u0006 למדת\u0005]\u0006 מ\"ערכך\" \u0003ל\u0004דין \u0003ערך סתם,\u0004 ואיך אפשר ללמוד ממנו דין נוסף? ומשיבים: \u0003קרי ביה\u0004 \u0005[קרא בו]\u0006 בלימוד זה \u0003\"ערך\" \"בערכך\",\u0004 שנלמד הדבר ממה שיכול היה לכתוב \"ערך\" ונכתב \"בערכך\".","וממשיכה הברייתא: \u0003יכול שאני מוציא\u0004 מכלל ערכין אפילו מעריך \u0003דבר\u0004 (איבר) \u0003שהנשמה תלויה בו,\u0004 כמו ראש? \u0003תלמוד לומר:\u0004 \"בערכך \u0003נפשת\",\u0004 ואם העריך איבר שהנשמה תלויה בו נותן ערך כולו. ועוד נאמר בברייתא: \u0003\"נפשת\"\u0004 — \u0003ולא את המת,\u0004 שהמעריך את המת פטור.","ושואלים: \u0003והא אפיקתיה\u0004 \u0005[והרי הוצאת אותו],\u0006 למדת כבר מכתוב זה שהמעריך איבר שהנשמה תלויה בו נותן ערך כולו! ומשיבים: \u0003קרי ביה\u0004 \u0005[קרא בו]\u0006 בלימוד זה: \u0003\"נפש\" \"נפשת\",\u0004 שנלמד הדבר ממה שיכול היה לכתוב \"נפש\" ונכתב \"נפשות\".","ועוד נאמר בברייתא: אם כן, \u0003אוציא את המת,\u0004 שאין בו נפש, \u0003ולא אוציא את הגוסס,\u0004 שהרי הוא חי עדיין! \u0003תלמוד לומר: \"והעמיד... והעריך\"\u0004 (\"והעמידו לפני הכהן והעריך אותו הכהן\", ויקרא כז, ח). ומשם יש ללמוד כי כל שניתן להעמידו כדי להעריכו — הריהו בדין ערכין, אבל גוסס שאינו יכול לעמוד — אינו נערך.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003מת נמי תיפוק לי\u0004\u0005[גם כן יצא,\u0006 יילמד\u0005]\u0006 \u0003מ\"והעמיד... והעריך\",\u0004 שהרי לא ניתן להעמידו, ולא הוצרך להילמד מ\"נפש\" \"נפשות\"! ומשיבים: \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 יש לומר למסקנה. ושואלים: \u0003ואלא,\u0004 הלימוד מ\u0003\"נפש\" \"נפשת\" למה לי,\u0004 למה הוא נצרך? ומשיבים: \u0003כדבעינן למימר קמן\u0004 \u0005[כפי שאנו רוצים לומר לפנינו]\u0006 בברייתא, שכך שנינו:","\u0003דבר אחר, \"נפשת\"\u0004 — אם היה כתוב רק \"נפש\" \u0003אין לי\u0004 ללמוד \u0003אלא\u0004 על \u0003אחד שהעריך אחד, אחד שהעריך מאה מנין\u0004 שחייב לתת את ערכי כולם? \u0003תלמוד לומר: \"נפשת\".\u0004","ועוד שנינו בברייתא: \u0003דבר אחר, \"נפשת\"\u0004 — \u0003אין לי אלא איש שהעריך, בין איש בין אשה, אשה שהעריכה איש, ו\u0004כן \u0003אשה שהעריכה אשה, מנין\u0004 שחייבת? \u0003תלמוד לומר: \"נפשת\",\u0004 לרבות אשה בכלל המעריכים.","\u0003דבר אחר: \"נפשת\"\u0004 — \u0003להביא מנוול ומוכה שחין,\u0004 שהמעריכם חייב, למרות שאינו שווה מאומה, שהרי על כל פנים הריהם בכלל \"נפש\". ושואלים: \u0003והא אפיקתיה להנך\u0004 \u0005[והרי\u0006 כבר \u0005הוצאת אותו,\u0006 את \"נפשות\", \u0005לאלו],\u0006 ללמד על אחד שהעריך מאה, ועל כך שגם אשה מעריכה!","ומשיבים: \u0003הנך לא צריכי קרא\u0004 \u0005[אלו אינם צריכים מקרא\u0006 נוסף\u0005],\u0006 \u0003מאי טעמא\u0004 \u0005[\u0006ו\u0005מה הטעם]?\u0006 \u0003כי שקול הוא,\u0004 כל אחד מלימודים אלו לחבירו, ואי אפשר להעדיפו, \u0003ו\u0004לכן \u0003יבואו כולם\u0004 ממה שנאמר \"נפש\", \u0003כי איצטריך קרא\u0004 \u0005[\u0006ו\u0005כאשר נצרך המקרא\u0006 של \"נפשות\"\u0005]\u0006 — \u0003למנוול ומוכה שחין הוא דאצטריך\u0004 \u0005[שנצרך].\u0006","עוד שנינו בברייתא: נאמר \u0003\"והיה ערכך\"\u0004 (שם ג), והמלה \"והיה\" באה \u0003לרבות טומטום ואנדרוגינוס לדמים,\u0004 כלומר, שהנודר את דמיהם — חייב, למרות שאינם נערכים. ושואלים: לנודר \u0003דמים\u0004 של טומטום או אנדרוגינוס למה לי קרא \u0005[מקרא]?\u0006 \u0003לא יהא אלא דמי דיקלא\u0004 \u0005[דקל],\u0006 \u0003אילו אמר \"דמי דיקלא\u0004 \u0005[דקל]\u0006 עלי\", \u0003מי לא יהיב\u0004 \u0005[האם אינו נותן\u0006 דמיו\u0005]?\u0006","\u0003אמר רבא:\u0004 כתוב זה בא \u0003לומר ש\u0004טומטום ואנדרוגינוס \u0003נידון בכבודו,\u0004 שאם אמר: \"דמי ראשו עלי\", או דמיו של איבר חשוב אחר, שחייו של הטומטום תלויים בו — נותן דמי כולו.","שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 הרי \u0003\"נדר בערכך\"\u0004 (שם) \u0003כתיב\u0004 \u0005[נאמר],\u0006 ובכך הוקשו נדרי דמים לדיני ערכין, ואם כן נאמר ש\u0003כל שישנו ב\u0004דין \u0003ערכין\u0004 — \u0003נידון בכבודו,\u0004 גם כשנודר נדר דמים, \u0003וכל שאינו בערכין,\u0004 כגון טומטום ואנדרוגינוס — \u0003אינו נידון בכבודו\u0004 כשנודר דמי איבר שהנשמה תלויה בו, לכן משמיע הכתוב שגם טומטום או אנדרוגינוס, שאינו בדין ערכין — נידון בכבודו בנדר דמים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבא: \u0003ודלא איתיה\u0004 \u0005[ו\u0006מי \u0005שאינו]\u0006 \u0003בערכין, מי\u0004 \u0005[האם]\u0006 באמת \u0003נידון בכבודו? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 מי שאמר \u0003\"ראש עבד זה הקדש\"\u0004 — \u0003הוא והקדש שותפין בו\u0004 בעבד כולו, וכן אם אמר לחבירו: \u0003\"ראש עבד מכור לך\"\u0004 — \u0003משמנין,\u0004 עושים שומה כמה שווה העבד, ומחלקים \u0003ביניהם\u0004 את דמיו. \u0003\"ראש חמור זה הקדש\"\u0004 — \u0003הוא והקדש שותפין בו, \"ראש חמור מכור לך\"\u0004 — \u0003משמנין ביניהם.\u0004","אבל אם אמר לחבירו: \u0003\"ראש פרה מכור לך\"\u0004 — \u0003לא מכר\u0004 לו \u0003אלא ראשה של פרה. ולא עוד, אלא אפילו\u0004 אמר: \u0003\"ראש פרה הקדש\"\u0004 — \u0003אין להקדש אלא ראשה. ואמר רב פפא\u0004 בטעם הדבר: \u0003דהא מזדבן רישא דתורא בבי טבחא\u0004 \u0005[שהרי נמכר ראש של שור בבית המטבחיים]\u0006 בפני עצמו.","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003חמור ופרה ליתנהו\u0004 \u0005[אינם]\u0006 \u0003ב\u0004דין \u0003ערכין, ואין נידון בכבודו,\u0004 שאם הקדיש את ראשם — אין כל גופם קדוש! אמר לו רבא לאביי: \u0003וליטעמיך\u0004 \u0005[ולשיטתך],\u0006 שאתה מוכיח מכאן שכל מי שאינו בערכין אינו נידון בכבודו, \u0003תיקשי\u0004 \u0005[יקשה]\u0006 \u0003לך עבד, דאיתיה\u0004 \u0005[ש\u0006הרי \u0005ישנו]\u0006 \u0003בערכין,\u0004 כפי ששנינו במשנתנו, \u0003ו\u0004גם לגביו שנינו בברייתא ש\u0003אין\u0004 הוא \u0003נידון בכבודו!\u0004","\u0003אלא לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו],\u0006 שהמקדיש ראש עבד (או ראש חמור) אינו משלם דמי כולו — עוסקת \u0003בקדשי מזבח,\u0004 וכגון שהקדיש את ראשו כדי לקנות בדמיו קרבן, ואילו \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו],\u0006 שהמקדיש דמי ראש טומטום משלם כל שוויו — עוסקת \u0003בקדשי בדק הבית,\u0004 שהקדיש דמי ראשו לצרכי המקדש, והוא נידון בכבודו, כדין ערכין, שדמיהם ניתנים לקדשי בדק הבית.","ושאל אביי את רבא: \u0003במאי אוקימתה\u0004 \u0005[במה העמדת אותה],\u0006 את הברייתא במקדיש ראש עבד, \u0003בקדשי מזבח? אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 שנאמר בה: \u0003ולא עוד, אלא אפילו אמר \"ראש פרה זו הקדש\"\u0004 — \u0003אין להקדש אלא ראשה,\u0004 ולשיטתך, שמדובר בקדשי מזבח, \u0003אמאי\u0004 \u0005[מדוע]\u0006 לא הוקדש אלא ראשה? \u0003תפשוט קדושה בכולה! מי לא תניא\u0004 \u0005[האם לא שנויה\u0006 ברייתא\u0005]:\u0006 \u0003האומר\u0004"],["\u0003\"רגלה של\u0004 בהמה \u0003זו עולה\",\u0004 \u0003יכול תהא כולה עולה? תלמוד לומר:\u0004 \"ואם בהמה אשר יקריבו ממנה קרבן לה' \u0003כל אשר יתן ממנו לה' יהיה קדש\"\u0004 (ויקרא כז, ט), מה שהוא נותן \u0003ממנו\u0004 הריהו \u0003קודש, ולא כולה קודש.\u0004","\u0003יכול\u0004 יפדה את רגלה ו\u0003תצא לחולין? תלמוד לומר: \"יהיה\"\u0004 — \u0003בהוייתה תהא,\u0004 שלא ניתן לפדות את הרגל מיד המזבח. \u0003הא כיצד\u0004 ייעשה בה? \u0003תמכר\u0004 הבהמה \u0003לצורכי עולות,\u0004 לאנשים שחייבים קרבן עולה, כדי שיקריבוה, \u0003ודמיה חולין, חוץ מדמי אותו אבר שבה,\u0004 שאינו יכול לפדותו, אלו \u0003דברי ר' מאיר.\u0004","\u0003ר' יהודה ור' יוסי ור' שמעון אומרים: מנין לאומר \"רגלה של זו עולה\", שכולה עולה? תלמוד לומר: \"כל אשר יתן ממנו לה' יהיה קדש\",\u0004 ומה שנאמר \"יהיה\" בא \u0003לרבות את כולה.\u0004 הרי שבקדשי מזבח, אם הקדיש איבר אחד — פושטת הקדושה בכולה.","\u0003ואפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר,\u0006 ר' מאיר\u0005]\u0006 שאם אמר \"רגלה של זו עולה\" \u0003אין כולה עולה, הני מילי דאקדיש\u0004 \u0005[דברים אלו\u0006 אמורים \u0005כשהקדיש]\u0006 \u0003דבר שאין הנשמה תלויה בו,\u0004 כגון רגלה, \u0003אבל\u0004 כשהקדיש \u0003דבר שהנשמה תלויה בו,\u0004 כגון ראשה — \u0003קדשה כולה.\u0004 ולדברי רבא, שהברייתא בענין מקדיש ראש עבד ופרה מדברת בקדשי מזבח, מדוע כשהקדיש ראש פרה לא קדשה כולה?","\u0003אלא,\u0004 ענה רבא לאביי: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 אף שבשני המקרים מדובר בקדשי מזבח, \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו],\u0006 שעולה ממנה שאם מקדיש ראש בהמה קדשה כולה — עוסקת \u0003בקדושת הגוף,\u0004 שמקדיש את הראש עצמו למזבח, \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו],\u0006 שהמקדיש ראש פרה לא קדשה כולה — עוסקת \u0003בקדושת דמים,\u0004 וכגון שאמר: \"דמי ראש פרה זו עלי לקרבן\".","אמר לו אביי לרבא: \u0003והא מר\u0004 \u0005[והרי אדוני]\u0006 \u0003הוא\u0004 ש\u0003אמר: מקדיש זכר\u0004 (איל) \u0003לדמיו,\u0004 כלומר, לדמי עולה — \u0003קדוש קדושת הגוף,\u0004 וקרב בעצמו, למרות שהקדישו לדמיו, שכיון שהוא ראוי להקרבה אינו יוצא מידי המזבח. ואם כן, גם אם מקדיש ראש פרה לדמיו — יקדש לגופו, שהרי הפרה ראויה להקרבה, ותתפשט הקדושה בכולה, ומדוע נאמר בברייתא שאין להקדש אלא ראשה?","השיב רבא לאביי: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[\u0006דין \u0005זה],\u0006 שקדושת הגוף חלה על הבהמה למרות שהקדישה לדמיה, הוא במקרה \u0003דאקדיש\u0004 \u0005[שהקדיש]\u0006 את הבהמה \u0003כולה\u0004 לדמי קרבן, ומתוך שנתקדשה כולה לדמיה, חלה עליה קדושת הגוף. אבל \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו,\u0006 של המקדיש ראש פרה\u0005],\u0006 עוסקת במקרה \u0003דאקדיש חד אבר\u0004 \u0005[שהקדיש\u0006 רק \u0005איבר אחד],\u0006 ואין אומרים שמתוך שקדש איבר אחד לדמיו — תחול קדושת הגוף על הבהמה כולה.","אמר אביי לרבא: \u0003חד אבר נמי איבעויי איבעיא לן\u0004 \u0005[\u0006והרי \u0005איבר אחד גם כן נשאל לנו],\u0006 \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003רבה: הקדיש אבר לדמיו, מהו?\u0004 האם חלה קדושת הגוף על כל הבהמה? ואם כדבריך, שהברייתא מדברת במקדיש איבר לדמיו, מדוע לא פשט רבה משם שאינו קדוש ליקרב כולו?","השיב רבא לאביי: \u0003כי איבעי לן\u0004 \u0005[כאשר נשאלה לנו]\u0006 שאלה זו, היה זה \u0003ב\u0004מקדיש איבר של בעל חיים \u0003תם,\u0004 שגופו ראוי ליקרב על המזבח, ובזה יש לומר שמתוך שחלה עליו קדושת דמים למזבח — כל גופו קדוש להקרבה. אבל \u0003הכא\u0004 \u0005[כאן,\u0006 בברייתא\u0005]\u0006 מדובר \u0003ב\u0004מקדיש ראש של \u0003בעל מום,\u0004 שאינו ראוי ליקרב, \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003חמור,\u0004 שהושווה אליו דינה של הפרה. והואיל והקדיש דמיו של דבר שאינו ראוי להקרבה — אין לומר שתחול עליו קדושת דמים.","שאל אביי: והרי דינו של \u0003בעל מום\u0004 שאינו ראוי ליקרב \u0003נמי איבעויי איבעיא לן\u0004 \u0005[גם כן נשאל לנו],\u0006 \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003רבה,\u0004 מי שאמר: \"הרי עלי \u0003דמי ראשי לגבי מזבח\", מהו?\u0004 האם יביא קרבן מדמי כולו? והרי אדם ודאי אינו עומד להקרבה, ולא פשט רבה את שאלתו מן הברייתא! השיב רבא לאביי: \u0003כי אבעיא לן\u0004 \u0005[כאשר נשאלה לנו\u0006 שאלה זו\u0005]\u0006 היה זה \u0003מקמי דאשמעה להא מתניתא\u0004 \u0005[לפני ששמע\u0006 רבה \u0005את הברייתא הזו],\u0006 \u0003השתא דשמעה הא מתניתא לא מיבעיא לן\u0004 \u0005[עכשיו ששמע את הברייתא הזו לא נשאלה לנו],\u0006 ואינו מביא בדמי כולו.","ומביאים את \u0003גופא\u0004 \u0005[גופה]\u0006 של שאלת רבה שהוזכרה לעיל. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבה: \"דמי ראשי לגבי מזבח\", מהו?\u0004 האם \u0003נידון בכבודו,\u0004 והואיל והקדיש איבר שהנשמה תלויה בו התחייב בדמי כולו, \u0003או אינו נידון בכבודו,\u0004 ולא הקדיש אלא דמי ראשו?","ומסבירים את הספק: מצד אחד, הרי \u0003לא אשכחן\u0004 \u0005[לא מצאנו]\u0006 \u0003ב\u0004הקדש \u0003דמים\u0004 שאם הקדיש איבר חשוב \u0003אינו נידון בכבודו,\u0004 ולכן ישלם דמי כולו, \u0003או דלמא\u0004 \u0005[שמא]\u0006 נאמר: הרי \u0003לא אשכחן\u0004 \u0005[לא מצאנו]\u0006 \u0003לגבי\u0004 הקדש ל\u0003מזבח\u0004 דין \u0003נידון בכבודו,\u0004 ולכן ישלם לפי דמי ראשו? לשאלה זו לא נמצא פתרון, ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","ועוד \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 האומר \u0003\"ערכי עלי לגבי מזבח\",\u0004 ולא לבדק הבית, כסתם ערכין, \u0003מהו?\u0004 האם \u0003נידון בהשג יד,\u0004 כלומר, אם הוא עני, האם נותן לפי השג ידו ודי בכך, \u0003או אין נידון בהשג יד\u0004 וחייב לשלם כשיעשיר?","ומסבירים את הספק: מצד אחד, הרי \u0003לא אשכחן\u0004 \u0005[לא מצאנו]\u0006 \u0003בערכין\u0004 מקרה ש\u0003אין נידון בהשג יד,\u0004 ולכן גם כשהעריך למזבח יחול דין זה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 נאמר: הרי \u0003לא אשכחן\u0004 \u0005[לא מצאנו]\u0006 בנודרים \u0003לגבי מזבח דמיפריק\u0004 \u0005[ש\u0006דבר \u0005נפדה]\u0006 \u0003אלא בשויו?\u0004 שאלה זו לא נפתרה, ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי\u0004 שאלה דומה: \u0003הקדיש שדה אחוזה לגבי מזבח,\u0004 ולא כסתם הקדשות, שהם לבדק הבית, \u0003מהו? מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003לא אשכחן\u0004 \u0005[לא מצאנו]\u0006 \u0003שדה אחוזה דמיפרקא\u0004 \u0005[שנפדית]\u0006 בשוויה, \u0003אלא\u0004 לפי הערך הקצוב בתורה: \u0003בית זרע חומר שעורים\u0004 (שטח הראוי לזריעת שלושים סאה שעורים) \u0003בחמשים שקל כסף\u0004 (ויקרא כז, טז). \u0003או דלמא\u0004 \u0005[שמא]\u0006 מצד אחר, הרי \u0003לא אשכחן\u0004 \u0005[לא מצאנו]\u0006 דבר הקדוש \u0003לגבי מזבח דמיפריק\u0004 \u0005[שנפדה]\u0006 \u0003אלא בשויו\u0004 האמיתי? שאלה זו לא נפתרה ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","תינוק \u0003פחות מבן חדש נידר,\u0004 שאם אמר: \"דמי תינוק זה עלי\" — חייב לתת להקדש את שוויו, כאילו היה נמכר בשוק. \u0003אבל לא נערך,\u0004 שאם אמר: \"ערכו של תינוק זה עלי\" — פטור מלשלם, מפני שלא הוזכר בתורה ערך למי שהוא פחות מבן חודש.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המעריך פחות מבן חדש,\u0004 שאמר: \"ערכו של פחות מבן חודש עלי\" — \u0003ר' מאיר אומר: נותן דמיו, וחכמים אומרים: לא אמר כלום.\u0004","ומבררים: \u0003במאי קמיפלגי\u0004 \u0005[במה הם חולקים]?\u0006 \u0003ר' מאיר סבר\u0004 \u0005[סבור]:\u0006 \u0003אין אדם מוציא דבריו לבטלה,\u0004 ואנו מניחים כי הוא \u0003יודע שאין\u0004 דין \u0003ערכין לפחות מבן חדש, ו\u0004לפיכך \u0003גמר\u0004 בלבו \u0003ואמר\u0004 דבריו \u0003לשם דמים,\u0004 כלומר, שנודר להקדש את דמיו; \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003אדם מוציא דבריו לבטלה,\u0004 ונתכוון למה שאמר, ולכן הוא פטור.","ומעירים: לפי זה, \u0003כמאן אזלא הא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת\u0006 שמועה \u0005זו]\u0006 ש\u0003אמר רב גידל אמר רב: האומר \"ערך כלי עלי\" נותן דמים\u0004 — \u0003כר' מאיר,\u0004 הסבור שאין אדם מוציא דבריו לבטלה, וכיון שאין בתורה דין ערך לכלי — גמר בלבו להתחייב בדמיו. ותמהים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005] ששמועה זו\u0006 \u0003כר' מאיר אתיא\u0004 \u0005[באה,\u0006 הולכת\u0005],\u0006 ולא הוצרך הדבר להיאמר!","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 ששמועה זו \u0003אפילו כרבנן\u0004 \u0005[כ\u0006שיטת \u0005חכמים],\u0006 הפוטרת את המעריך פחות מבן חודש, שיש לומר: \u0003התם הוא דטעי\u0004 \u0005[שם הוא\u0006 שהם פוטרים, מפני \u0005ש\u0006הוא \u0005טועה],\u0006 \u0003סבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003כי היכי דאיכא\u0004 \u0005[כשם שיש]\u0006 \u0003ערכין לבן חודש\u0004 — \u0003איכא נמי\u0004 \u0005[יש גם כ8ן]\u0006 ערך \u0003לפחות מבן חודש,\u0004 ונדר של טעות אינו נדר.","\u0003אבל הכא\u0004 \u0005[כאן]\u0006 במעריך כלי \u0003דליכא למיטעי\u0004 \u0005[שאין\u0006 מקום \u0005לטעות],\u0006 היה מקום לומר: \u0003ודאי אדם יודע שאין ערך לכלי, וגמר\u0004 בלבו \u0003ואמר\u0004 דבריו \u0003לשם דמים,\u0004 על כן \u0003קמשמע לן\u0004 \u0005[משמיע לנו]\u0006 שלא נאמרו דברי רב אלא לשיטת ר' מאיר, אבל חכמים סבורים כי באופן עקרוני אנו מניחים שאדם הנודר מוציא דבריו לבטלה, ופטור לגמרי."],["ושואלים: \u0003ו\u0004הואיל ורב הולך \u0003ל\u0004שיטת \u0003ר' מאיר,\u0004 שמעריך פחות מבן חודש נותן את דמיו, \u0003למאי איצטריך\u0004 \u0005[ל\u0006שם \u0005מה הוצרך]\u0006 להשמיענו שהמעריך כלי גם כן מתחייב בדמיו? והרי פשוט הדבר לשיטתו!","ומשיבים: יש בכך צורך, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003טעמא דר' מאיר התם\u0004 \u0005[\u0006\u0005טעמו של ר' מאיר שם],\u0006 בענין המעריך פחות מבן חודש, אינו מפני שאדם אינו מוציא דבריו לבטלה, אלא מפני \u0003דגזר\u0004 \u0005[\u0006\u0005ש\u0006הוא \u0005גוזר]\u0006 לחייב את המעריך תינוק \u0003פחות מבן חודש, אטו\u0004 \u0005[משום]\u0006 המעריך תינוק \u0003בן חודש,\u0004 שלא יטעו לפטור גם מי שהעריך בן חודש, שיש לו דין ערכין, \u0003אבל הכא דליכא למיגזר\u0004 \u0005[כאן,\u0006 במעריך כלי, \u0005שאין\u0006 צורך \u0005לגזור],\u0006 שהרי אין מקום לטעות, \u0003אימא לא\u0004 \u0005[אמור שאינו\u0006 מחייבו\u0005],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 רב: \u0003טעמא\u0004 \u0005[טעמו]\u0006 של \u0003ר' מאיר\u0004 שחייב את המעריך פחות מבן חודש, הוא מפני ש\u0003אין אדם מוציא דבריו לבטלה,\u0004 ולכן \u0003לא שנא הכא ולא שנא הכא\u0004 \u0005[לא שונה\u0006 הדין \u0005כאן ולא שונה\u0006 הדין \u0005כאן].\u0006","ועוד מעירים: \u0003כמאן אזלא הא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת\u0006 שמועה \u0005זו]\u0006 ש\u0003אמר רבה בר יוסף אמר רב, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר רב ייבא בר יוסי אמר רב: המקדיש בהמת חבירו\u0004 — \u0003נותן דמיה? כמאן\u0004 \u0005[כמי]\u0006 — \u0003כר' מאיר\u0004, הסבור שאין אדם מוציא דבריו לבטלה, וכיון שיודע שאינו יכול להקדיש דבר שאינו שלו — התכוון לתת דמיה.","ושואלים: \u0003הא\u0004 \u0005[הרי]\u0006 כבר \u0003אמרה רב חדא זימנא\u0004 \u0005[פעם אחת],\u0006 ש\u0003אמר רב גידל אמר רב: האומר \"ערך כלי עלי\"\u0004 — \u0003נותן דמיו!\u0004 ומשיבים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 שנאמר דין זה, מפני שאדם \u0003יודע שאין ערך לכלי,\u0004 שאינו בכלל ערכין, \u0003ו\u0004לכן \u0003גמר ואמר לשם דמים.\u0004","\u0003אבל\u0004 במקדיש \u0003בהמה, דבת מיקדש היא\u0004 \u0005[שהיא בת הקדשה],\u0006 \u0003איכא למימר דהכי קאמר\u0004 \u0005[יש לומר שכך הוא אומר\u0006 בלבו\u0005]\u0006 בשעה שהוא מקדיש אותה: אי אמינא לה למרה מזבין לה ניהלי, תיקדוש לה מהשתא ואקרבה \u0005[\u0006הואיל ו\u0005אם אומר לבעליה ימכור אותה לי,\u0006 לכן \u0005תתקדש לה מעכשיו, ואקריבנה]\u0006 כשאקנה אותה ממנו. וכוונתו להקדיש את גופה להקרבה, \u0003אבל דמי לא קאמר\u0004 \u0005[\u0006לתת \u0005דמיה לא אמר\u0006 בלבו\u0005],\u0006 והואיל ואין אדם יכול להקדיש דבר שאינו ברשותו — אין בדבריו כלום. על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו\u0006 רב\u0005]\u0006 שאין אומרים כן, אלא יש לפרש את דבריו כמתכוון לתת להקדש את דמיה.","\u0003אמר רב אשי: ו\u0004דין זה \u0003הוא\u0004 כש\u0003אמר\u0004 \"בהמה זו של חברי \u0003עלי\u0004 הקדש\", \u0003אבל אומר: \"הרי\u0004 בהמה \u0003זו\u0004 הקדש\" — \u0003לא\u0004 התחייב בדמיה, מפני שלשון זו מורה שכוונתו להקדיש בהמה זו עצמה, וכאמור, אינו יכול להקדישה קודם שתגיע לידיו.","\u0003נכרי\u0004 — \u0003ר' מאיר אומר: נערך,\u0004 שאם אומר ישראל \"ערכו של נכרי זה עלי\" — משלם את הערך האמור בתורה לפי גילו ומינו של הנכרי, \u0003אבל לא מעריך,\u0004 שאם מעריך הנכרי את עצמו או את אחרים — אינו מתחייב. \u0003ר' יהודה אומר\u0004 להיפך: הנכרי \u0003מעריך\u0004 את ישראל ומתחייב בערכו, \u0003אבל לא נערך,\u0004 שאם העריך את עצמו, או אדם אחר העריכו — הריהו פטור. \u0003וזה וזה,\u0004 גם ר' מאיר וגם ר' יהודה, \u0003מודים ש\u0004נכרים \u0003נודרין\u0004 דמיו של אדם להקדש, \u0003ונידרין,\u0004 שאם אמר אדם: \"דמי נכרי זה עלי\" — נותן את דמיו.","בטעמם של ר' מאיר ושל ר' יהודה שבמשנה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר בתורה בתחילת פרשת הערכין: \"דבר אל בני ישראל\" (ויקרא כז, ב), ומכאן יש ללמוד כי \u0003בני ישראל מעריכין ואין הגוים מעריכין;\u0004","\u0003יכול לא יהו\u0004 הגוים \u0003נערכין? תלמוד לומר: \"איש\u0004 כי יפליא נדר\" (שם), שמשמעו — כל איש, אפילו נכרי. אלו \u0003דברי ר' מאיר.\u0004","\u0003אמר ר' מאיר: וכי מאחר שמקרא אחד\u0004 (\"איש\") \u0003מרבה\u0004 אף נכרי, \u0003ומקרא אחד\u0004 (\"בני ישראל\") \u0003ממעט\u0004 את הנכרי, \u0003מפני מה אני אומר\u0004 שהנכרי \u0003נערך ולא מעריך?\u0004","\u0003מפני שריבה הכתוב ב\u0004מספר ה\u0003נערכין יותר מב\u0004 מספר ה\u0003מעריכין, שהרי,\u0004 כפי ששנינו בראש המסכת (ב,א) \u0003חרש שוטה וקטן נערך\u0004 על ידי אחרים, \u0003אבל לא מעריכין.\u0004","\u0003ר' יהודה אומר:\u0004 כך יש לדרוש את הכתוב \"דבר אל בני ישראל\" — \u0003בני ישראל נערכין ואין הגוים נערכין; יכול לא יהו\u0004 הגוים \u0003מעריכין? תלמוד לומר: \"איש\".\u0004","\u0003אמר ר' יהודה: וכי מאחר שמקרא אחד מרבה ומקרא אחד ממעט, מפני מה אני אומר נכרי מעריך ולא נערך? מפני שריבה הכתוב במעריכין יותר מבנערכין, שהרי,\u0004 כפי ששנינו בראש המסכת (ב,א) \u0003טומטום ואנדרוגינוס מעריכין אבל לא נערכין.\u0004","\u0003אמר רבא: הלכתיה דר' מאיר מסתברא, טעמיה לא מסתברא\u0004 \u0005[הלכתו של ר' מאיר מסתברת,\u0006 אבל \u0005טעמו\u0006 שהביא לדבריו \u0005אינו מסתבר], ד לעומת זאת\u0006 \u0003טעמא דר' יהודה מסתברא, הלכתיה לא מסתברא\u0004 \u0005[הטעם\u0006 שהביא \u0005ר' יהודה\u0006 לדבריו \u0005מסתבר,\u0006 אבל \u0005הלכתו לא מסתברת].\u0006","ומסביר רבא: \u0003הלכתיה דר' מאיר מסתברא\u0004 \u0005[הלכתו של ר' מאיר,\u0006 שגוים אינם מעריכים, \u0005מסתברת]\u0006 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 על ידי עולי בבל לשכניהם הגוים, כשהציעו לעזור להם בבנין המקדש: \u0003\"לא לכם ולנו לבנות את בית אלהינו\"\u0004 (עזרא ד, ג), ולפיכך מסתבר שאינם נודרים נדרי ערכין, המיועדים לבדק הבית. אבל \u0003טעמיה לא מסתברא\u0004 \u0005[טעמו\u0006 שהביא לדבריו \u0005לא מסתבר],\u0006 \u0003דקא מייתי ליה\u0004 \u0005[שהוא מביא,\u0006 לומד \u0005אותו]\u0006 \u0003מחרש שוטה וקטן\u0004 שאינם מעריכים, שהרי \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003חרש שוטה וקטן\u0004 שאינם מעריכים, כפי שאינם נודרים, מפני \u0003דלאו בני דעה נינהו\u0004 \u0005[שאינם בני דעה],\u0006 אבל נכרי גדול — הרי יש לו דעת ונדריו חלים.","לעומת זאת, \u0003טעמא דר' יהודה מסתברא\u0004 \u0005[הטעם\u0006 שהביא \u0005ר' יהודה מסתבר],\u0006 \u0003דקא מייתי ליה\u0004 \u0005[שהוא מביא,\u0006 לומד, \u0005אותו]\u0006 \u0003מטומטום ואנדרוגינוס, דאף על גב דבני דעה נינהו מעטינהו רחמנא\u0004 \u0005[שאף על פי שבני דעה הם, מיעטה אותם התורה]\u0006 ואינם נערכים, ויש לדמות להם את הגוים שאף הם לא יהיו נערכים. אבל \u0003הלכתיה לא מסתברא\u0004 \u0005[הלכתו לא מסתברת],\u0006 שאמר שהם מעריכים, \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"לא לכם ולנו לבנות את בית אלהינו\",\u0004 ומשמע שאין הם נותנים דבר לבדק הבית.","ושואלים: \u0003ור' יהודה,\u0004 האומר שגוים מעריכים, והדמים ניתנים לבדק הבית, \u0003האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003\"לא לכם ולנו\", מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה בו]?\u0006 \u0003אמר רב חסדא אמר אבימי:\u0004 מפסוק זה הוא למד, שכשהגוי דמעריך, \u0003ו\u0004מביא את הדמים למקדש — \u0003ערכו נגנז,\u0004 ואין משתמשים בו.","ושואלים: \u0003אלא מעתה,\u0004 שלא ניתן לעשות בו דבר לטובת ההקדש — \u0003לא ימעלו בו,\u0004 שמי שנהנה בשוגג מכסף זה לא יתחייב בקרבן מעילה, שהרי אין להקדש כל הנאה ממנו; \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו]:\u0006 \u0003חמש חטאות המתות,\u0004 כלומר, חטאות שאסור להקריבן וממתינים שימותו, \u0003ו\u0004כן \u0003מעות\u0004 הקדש \u0003ההולכות לים המלח,\u0004 כדי שיכלו שם, מפני שלא ניתן לעשות בהן דבר — \u0003לא נהנין\u0004 מהן \u0003ולא מועלין\u0004 בהן, כלומר, אסור לאדם ליהנות מהן, אך אם נהנה אינו מביא קרבן מעילה, מפני שאין להקדש הנאה מהם!","\u0003אלמה תניא\u0004 \u0005[מדוע שנויה\u0006 ברייתא\u0005]\u0006 ל\u0003גבי קדשי גוים,\u0004 ששנינו שאין בהם דין מעילה: \u0003במה דברים אמורים\u0004 — \u0003בקדשי מזבח, אבל בקדשי בדק הבית מועלין בהן?\u0004 והלא כל שהקדיש הנכרי לבדק הבית נגנז!","\u0003אלא אמר רבא:\u0004 לשיטת ר' יהודה, ערכו של הגוי ניתן לבדק הבית, ואינו נגנז. ומה שנאמר לגוים בימי עזרא \"לא לכם ולנו\", \u0003משום רפיון ידים הוא,\u0004 כלומר, מפני שהיה בכך כדי לרפות את ידי עולי בבל מבנין המקדש, \u0003דכתיב\u0004 \u0005[\u0006כפי \u0005שנאמר\u0006 שם\u0005]:\u0006 \u0003\"ויהי עם הארץ מרפין ידי עם יהודה ומבהלים אותם לבנות\"\u0004 (עזרא ד, ד)."],["בענין נדרי גוים לבדק הבית נמצאת לכאורה סתירה, שכן \u0003תנא חדא\u0004 \u0005[שנה\u0006 בברייתא \u0005אחת]:\u0006 \u0003גוי שהתנדב נדבה\u0004 על מנת שתינתן \u0003לבדק הבית\u0004 — \u0003מקבלים הימנו, ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003אין מקבלין\u0004 הימנו!","\u0003אמר ר' אילא אמר ר' יוחנן: לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003הא\u0004 \u0005[זה,\u0006 שאין מקבלים מהם\u0005] —\u0006 \u0003בתחילה,\u0004 כלומר, בתחילת בנין הבית, כדי שלא לסמוך עליהם. \u0003הא\u0004 \u0005[זה,\u0006 שמקבלים מהם\u0005]\u0006 — \u0003בסוף,\u0004 כלומר, לאחר שכבר נבנה.","שאמר ר' אסי אמר ר' יוחנן: בתחילה, \u0003אפילו\u0004 נדבו \u0003מים ומלח\u0004 לצורך בדק הבית — \u0003אין מקבלין מהם. בסוף,\u0004 אם נדב \u0003דבר המסויים,\u0004 מוגדר, שניכר שהוא מן הגוי — \u0003אין מקבלין\u0004 ממנו, נדב \u0003דבר שאינו מסויים\u0004 — \u0003מקבלין\u0004 ממנו. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003דבר המסויים? אמר רב יוסף: כגון אמה כליא עורב,\u0004 מתקן שבנו על גג ההיכל כדי לגרש את העורבים.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב יוסף\u0004 על מה שנאמר שאין מקבלים מהם דבר בתחילה, ממה שביקש נחמיה ממלך פרס: \u0003\"ואיגרת אל אסף שומר הפרדס אשר למלך\u0004 אשר יתן לי עצים לקרות את שערי הבירה אשר לבית\" (נחמיה ב, ח)! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: שאני מלכותא, דלא הדרא ביה\u0004 \u0005[שונה המלכות, שאינה חוזרת בה],\u0006 כפי ש\u0003אמר שמואל: אי אמר מלכותא \"עקרנא טורי\", עקר טורי ולא הדר ביה\u0004 \u0005[אם אומרת המלכות אעקור הרים, עוקרת הרים ולא חוזרת בה].\u0006","\u0003אמר רב יהודה אמר רב: גוי שהפריש תרומה מכריו\u0004 (מערימת התבואה שלו), \u0003בודקין אותו\u0004 למה בדיוק התכוון, \u0003אי בדעת ישראל הפרישה,\u0004 שינהגו בה כתרומה של ישראל — \u0003תינתן לכהן, ואם לאו\u0004 — \u0003טעונה גניזה, חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא בלבו לשמים\u0004 ולא לתיתה לכהן, ומספק לא ניתן לעשות עמה דבר.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו ברייתא: \u0003גוי שהתנדב קורה\u0004, והביאה לבית הכנסת, \u0003ושם\u0004 ה' \u0003כתוב עליה\u0004 — \u0003בודקין אותו\u0004 למה היתה כוונתו, \u0003אם אמר: בדעת ישראל הפרשתיה,\u0004 כשם שישראל תורם — \u0003יגוד,\u0004 יחתוך את השם הקדוש ויגנזנו, \u0003וישתמש במותר\u0004 לבית הכנסת; \u0003ואם לאו,\u0004 שלא עשה בדעת ישראל — \u0003טעונה\u0004 הקורה כולה \u0003גניזה, חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא בלבו לשמים,\u0004 להקדיש את הקורה למקדש, ולא ניתן להשתמש בה.","ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 מפני ש\u0003שם כתוב עליה\u0004 הוא דבעיא \u0005[שצריכה]\u0006 \u0003גניזה, הא\u0004 \u0005[אבל]\u0006 אם \u0003אין שם כתוב עליה\u0004 — \u0003לא בעיא\u0004 \u0005[צריכה]\u0006 \u0003גניזה,\u0004 ומדוע אמר רב יהודה שתרומה שהפריש הגוי טעונה גניזה?","ומשיבים: \u0003הוא הדין דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003אין שם כתוב עליה נמי בעיא\u0004 \u0005[גם כן צריכה]\u0006 הקורה \u0003גניזה,\u0004 מחשש שליבו לשמים, \u0003והא קא משמע לן\u0004 \u0005[ו\u0006דין \u0005זה הוא משמיע לנו],\u0006 שבמקרה שכוונתו להקדישה לבית הכנסת, \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003שם כתוב עליה\u0004 לא נאסרה כולה, אלא \u0003יגוד\u0004 (יחתכנו) \u0003וישתמש במותר.\u0004 וטעם הדבר, מפני ש\u0003שם\u0004 הכתוב על דבר מקדש רק את מקומו, אבל \u0003שלא במקומו\u0004 של השם, \u0003לאו\u0004 \u0005[אינו]\u0006 \u0003קדוש.\u0004","והוא כפי \u0003דתנן\u0004 \u0005[ששנינו]:\u0006 \u0003היה כתוב\u0004 שם השם \u0003על ידות הכלים ועל כרעי המטה\u0004 — \u0003הרי זה יגוד\u0004 את השם \u0003ויגנוז,\u0004 וישתמש בשאר.","\u0003אמר רב נחמן אמר רבה בר אבהו: האומר\u0004 על מטבע \u0003\"סלע זו לצדקה\"\u0004 — \u0003מותר לשנותה,\u0004 כלומר, להשתמש בה, ולאחר זמן יביא אחרת. ומעירים: \u0003סבור מינה\u0004 \u0005[סברו מכאן]\u0006 מתחילה: \u0003ל\u0004צורך \u0003עצמו\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 מותר לשנותה, מפני שכך חשב מתחילה, אבל להלוותה \u0003ל\u0004איש \u0003אחר\u0004 — \u0003לא.\u0004 ואולם \u0003איתמר\u0004 \u0005[נאמר]\u0006 שכך \u0003אמר רב אמי אמר ר' יוחנן: בין לעצמו בין לאחר\u0004 — מותר לשנותה.","\u0003אמר ר' זעירא: לא שנו\u0004 שמותר לשנותה, \u0003אלא\u0004 כש\u0003אמר:\u0004 \"הרי \u0003עלי\u0004 סלע לצדקה\", \u0003אבל\u0004 אם \u0003אמר: \"הרי\u0004 סלע \u0003זו\u0004 לצדקה\" — \u0003בעינא בעי למיתבה\u0004 \u0005[\u0006את המטבע \u0005בעינה צריך לתת],\u0006 ואינו יכול לשנותה באחרת.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא:\u0004 \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 \u0003איפכא מיסתברא\u0004 \u0005[ההיפך הוא המסתבר]:\u0006 דווקא אם \u0003אמר\u0004 \"סלע \u0003זו\u0004 לצדקה\", יש להתיר לו שיהיה \u0003משתמש בה, כי היכי דליחייב באחריותה\u0004 \u0005[כדי שיתחייב\u0006 מאותה שעה \u0005באחריותה],\u0006 שאם תאבד ייתן אחרת, \u0003אבל\u0004 אם \u0003אמר:\u0004 \"הרי \u0003עלי\u0004 סלע לצדקה\", שהוא ממילא חייב באחריותה — \u0003לא\u0004 ישתמש בה! \u0003אלא\u0004 מכיוון שיש סברה לכל צד, \u0003לא שנא\u0004 \u0005[לא שונה\u0006 הדין\u0005],\u0006 ובכל אופן מותר להשתמש בה.","ומעירים, \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבא: נדר צדקה ואין הקדש צדקה.\u0004 ויש לתמוה: \u0003מאי קאמר\u0004 \u0005[מה הוא אומר]?\u0006 והרי \u0003לא נדר ולא הקדש\u0004 הינם \u0003צדקה\u0004 לעניים!","\u0003אלא לאו הכי קאמר\u0004 \u0005[\u0006האם \u0005לא כך הוא אומר]:\u0006 \u0003צדקה הרי היא ב\u0004איסור \u0003\"בל תאחר\"\u0004 (\"לא תאחר לשלמו\", דברים כג, כב) כנדר שאדם נודר להקדש, \u0003ו\u0004אולם \u0003אינה כהקדש,\u0004 ש\u0003אילו הקדש אסור לאשתמושי ביה\u0004 \u0005[להשתמש בו],\u0006 \u0003ואילו צדקה שרי לאשתמושי ביה\u0004 \u0005[מותר להשתמש בה],\u0006 והברייתא אינה מחלקת בין האומר \"הרי עלי\" או \"הרי זו\", וכשיטת רבא.","\u0003אמר רב כהנא: אמריתא לשמעתא\u0004 \u0005[אמרתי שמועה זו]\u0006 של רב נחמן, בענין האומר \"סלע זו לצדקה\", והדיון שעליה, קמיה \u0005[לפני]\u0006 \u0003רב זביד מנהרדעא,\u0004 ו\u0003אמר\u0004 לי: \u0003אתון הכי מתניתו לה\u0004 \u0005[אתם כך אתם שונים אותה],\u0006 שרב נחמן אמר רק שמותר לשנותה, וחכמים דנו בדבר, והגיעו למסקנה שמדובר בכל האופנים, ואילו \u0003אנן הכי מתנינן לה\u0004 \u0005[אנו כך אנו שונים אותה],\u0006 כולה בשם רב נחמן, \u0003אמר רב נחמן אמר רבה בר אבוה אמר רב: האומר \"סלע זו לצדקה\"\u0004 — \u0003מותר לשנותה, בין לעצמו בין לאחר, בין אמר: \"עלי\" בין אמר: \"הרי זו\".\u0004","ועוד בענינים אלו, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 האומר \u0003\"סלע זו לצדקה\", עד שלא באתה\u0004 (באה) \u0003ליד גבאי\u0004 הצדקה — \u0003מותר לשנותה,\u0004 להשתמש בה כדי לתת אחרת תמורתה, \u0003משבאתה ליד גבאי\u0004 — \u0003אסור לשנותה.\u0004"],["ושואלים: \u0003איני\u0004 \u0005[האמנם]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' ינאי,\u0004 שהיה גבאי צדקה, \u0003יזיף ופרע\u0004 \u0005[\u0006היה \u0005לווה\u0006 ממעות צדקה שבאו לידו \u0005ופורע]!\u0006 ומשיבים: \u0003שאני\u0004 \u0005[שונה\u0006 דינו של\u0005]\u0006 \u0003ר' ינאי, דניחא להו\u0004 \u0005[שנוח להם]\u0006 \u0003לעניים\u0004 בכך, מפני \u0003דכמה דמשהי מעשי ומייתי להו\u0004 \u0005[שככל ש\u0006היה \u0005משהה\u0006 את קופת הצדקה בלא מעות, כך היה \u0005כופה\u0006 את הציבור \u0005ומביא להם]\u0006 מעות נוספות.","ועוד בעניינים אלו \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ישראל שהתנדב מנורה או נר לבית הכנסת\u0004 — \u0003אסור לשנותה,\u0004 להשתמש בה לצורך דבר אחר. \u0003סבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 \u0003ר' חייא בר אבא למימר\u0004 \u0005[לומר]:\u0006 \u0003לא שנא\u0004 \u0005[לא שונה\u0006 הדין\u0005]\u0006 \u0003לדבר הרשות ולא שנא\u0004 \u0005[ולא שונה\u0006 הדין\u0005]\u0006 \u0003לדבר מצוה,\u0004 אסור לשנותה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אמי, הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן: לא שנו\u0004 שאסור לשנותה, \u0003אלא לדבר הרשות, אבל לדבר מצוה\u0004 — \u0003מותר לשנותה.\u0004","ודין זה נלמד \u0003מ\u0004מה ש\u0003אמר ר' אסי אמר ר' יוחנן: גוי שהתנדב מנורה או נר לבית הכנסת, עד שלא נשתקע\u0004 (נשתכח) \u0003שם בעליה,\u0004 שאנשים זוכרים שהוא תרם אותה — \u0003אסור לשנותה, משנשתקע שם בעליה\u0004 — \u0003מותר לשנותה.\u0004","ויש לברר: \u0003למאי\u0004 \u0005[למה\u0006 נאסר לשנותה\u0005]\u0006 קודם שנשתקע שם הבעלים? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003לדבר הרשות, מאי איריא\u0004 \u0005[מדוע מדובר\u0006 דווקא\u0005]\u0006 על \u0003גוי? אפילו\u0004 אם \u0003ישראל\u0004 התנדב מנורה, \u0003נמי\u0004 \u0005[גם כן]\u0006 אסור לשנותה לדבר רשות!","\u0003אלא\u0004 מדובר בשינוי \u0003לדבר מצוה,\u0004 שהוא אסור קודם שנשתקע שם הבעלים, רק אם המתנדב הוא גוי, אבל לא ישראל. \u0003וטעמא\u0004 \u0005[וטעם\u0006 הדבר\u0005],\u0006 מפני ש\u0003גוי הוא דפעי\u0004 \u0005[שצועק]\u0006 היכן המנורה שנדבתי, ומוחה על כך. \u0003אבל ישראל דלא פעי\u0004 \u0005[שאינו צועק]\u0006 כשמשנים את נדבתו לצורך מצוה אחרת, \u0003שפיר דמי\u0004 \u0005[יפה,\u0006 נכון \u0005הדבר].\u0006","מסופר, \u0003שעזרק טייעא\u0004 \u0005[סוחר ערבי]\u0006 \u0003אינדב שרגא לבי כנישתא\u0004 \u0005[התנדב נר לבית הכנסת]\u0006 של \u0003רב יהודה, שנייה\u0004 \u0005[שינה אותו]\u0006 \u0003רחבא\u0004 לדבר אחר, קודם שנשתקע שמו של שעזרק ממנה, \u0003ואיקפד\u0004 \u0005[והקפיד]\u0006 \u0003רבא\u0004 על שלא המתינו. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 להיפך: \u0003שנייה\u0004 \u0005[שינה אותו]\u0006 \u0003רבא, ואיקפד\u0004 \u0005[והקפיד]\u0006 \u0003רחבא. ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003שנייה חזני דפומבדיתא\u0004 \u0005[שינו אותה גבאי פומבדיתא],\u0006 \u0003ואיקפד\u0004 \u0005[והקפיד]\u0006 \u0003רחבא ואיקפד\u0004 \u0005[והקפיד\u0006 גם\u0005]\u0006 \u0003רבה.\u0004","ומסבירים: \u0003מאן דשנייה סבר\u0004 \u0005[מי ששינה\u0006 היה \u0005סבור]\u0006 שמותר הדבר, מפני \u0003דלא שכיח\u0004 \u0005[ש\u0006עזרק \u0005אינו מצוי\u0006 בעיר\u0005],\u0006 ואין לחשוש לכך שימחה. \u0003ומאן דאיקפד סבר\u0004 \u0005[ומי שהקפיד\u0006 היה \u0005סבור]:\u0006 \u0003זמנין דמקרי ואתי\u0004 \u0005[פעמים קורה ש\u0006הוא \u0005בא\u0006 לשם\u0005]\u0006 ויש לחשוש לכך.","\u0003הגוסס\u0004 (העומד למות) \u0003ו\u0004כן \u0003היוצא ליהרג\u0004 לאחר שנגמר דינו בבית הדין — \u0003לא נידר ולא נערך,\u0004 שמי שנדר את דמיו או את ערכו — פטור. \u0003ר' חנינא בן עקביא אומר:\u0004 אמנם אינו נידר, מפני שאין לו דמים, שלא ניתן למוכרו כעבד. אבל \u0003נערך, מפני שדמיו קצובין\u0004 בתורה, לפי גילו. \u0003ר' יוסי אומר:\u0004 אדם במצב כזה \u0003נודר\u0004 דמיו של פלוני, \u0003ומעריך, ומקדיש\u0004 מנכסיו, \u0003ואם הזיק\u0004 — \u0003חייב\u0004 בתשלומים.","שנינו במשנה כי הגוסס והיוצא ליהרג לא נידר ולא נערך. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003גוסס לא נידר\u0004 — מפני \u0003דלאו בר\u0004 \u0005[שלא בן]\u0006 \u0003דמים הוא,\u0004 שאין שווי לגוסס, \u0003ולא נערך\u0004 — מפני \u0003דלאו בר\u0004 \u0005[שלא בן]\u0006 \u0003העמדה והערכה הוא,\u0004 ונאמר בתורה: \"והעמידו לפני הכהן והעריך\" (ויקרא כז, ח), ומי שלא ניתן להעמידו — אין לו דין ערכין. \u0003אלא יוצא ליהרג, בשלמא\u0004 \u0005[נניח]\u0006 ש\u0003לא נידר\u0004 — מפני \u0003דלאו בר\u0004 \u0005[שלא בן]\u0006 \u0003דמים הוא,\u0004 שאין לו קונים, \u0003אלא לא נערך, אמאי לא\u0004 \u0005[מדוע לא]?\u0006","ומשיבים, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003מנין\u0004 ש\u0003היוצא ליהרג ואמר \"ערכי עלי\", שלא אמר כלום,\u0004 ולא יגבו מנכסיו? \u0003תלמוד לומר: \"כל חרם\u0004 אשר יחרם מן האדם \u0003לא יפדה\u0004 מות יומת\" (ויקרא כז, כט), שמי שדינו למות (\"אשר יחרם\") אינו בכלל פדיון וערכין. \u0003יכול\u0004 נאמר כן \u0003אפילו\u0004 העריך את הנידון \u0003קודם שנגמר דינו\u0004 למיתה? \u0003תלמוד לומר:\u0004 \"כל אשר יחרם \u0003מן האדם\", ולא כל האדם.\u0004","ושואלים: \u0003ול\u0004דעת \u0003ר' חנינא בן עקביא\u0004 ש\u0003אמר\u0004 במשנתנו כי היוצא ליהרג \u0003נערך מפני שדמיו קצובין, האי\u0004 \u0005[\u0006מקרא \u0005זה]\u0006 \u0003\"כל חרם\" מאי עביד ליה\u0004 \u0005[מה\u0006 הוא \u0005עושה עמו]?\u0006","ומשיבים: הוא דורש אותו \u0003לכדתניא\u0004 \u0005[לכמו\u0006 \u0005ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר: לפי שמצינו למומתים בידי שמים שנותנין ממון ומתכפר להם, שנאמר\u0004 בדין בעליו של שור מועד שהמית אדם: \"השור יסקל וגם בעליו יומת. \u0003אם כפר יושת עליו\u0004 ונתן פדיון נפשו\" (שמות כא, כט—ל), \u0003יכול אף\u0004 חייב מיתה \u0003בידי אדם\u0004 דינו \u0003כן,\u0004 שיתן ממון ויתכפר לו? \u0003תלמוד לומר: \"כל חרם\u0004 אשר יחרם מן האדם \u0003לא יפדה\".\u0004","\u0003אין לי אלא\u0004 ב\u0003מיתות\u0004 על עבירות \u0003חמורות,\u0004 אותן \u0003שלא ניתנה שגגתן לכפרה,\u0004 שאם עשאן בשוגג אין לו כפרה בקרבן או בגלות, כגון מגדף ומקלל אביו, ויש לומר שמטעם זה גם אינם מתכפרים בממון אם עשו במזיד, אבל ב\u0003מיתות קלות,\u0004 אותן \u0003שניתנה שגגתן לכפרה,\u0004 כגון מחלל שבת בשוגג שמביא חטאת, או רוצח בשוגג שגולה, \u0003מנין\u0004 שלא יתכפר בהם המזיד בממון? \u0003תלמוד לומר: \"כל חרם\",\u0004 והמילה \"כל\" מרבה אף אותם.","בענין היוצא ליהרג נאמר במשנתנו, \u0003ר' יוסי אומר: נודר ומעריך\u0004 (את האחרים) ומקדיש, ואם הזיק באותה שעה — חייב בתשלומים. ושואלים: \u0003ותנא קמא מי קאמר דלא\u0004 \u0005[והתנא הראשון האם\u0006 הוא \u0005אומר שאינו\u0006 נודר ומעריך\u0005]?\u0006 והרי רק אמר שאינו נידר ונערך!","\u0003אלא, ב\u0004כך שהוא \u0003נודר ומעריך ומקדיש\u0004 — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים],\u0006 וגם התנא הראשון סבור כן. \u0003כי פליגי\u0004 \u0005[כאשר הם חלוקים]\u0006 — הרי זה \u0003באם הזיק\u0004 באותה שעה, \u0003תנא קמא סבר\u0004 \u0005[התנא הראשון סבור]:\u0006 \u0003אם הזיק\u0004 — \u0003אינו חייב בתשלומין, ור' יוסי סבר\u0004 \u0005[סבור]:\u0006 \u0003אם הזיק\u0004 — \u0003חייב בתשלומין.\u0004","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה הם חלוקים]?\u0006 והלא התורה חייבה כל מי שהזיק לשלם! \u0003אמר רב יוסף:\u0004 באפשרות לגבות את התשלומים מיורשיו, ובשאלה האם \u0003במלוה על פה\u0004 (חוב שאינו כתוב בשטר) \u0003גובה\u0004 בעל החוב \u0003מן\u0004 נכסי החייב שביד \u0003היורשין קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003תנא קמא סבר\u0004 \u0005[התנא הראשון סבור]:\u0006 \u0003מלוה על פה אינו גובה מן היורשין, ור' יוסי סבר\u0004 \u0005[סבור]:\u0006 \u0003מלוה על פה גובה מן היורשין.\u0004","\u0003רבא אמר: דכולי עלמא\u0004 \u0005[לדעת\u0006 \u0005הכל]\u0006 \u0003מלוה על פה אינו גובה מן היורשין, והכא\u0004 \u0005[וכאן],\u0006 \u0003במלוה\u0004 ה\u0003כתובה בתורה\u0004 (כגון חובת המזיק לשלם) האם היא נחשבת כמילוה שבשטר \u0003קמיפלגי\u0004 \u0005[הם חלוקים],\u0006 \u0003תנא קמא סבר\u0004 \u0005[התנא הראשון סבור]:\u0006 \u0003מלוה כתובה בתורה\u0004 — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003ככתובה בשטר דמיא\u0004 \u0005[נחשבת],\u0006 ולכן לא יגבו מהנכסים שהוריש המזיק, \u0003ור' יוסי סבר\u0004 \u0005[סבור]:\u0006 \u0003ככתובה בשטר דמיא\u0004 \u0005[נחשבת],\u0006 ולכן יגבו מהנכסים שהוריש המזיק.","\u0003ואיכא דמתני לה אהא\u0004 \u0005[ויש ששונים\u0006 את מחלוקת רב יוסף ורבא \u0005על\u0006 ברייתא \u0005זו]:\u0006 \u0003היוצא ליהרג,\u0004 שנגמר דינו למיתה, \u0003הוא שחבל באחרים\u0004 — \u0003חייב, אחרים שחבלו בו\u0004 — \u0003פטורין,\u0004 כאילו חבלו באדם מת. \u0003ר' שמעון בן אלעזר אומר: אף הוא אם חבל באחרים\u0004 — \u0003פטור,\u0004 מפני \u0003שלא ניתן לחזרת עמידת בית דין,\u0004 כלומר, לא ניתן לחזור ולהעמידו לדין לאחר שנגמר דינו למיתה, מפני שצריך להמיתו מיד."],["ותמהים: \u0003מכלל דתנא קמא סבר\u0004 \u0005[מכלל\u0006 הדברים יש ללמוד \u0005שהתנא הראשון,\u0006 האומר שהוא שחבל באחרים חייב, \u0005סבור],\u0006 שהיוצא ליהרג \u0003ניתן לחזרת עמידת בית דין?\u0004 והרי מקובלנו שאין מענים את דינו!","\u0003אמר רב יוסף:\u0004 אכן, לדעת הכל לא יעכבו את הריגתו, אלא נחלקו באפשרות לגבות את חובו מן היורשים, ו\u0003ב\u0004שאלה האם \u0003מלוה על פה גובה מן היורשין קמיפלגי\u0004 \u0005[הם חלוקים],\u0006 \u0003תנא קמא סבר\u0004 \u0005[התנא הראשון סבור]:\u0006 \u0003מלוה על פה גובה מן היורשין,\u0004 ואחר הריגתו יגבו מהנכסים שהוריש, \u0003ורבי שמעון בן אלעזר סבר\u0004 \u0005[סבור]:\u0006 מלוה על פה \u0003אינו גובה מן היורשין,\u0004 ולכן פטורים יורשי נכסיו לשלם את מה שהזיק.","\u0003רבה אמר: דכולי עלמא\u0004 \u0005[הכל\u0006 סבורים\u0005]\u0006 ש\u0003מלוה על פה אינו גובה מן היורשין, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה האם \u0003מלוה הכתובה בתורה,\u0004 כמו חובת המזיק לשלם, נחשבת \u0003ככתובה בשטר קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003תנא קמא סבר\u0004 \u0005[התנא הראשון סבור]:\u0006 \u0003ככתובה בשטר דמיא\u0004 \u0005[נחשבת],\u0006 ולכן יגבו מהנכסים שהוריש, \u0003ור' שמעון בן אלעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003לאו ככתובה בשטר דמיא\u0004 \u0005[נחשבת],\u0006 ולא יגבו מהנכסים שהוריש.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על הסוברים שמילוה על פה (ובכלל זה חוב הכתוב בתורה) אינו נגבה מהיורשים, ממה ששנינו בברייתא: \u0003החופר בור ברשות הרבים, ונפל עליו שור והרגו\u0004 (את החופר) — \u0003פטור\u0004 בעל השור מלשלם, מפני שהחופר גרם את התקלה; \u0003ולא עוד, אלא שאם מת השור\u0004 — \u0003יורשי בעל הבור חייבין לשלם דמי שור לבעליו.\u0004 הרי שגובים מן היורשים חוב כזה!","\u0003אמר ר' אילא אמר רב:\u0004 מדובר בברייתא זו \u0003כשעמד\u0004 חופר הבור \u0003בדין\u0004 קודם שמת, וחייבוהו, ודינו של פסק בית דין כדין מילוה בשטר. ושואלים: וכיצד ניתן לפרש שעמד בדין? \u0003והא\u0004 \u0005[והרי]\u0006 \"נפל עליו השור ו\u0003הרגו\" קתני\u0004 \u0005[הוא שונה\u0006 בברייתא\u0005]!\u0006 \u0003אמר רב אדא בר אהבה:\u0004 מדובר \u0003כשעשאו\u0004 השור \u0003טריפה\u0004 (אדם העומד למות), ואז דנו אותו ואחר כך מת.","ומקשים: כיצד ניתן לפרש כן? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן, תני\u0004 \u0005[שונה]\u0006 \u0003חגא\u0004 בברייתא זו: \u0003מת\u0004 השור \u0003וקברו\u0004 — חייבים יורשיו של החופר לשלם לבעל השור, וכיצד ייתכן שדנוהו באותה שעה? ומסכמים: \u0003והילכתא\u0004 \u0005[וההלכה\u0006 היא\u0005]\u0006 שאין היורשים משלמים על נזק שהזיק אביהם, אלא אם כן עמד בדין. ויש להעמיד ברייתא זו במקרה \u0003דייתבי דייני אפומא דבירא\u0004 \u0005[שישבו הדיינים\u0006 שם \u0005על פי הבור],\u0006 ופסקו את דינו לשלם קודם שיצאה נשמתו.","ועוד בענין היוצא ליהרג \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003היוצא ליהרג\u0004 — \u0003מזין עליו\u0004 (עבורו) על המזבח \u0003מדם\u0004 קרבן \u0003חטאתו ומדם\u0004 קרבן \u0003אשמו,\u0004 שהביא קודם לכן. אבל אם \u0003חטא באותה שעה\u0004 בחטא המחייבו חטאת או אשם — \u0003אין נזקקין לו,\u0004 שאין ממתינים לו שיקריב קרבן על חטאו, אלא הורגים אותו מיד. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003אמר רב יוסף: מפני שאין מענין את דינו,\u0004 להמתין שיוקרב הקרבן.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אי הכי\u0004 \u0005[אם כך],\u0006 מפני עינוי הדין, \u0003אפילו רישא נמי\u0004 \u0005[בתחילה גם כן],\u0006 במקרה שהביא קרבן מתחילה, לא ימתינו לשוחטו ולזרוק את דמו! ומשיבים: מדובר שם \u0003כגון שהיה זבחו זבוח\u0004 (שחוט) \u0003באותה שעה,\u0004 ולא נותר אלא לזרוק את הדם, ובזמן מועט כזה אין לחשוש לעינוי הדין.","ומקשים: \u0003אבל\u0004 לדרך זו, כשהפריש קרבנו אלא ש\u0003אין זבחו זבוח, מאי\u0004 \u0005[מה\u0006 דינו\u0005],\u0006 \u0003לא\u0004 ממתינים? אם כן, \u0003אדתני\u0004 \u0005[עד שהוא שונה\u0006 בברייתא\u0005]\u0006 הלכה חדשה, שאם \u0003חטא באותה שעה אין נזקקין לו\u0004 — \u0003ליפלוג וליתני בדידה\u0004 \u0005[שיחלוק ושישנה בה,\u0006 באותה הלכה \u0005עצמה]:\u0006 \u0003במה דברים אמורים\u0004 שמזים עליו מדם חטאתו ודם אשמו — \u0003שהיה זבח זבוח באותה שעה, אבל אין זבח זבוח\u0004 — \u0003לא\u0004 ממתינים!","ומשיבים: \u0003הכי נמי קאמר\u0004 \u0005[כך גם כן הוא אומר]:\u0006 \u0003במה דברים אמורים\u0004 — \u0003שהיה זבח זבוח באותה שעה, אבל אין זבח זבוח\u0004 — \u0003נעשה כמי שחטא באותה שעה, ואין נזקקין לו.\u0004","\u0003האשה שיצאה ליהרג\u0004 בבית דין, והיא מעוברת — \u0003אין ממתינין לה עד שתלד,\u0004 אלא הורגים אותה מיד, עם העובר שבמעיה. אבל \u0003האשה\u0004 היוצאת ליהרג \u0003שישבה על המשבר\u0004 כלומר, שהחלה ללדת — \u0003ממתינין לה עד שתלד. האשה שנהרגה\u0004 במיתת בית דין — \u0003נהנין בשערה\u0004 כלומר, אין השיער אסור בהנאה. \u0003בהמה שנהרגה\u0004 במיתת בית דין, וכגון שנגחה אדם — \u0003אסורה בהנאה.\u0004","שנינו במשנה כי אשה שיצאה ליהרג אין ממתינים לה עד שתלד, אלא הורגים אותה עם העובר שבמעיה. ותמהים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005],\u0006 והרי העובר \u0003גופה היא,\u0004 חלק מגופה! ומשיבים: \u0003איצטריך\u0004 \u0005[נצרך]\u0006 הדבר להיאמר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]\u0006 \"וכי ינצו אנשים ונגפו אשה הרה ויצאו ילדיה... ענוש יענש \u0003כאשר ישית עליו בעל האשה\"\u0004 (שמות כא, כב), אם כן העובר \u0003ממונא\u0004 \u0005[ממון,\u0006 רכוש\u0005]\u0006 של ה\u0003בעל הוא, ולא ליפסדיה מיניה\u0004 \u0005[ולא יפסידו אותו ממנו],\u0006 אלא ימתינו עד שתלד, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין אומרים כן.","ושואלים: \u0003ואימא הכי נמי\u0004 \u0005[ואמור כך גם כן]\u0006 שימתינו! \u0003אמר ר' אבהו אמר ר' יוחנן, אמר קרא\u0004 \u0005[המקרא]:\u0006 \"כי ימצא איש שוכב עם אשה בעולת בעל \u0003ומתו גם שניהם\u0004 האיש השוכב עם האשה והאשה\" (דברים כב, כב), והייתור של \"גם שניהם\" בא \u0003לרבות את הוולד\u0004 שבמעיה, שגם הוא מת.","ושואלים: \u0003והאי מיבעי ליה\u0004 \u0005[והרי\u0006 מקרא זה \u0005נצרך הוא]\u0006 כדי ללמוד ממנו דין אחר, שאין מענישים אף אחד מהם \u0003עד שיהו שניהן שוין,\u0004 כלומר, בני עונשין, אלו \u0003דברי ר' יאשיה!\u0004 ומשיבים: \u0003כי קאמרת\u0004 \u0005[כאשר אומר אתה]\u0006 שלמדים מכאן שממיתים את הוולד — הרי זה \u0003מ\"גם\",\u0004 ומה שאין ממיתים עד שיהיו שניהם שווים נלמד מהמקרא \"שניהם\".","ועוד שנינו במשנה: האשה היוצאת ליהרג, אם \u0003ישבה על המשבר\u0004 ממתינים לה עד שתלד. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה\u0006 ה\u0005טעם]\u0006 שבאופן זה ממתינים לה? ומשיבים: \u0003כיון דעקר\u0004 \u0005[שנעקר]\u0006 הוולד ממקומו והחל לצאת, \u0003גופא אחרינא\u0004 \u0005[גוף אחר]\u0006 \u0003הוא\u0004 נחשב, ואין להורגו.","\u0003אמר רב יהודה אמר שמואל: האשה\u0004 המעוברת \u0003היוצאה ליהרג,\u0004 \u0003מכין אותה\u0004 על בטנה \u0003כנגד בית הריון\u0004 (הרחם) \u0003כדי שימות הוולד תחילה,\u0004 \u0003כדי שלא תבא\u0004 האם \u0003לידי ניוול,\u0004 שמא יפרכס הוולד כדי לצאת, ויצא דמה, ותתבזה בפני הרואים. ושואלים: האם \u0003למימרא\u0004 \u0005[לומר]\u0006 שלדעת שמואל, כשאשה מעוברת מתה, \u0003היא קדמה ומתה ברישא\u0004 \u0005[בתחילה]\u0006 לפני העובר? \u0003והא קיימא לן דוולד מיית ברישא\u0004 \u0005[והרי מוחזק לנו שהוולד מת בתחילה]!\u0006","\u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003תינוק בן יומו\u0004 הראשון, \u0003נוחל,\u0004 יורש את קרוביו שמתו, \u0003ו\u0004אם מת בו ביום \u0003מנחיל\u0004 לקרוביו את מה שירש. \u0003ו\u0004בפירוש הדברים \u0003אמר רב ששת:\u0004 הכוונה היא שהתינוק \u0003נוחל בנכסי האם,\u0004 שמתה לאחר שנולד, כדי \u0003להנחיל\u0004 נכסים אלו \u0003לאחין\u0004 שלו \u0003מן האב,\u0004 שאינם בניה של אמו, אלא מאשה אחרת.","ויש לדייק: \u0003דווקא בן יום אחד\u0004 נוחל ומנחיל, \u0003אבל עובר\u0004 במעי אמו שמתה — \u0003לא\u0004 נוחל ומנחיל. וטעם הדבר, מפני ש\u0003הוא מיית ברישא\u0004 \u0005[בתחילה]\u0006 קודם אמו, \u0003ואין הבן יורש את אמו\u0004 כשהוא \u0003בקבר,\u0004 כדי \u0003להנחיל\u0004 את נכסיה \u0003לאחין מן האב!\u0004","ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה],\u0006 שהעובר מת בתחילה, אמורים \u0003לגבי מיתה\u0004 רגילה, שהאשה מתה בידי שמים. וטעם הדבר, כי \u0003איידי דוולד זוטרא חיותיה, עיילא טיפה דמלאך המות ומחתך להו לסימנין\u0004 \u0005[מתוך שחיותו של הוולד מועטה, נכנסת\u0006 בו \u0005טיפה של מלאך המות וחותכת את סימני\u0006 חיותו קודם לאמו\u0005].\u0006 \u0003אבל נהרגה\u0004 האם, כגון במיתת בית דין — \u0003היא מתה ברישא\u0004 \u0005[בתחילה].\u0006","ומקשים: \u0003והא הוה עובדא ופרכיס עד תלת פרכוסי\u0004 \u0005[והרי היה מעשה\u0006 באשה שמתה כדרכה, \u0005ו\u0006אחר כך \u0005פירכס העובר שלוש פעמים]!\u0006 ומשיבים: הפירכוס הזה אינו סימן לחיות, אלא \u0003מידי דהוי אזנב הלטאה דמפרכסת\u0004 \u0005[כמו שהוא בזנב הלטאה שמפרכס]\u0006 אחר שנחתך ממנה, למרות שאין בו חיות.","\u0003אמר רב נחמן אמר שמואל: האשה שישבה על המשבר ומתה בשבת, מביאין סכין ומקרעים את כריסה, ומוציאין את הוולד,\u0004 מפני שפעמים העובר חי וניתן להצילו. ותמהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שמותר הדבר, \u0003מאי עביד\u0004 \u0005[\u0006וכי \u0005מה הוא עושה]?\u0006"],["\u0003מחתך בבשר הוא,\u0004 ואין מקום לאוסרו! \u0003אמר רבה: לא נצרכה\u0004 הלכה זו לענין חיתוך כריסה, אלא להשמיענו שמותר \u0003להביא סכין דרך רשות הרבים\u0004 לשם כך, למרות שהיא אחת המלאכות האסורות בשבת מהתורה.","ושואלים: \u0003ומאי קמשמע לן, דמספיקא מחללינן שבתא\u0004 \u0005[ומה הוא משמיע לנו, שמספק\u0006 פיקוח נפש \u0005אנו מחללים שבת]?\u0006 והרי כבר \u0003תנינא\u0004 \u0005[שנינו\u0006 זאת במשנה\u0005]:\u0006 \u0003מי שנפלה עליו מפולת, ספק הוא שם,\u0004 תחת גל האבנים, \u0003ספק אינו שם, ספק\u0004 הוא \u0003חי ספק מת, ספק נכרי ספק ישראל\u0004 — \u0003מפקחין עליו את הגל\u0004 בשבת!","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 שמחללים שבת על ספק פיקוח נפש, מפני \u0003דהוה ליה חזקה דחיותא\u0004 \u0005[שהיתה לו חזקה של חיות],\u0006 ואנו מעמידים דבר על חזקתו. \u0003אבל הכא דלא הוה ליה חזקה דחיותא מעיקרא\u0004 \u0005[כאן שלא היתה לו חזקה של חיות מתחילה,\u0006 שהרי טרם נולד\u0005]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יחללו על כך שבת, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שמואל שמחללים שבת מספק אפילו על עובר.","שנינו במשנתנו: \u0003האשה שנהרגה\u0004 נהנין בשערה. ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 והרי המת ושערו \u0003איסורי הנאה נינהו\u0004 \u0005[הם]!\u0006 \u0003אמר רב:\u0004 מדובר \u0003באומרת\u0004 לפני הריגתה \u0003\"תנו שערי לבתי\".\u0004 ותמהים: וכי איסור ההנאה מגוף המת תלוי ברצונו? \u0003אילו אמרה \"תנו ידי לבתי\", מי יהבינן לה\u0004 \u0005[האם היינו נותנים לה,\u0006 לבתה\u0005]\u0006 את היד?! \u0003אמר רב:\u0004 אין מדובר במשנה בשיער ממש, אלא \u0003בפאה נכרית,\u0004 שיער של אשה אחרת, שאינו ממש חלק מגופה. ומדייקים מדברי רב: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 במקרה ש\u0003אמרה \"תנו\u0004 לבתי\" מותר לתת אותה לבתה, מפני שגילתה דעתה שאין זה חלק מגופה, \u0003הא\u0004 \u0005[אבל]\u0006 \u0003לא אמרה \"תנו\"\u0004 — \u0003גופה הוא ומיתסר\u0004 \u0005[ונאסר].\u0006","","\u0003והא מיבעיא ליה\u0004 \u0005[והרי נשאלה לו]\u0006 \u0003לר' יוסי בר' חנינא\u0004 שאלה זו בדין עיר הנידחת (שהדיחו את יושביה לעבודה זרה), שדנים את החוטאים שבה למיתה, ושורפים את כל הרכוש שבה (גם של אלו שלא חטאו), \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003ר' יוסי בר' חנינא: שער נשים צדקניות\u0004 שלא חטאו \u0003מהו?\u0004","\u0003ואמר רבא:\u0004 לא בשיער ממש, אלא \u0003בפאה נכרית קמיבעיא ליה\u0004 \u0005[נשאלה לו\u0006 לר' יוסי בר' חנינא\u0005].\u0006 והלא לדברי רב, כל עוד לא התנתה על כך מראש — נחשבת הפאה הנכרית לחלק מגופה! ומשיבים: \u0003כי קמיבעיא ליה\u0004 \u0005[כאשר נשאלה לו]\u0006 השאלה \u0003לר' יוסי בר' חנינא,\u0004 האם הפאה נחשבת חלק מגופה — הרי זה בפאה נכרית \u0003דתלי בסיכתא\u0004 \u0005[שתלויה בסיכה],\u0006","\u0003הכא דמחבר בה\u0004 \u0005[כאן\u0006 דיבר רב בפאה נכרית \u0005שמחוברת בה],\u0006 ובמקרה זה, \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 במקרה ש\u0003אמרה \"תנו\u0004 לבתי\" — נותנים לה את הפאה, \u0003הא\u0004 \u0005[אבל]\u0006 \u0003לא אמרה \"תנו\"\u0004 — \u0003גופה הוא ומיתסר\u0004 \u0005[ואסור\u0006 בהנאה\u0005].\u0006","על העמדת דין המשנה בפאה נכרית, ולא בשיער רגיל, \u0003קשיא ליה\u0004 \u0005[קשה\u0006 היה \u0005לו]\u0006 \u0003לרב נחמן בר יצחק: והא דומיא דבהמה קתני\u0004 \u0005[והרי\u0006 ב\u0005דומה\u0006 לאיסור הנאה \u0005מן הבהמה\u0006 התנא \u0005שונה],\u0006 שהוא מעמיד אותן זו לעומת זו, ואם כן \u0003מה התם\u0004 \u0005[שם,\u0006 בבהמה\u0005]\u0006 מדובר בהנאה מ\u0003גופיה\u0004 \u0005[גופו],\u0006 \u0003אף הכא נמי גופיה\u0004 \u0005[אף כאן,\u0006 בשער האשה, \u0005גם כן\u0006 מדובר ב\u0005גופה\u0006 ממש\u0005],\u0006 ולא בפאה נכרית! \u0003אלא אמר רב נחמן\u0004 בר יצחק: אכן מדובר במשנה בשיער ממש, ויש הבדל בין שער האשה לבין שער בהמה: \u0003זו,\u0004 האשה — \u0003מיתתה אוסרתה\u0004 בהנאה, ולכן השיער שלא שייכת בו מיתה — אינו נאסר בהנאה, \u0003וזו,\u0004 הבהמה — \u0003גמר דינה אוסרתה\u0004 בהנאה, עוד קודם שהוציאוה להורג, ולא מיתתה, ולכן גם השיער שמחובר בה נאסר.","","ומעירים: \u0003תני\u0004 \u0005[שנה]\u0006 \u0003לוי\u0004 ברייתא \u0003כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003רב, תני\u0004 \u0005[שנה]\u0006 \u0003לוי\u0004 ברייתא \u0003כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003רב נחמן בר יצחק.\u0004 ומפרטים: \u0003תני\u0004 \u0005[שנה]\u0006 \u0003לוי\u0004 ברייתא \u0003כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003רב: האשה שיוצאה ליהרג ואמרה:\u0004 \u0003\"תנו שערי לבתי\"\u0004 — \u0003נותנין, מתה\u0004 ולא אמרה \"תנו שערי\" — \u0003אין נותנין, מפני שהמת אסור בהנאה.\u0004","ויש לתמוה: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005]\u0006 שהטעם הוא משום שהמת אסור בהנאה, ולא היה צריך להיאמר! \u0003אלא\u0004 צריך לומר שאין מדובר כאן בשיער ממש, אלא בפאה נכרית, ומחדשת הברייתא \u0003ש\u0004גם \u0003נויי המת,\u0004 כגון פאה נכרית, \u0003אסור בהנאה.\u0004","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב נחמן בר יצחק: האשה שמתה\u0004 — \u0003נהנין בשערה, בהמה שנהרגה\u0004 — \u0003אסורה בהנאה; ומה הפרש בין זה לזה? זו\u0004 — \u0003מיתתה אוסרתה, וזו\u0004 — \u0003גמר דינה אוסרתה.\u0004","","\u0003אין נערכין פחות מסלע\u0004 (שקל האמור בתורה), ואפילו עני שאין ידו משגת לשלם את הערך שהעריך — אינו יוצא ידי חובתו בפחות מכך, \u0003ולא יתר על חמשים סלע,\u0004 שהוא הערך הגבוה ביותר, של איש מבן עשרים ועד שישים. \u0003כיצד\u0004 בדיוק חל הדין שאין בערכין פחות מסלע? עני שהעריך אדם שערכו חמישים סלעים, ו\u0003נתן סלע,\u0004 שלא היה בידו יותר, \u0003ו\u0004אחר כך \u0003העשיר\u0004 — \u0003אינו נותן כלום,\u0004 שכבר יצא ידי חובתו בסלע שנתן. אבל אם נתן \u0003פחות מסלע\u0004 — לא יצא ידי חובת נדרו, \u0003ו\u0004אם \u0003העשיר\u0004 אחר כך — \u0003נותן חמשים סלע.\u0004","\u0003היו בידיו\u0004 של העני \u0003חמש סלעים,\u0004 כמה יתן? \u0003רבי מאיר אומר: אינו נותן אלא אחת,\u0004 ויוצא ידי חובתו, \u0003וחכמים אומרים: נותן את כולן,\u0004 את כל מה שבידו, ובכך יוצא ידי חובתו. \u0003אין נערכין פחות מסלע, ולא יתר על חמשים סלע.\u0004 שנינו במשנה: \u0003אין נערכין פחות מסלע.\u0004 ומבררים: \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וכל ערכך יהיה בשקל הקדש\"\u0004 (ויקרא כז, כה), ולמדים מכך ש\u0003כל ערכין שאתה מעריך לא יהו פחותין משקל,\u0004 שאין אדם יוצא ידי חובתו בפחות מכך. ומה שנאמר במשנה: \u0003ולא יתר על חמשים סלעים,\u0004 נלמד מהערך הגבוה שבפרשת ערכין, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"הזכר מבן עשרים שנה ועד בן ששים שנה והיה ערכך \u0003חמשים\u0004 שקל כסף\" (שם ג).","","","שנינו במשנה: \u0003היו בידיו חמשה\u0004 סלעים, רבי מאיר אומר: אינו נותן אלא אחד, וחכמים אומרים: נותן את כולם. ומבררים: \u0003מאי טעמא\u0004 \u0005[מהו הטעם]\u0006 של ר' מאיר? \u0003כתיב\u0004 \u0005[נאמר]\u0006 מתחילה לגבי ערכו של איש מבן עשרים ועד שישים: \"והיה ערכך \u0003חמשים\u0004 שקל\" (ויקרא כז, ג), וכיוצא בזה ערכם של ילדים, נשים וזקנים, כל אחד לפי ערכו, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 מצד אחר: \"וכל ערכך יהיה ב\u0003שקל\"\u0004 (שם כה), ולכן \u0003או\u0004 יתן \u0003חמשים\u0004 — כשידו משגת, \u0003או\u0004 יתן \u0003שקל\u0004 — כשאין ידו משגת.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה יענו על דבריו? ומשיבים: המקרא \u0003ההוא,\u0004 \"וכל ערכך יהיה בשקל\", \u0003ל\u0004למד כי \u0003כל ערכין שאתה מעריך לא יהו פחותים משקל הוא דאתא\u0004 \u0005[שבא],\u0006 שאין יוצאים ידי חובה בפחות מכך, אבל \u0003היכא דאית ליה\u0004 \u0005[במקום שיש לו\u0006 יותר משקל\u0005]\u0006 — על כך הרי \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \"ואם מך הוא מערכך וכו' על פי \u0003אשר תשיג יד הנודר\u0004 יעריכנו הכהן\" (שם ח), \u0003והרי ידו משגת\u0004 יותר משקל, ולכן יתן מה שבידו. ושואלים: \u0003ור' מאיר\u0004 מה הוא משיב על כך? ומשיבים: הכתוב \u0003ההוא,\u0004 ללמד שהולכים אחר השג \u0003יד הנודר ולא\u0004 אחר השג \u0003יד הנידר הוא דאתא\u0004 \u0005[שבא],\u0006 שעני שנדר את ערכו של עשיר נידון לפי השג ידו של הנודר, ואין מתחשבים בכך שהנידר הוא עשיר. ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 מה הם משיבים על כך? והלא בוודאי הוצרך הכתוב לכך! ומשיבים: \u0003לאו ממילא שמעת מינה\u0004 \u0005[\u0006האם \u0005לא מאליו שומע אתה מכאן],\u0006 \u0003דהיכא\u0004 \u0005[שבמקום]\u0006 ש\u0003ידו משגת שקול מיניה\u0004 \u0005[קח ממנו\u0006 לפי השג ידו\u0005]?\u0006 \u0003אמר רב אדא בר אהבה:\u0004 אדם ש\u0003היו בידיו חמש סלעים\u0004 בלבד, שאין די בהם לערך של איש מבוגר, \u0003ואמר \"ערכי עלי\", וחזר ואמר \"ערכי עלי\",\u0004 ונמצא שהתחייב פעמיים, \u0003ונתן ארבע\u0004 סלעים \u0003ל\u0004תשלום הפעם ה\u0003שניה\u0004 שנדר, \u0003ו\u0004אחר כך נתן סלע \u0003אחד ל\u0004שם ה\u0003ראשונה\u0004 — \u0003יצא ידי שתיהן,\u0004 כדין עני שאין ידו משגת, וגם אם העשיר לאחר מכן — אינו צריך לשלם את מלוא ערכו. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 למרות שנכסיו נשתעבדו תחילה לגביית הנדר הראשון, מכל מקום \u0003בעל חוב מאוחר שקדם וגבה\u0004 את חובו — \u0003מה שגבה גבה,\u0004 ואין מוציאים מידו, ולכן יצא ידי חובת השניה באותם ארבעה סלעים.","","","","ואין לומר שלא יצא ידי חובתו מפני שלא נתן את כל חמשת הסלעים שהשיגה ידו באותה שעה, שהרי \u0003בעידנא דיהיב\u0004 \u0005[בזמן שנתן]\u0006 \u0003לשניה\u0004 היה כל כספו \u0003משעבד\u0004 \u0005[משועבד]\u0006 \u0003לראשונה,\u0004 וכאילו לא היה בידו דבר לשלם (אף שבדיעבד יצא ידי נדרו במה שנתן), וכן יצא ידי חובת נדרו הראשון, שהרי \u0003בעידנא דיהיב\u0004 \u0005[בזמן שנתן]\u0006 את הסלע שנותר לו \u0003לראשונה תו לית ליה\u0004 \u0005[שוב אין לו]\u0006 יותר מסלע זה."],["אבל אם \u0003נתן ארבע\u0004 סלעים \u0003לראשונה ו\u0004סלע \u0003אחת לשניה\u0004 — \u0003ידי שניה יצא,\u0004 שהרי לאחר שנתן ארבעה לראשונה לא נותר בידו אלא סלע אחד, ומי שנותן סלע אחד עבור ערכו יוצא ידי חובתו, אך \u0003ידי ראשונה לא יצא\u0004 בארבעה הסלעים, שהרי חמישה הסלעים \u0003כולהו משעבדן\u0004 \u0005[כולם היו משועבדים]\u0006 \u0003לראשונה.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אדא בר אהבה: היו בידו חמש סלעים ואמר \"שני ערכי עלי\"\u0004 \u0003בבת אחת, מהו? כיון\u0004 ש\u0003בבת אחת נדר\u0004 — \u0003כי הדדי תפסן\u0004 \u0005[בבת אחת תופסים]\u0006 שני הנדרים, ולכן \u0003יהיב תרתי ופלגא להאי ותרתי ופלגא להאי\u0004 \u0005[נותן שתי\u0006 סלעים \u0005ומחצה ל\u0006ערך \u0005זה ושתי\u0006 סלעים \u0005ומחצה ל\u0006ערך \u0005זה]\u0006 ויוצא ידי חובתו, \u0003או דלמא כולהו חזיא להאי וכולהו חזיא להאי\u0004 \u0005[שמא כולם ראויים ל\u0006ערך \u0005זה וכולם ראויים ל\u0006ערך \u0005זה],\u0006 ולכן צריך לתת חמישה עבור כל אחד מן הערכים? לא נמצאה תשובה לשאלה זו ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","שנינו במשנה: \u0003אין בערכין פחות מסלע ולא יתר\u0004 על חמישים סלע. ושואלים: \u0003הא תו\u0004 \u0005[\u0006הלכה \u0005זו עוד]\u0006 \u0003למה לי?\u0004 הלא כבר שנינו אותה בתחילת המשנה!","ומשיבים, \u0003הא קמשמע לן\u0004 \u0005[\u0006דבר \u0005זה הוא משמיע לנו]:\u0006 \u0003פחות מסלע הוא דליכא\u0004 \u0005[שאין]\u0006 בערכין, \u0003הא\u0004 \u0005[אבל]\u0006 \u0003יתר על סלע איכא\u0004 \u0005[יש],\u0006 שאם יש בידו יותר מסלע — צריך לשלם כל מה שידו משגת, וכן \u0003יתר על חמשים הוא דליכא\u0004 \u0005[שאין]\u0006 בערכין, \u0003הא\u0004 \u0005[אבל]\u0006 \u0003פחות מחמשים איכא\u0004 \u0005[יש],\u0006 לפי השג ידו. \u0003וסתמא כרבנן\u0004 \u0005[וסתם\u0006 משנה זו באה להכריע הלכה \u0005כחכמים],\u0006 החולקים על ר' מאיר במשנתנו, שאמר כי מי שאין ידו משגת לשלם מלוא ערכו אינו נותן אלא סלע אחד בלבד.","אשה הרואה דם לראשונה בחייה הריהי נידה וטמאה שבעה ימים (בין שראתה יום אחד ובין שראתה שבעה ימים), ואם ביום השביעי פסקה מלראות הריהי טובלת בליל שמיני וטהורה מדין תורה. אחד עשר ימים לאחר מכן (ביום התשעה עשר) חוזרת האשה לתחילת ימי נידתה, שאם תראה דם הריהי טמאה שבעה ימים. ובכל אותם אחד עשר ימים, אם תראה האשה דם — אינה נידה אלא זבה, ואם ראתה בתוך ימים אלו שלושה ימים רצופים — אינה חוזרת לתחילת נידתה עד שתפסיק מלראות, ותספור שבעה ימים נקיים (ובזמן המקדש צריכה להביא קרבן). ועל כך נאמר כי \u0003אין פתח בטועה\u0004 כלומר, אשה שראתה דם ואינה יודעת אם היא בימי נידתה או זיבתה — אינה חוזרת לתחילת (פתח) ימי נידתה ב\u0003פחות משבעה\u0004 ימים נקיים, \u0003ולא יתר על שבעה עשר\u0004 ימים נקיים, בהתאם למספר הימים שהיא רואה דם.","בביאור דברי המשנה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003טועה שאמרה \"יום אחד טמא ראיתי\"\u0004 — \u0003פתחה\u0004 (תחילת נידתה) הריהו בוודאות רק כשתראה דם לאחר \u0003שבעה עשר\u0004 יום נקיים, שאם היום שראתה בו היה הראשון לימי זיבתה, הרי שביום השנים עשר כבר חזרה לימים הראויים לפתוח את נידתה. ואפילו אם היום שראתה בו היה היום הראשון לנידתה — הרי ששת הימים הראשונים עלו לה להשלמת ימי נידתה, ואחד עשר הימים שאחריהם עלו לה להשלמת הימים הראויים לזיבתה. אבל אם תראה ביום השבעה עשר עצמו — עדיין היא בספק, שמא ראתה מתחילה ביום הראשון לנידתה, ויום זה הוא האחרון מימי הזיבה.","אמרה: \u0003\"שני ימים טמא ראיתי\"\u0004 — \u0003פתחה\u0004 לאחר \u0003שבעה עשר\u0004 נקיים. שאמנם, אם שני ימים אלה היו תחילת נידתה, נותרו לה רק ששה עשר יום (חמישה לתשלום ימי נידתה, ואחד עשר ימי זיבתה), ואולם יש לחשוש שמא היום הראשון שראתה בו היה האחרון לימי הזיבה, והיום השני שראתה בו היה הראשון לנידתה, והיא צריכה לספור עוד ששה ימים לימי נידתה ואחד עשר לימי זיבתה, כדי לחזור לפתח נידתה.","אמרה: \u0003\"שלשה ימים טמא ראיתי\"\u0004 — \u0003פתחה\u0004 גם כן רק לאחר \u0003שבעה עשר\u0004 יום נקיים, שמא היומיים הראשונים היו מימי הזיבה והיום השלישי הוא הראשון לנידתה, וצריכה להוסיף ששה ימים להשלים ימי נידתה, ועוד אחד עשר יום עד שתחזור לפתח נידתה.","אמרה: \u0003\"ארבעה ימים טמא ראיתי\"\u0004 — \u0003פתחה\u0004 לאחר \u0003ששה עשר\u0004 יום נקיים, שמא שני הימים הראשונים שראתה בהם היו האחרונים מימי זיבתה, ושני הימים הנוספים היו תחילת נידתה, וצריכה להוסיף חמישה ימים להשלים ימי נידתה, ועוד אחד עשר יום עד שתחזור לפתח נידתה.","אמרה: \u0003\"חמשה ימים טמא ראיתי\"\u0004 — \u0003פתחה\u0004 לאחר \u0003חמשה עשר\u0004 נקיים, שמא שני הימים הראשונים שראתה בהם היו מימי זיבתה, והשלושה האחרונים היו תחילת ימי נידתה, וצריכה להוסיף ארבעה ימים להשלים ימי נידתה, ועוד אחד עשר יום עד שתחזור לפתח נידתה. אמרה: \u0003\"ששה ימים טמא ראיתי\"\u0004 — \u0003פתחה\u0004 לאחר \u0003ארבעה עשר\u0004 ימים נקיים, שמא היומיים הראשונים היו מימי הזיבה, והארבעה שאחריהם תחילת נידתה הם, וצריכה להוסיף שלושה ימים להשלים לשבעה ימי נידתה, ועוד אחד עשר יום עד לפתח נידתה.","אמרה: \u0003\"שבעה ימים טמא ראיתי\"\u0004 — \u0003פתחה\u0004 לאחר \u0003שלשה עשר\u0004 ימים נקיים, שמא היומיים הראשונים מימי זיבתה היו, וחמישה האחרונים מימי נידתה, וצריכה להוסיף שני ימים להשלים ימי נידתה, ועוד אחד עשר יום עד לפתח נידתה.","אמרה: \u0003\"שמונה ימים טמא ראיתי\"\u0004 — \u0003פתחה\u0004 לאחר \u0003שנים עשר\u0004 ימים נקיים, שמא שני הימים הראשונים היו מימי זיבתה, וששה האחרונים מימי נידתה, וצריכה יום אחד להשלים שבעה ימי נידתה, ועוד אחד עשר יום עד לפתח נידתה.","אמרה: \u0003\"תשעה ימים טמא ראיתי\"\u0004 — \u0003פתחה\u0004 לאחר \u0003אחד עשר\u0004 ימים נקיים, שמא שבעה ימים האחרונים ימי נידתה הם, ונותרו לה אחד עשר ימי זיבתה עד תחילת ימי הנידה.","אמרה: \u0003\"עשרה ימים טמא ראיתי\"\u0004 — \u0003פתחה\u0004 לאחר \u0003עשרה\u0004 ימים נקיים, שמא יומיים הראשונים היו מימי זיבתה, והשבעה שאחריהם — שבעה ימי נידתה, והיום האחרון — הראשון לימי זיבתה, וצריכה עוד עשרה ימים עד לפתח נידתה. אמרה: \u0003\"אחד עשר\u0004 ימים טמא ראיתי\" — \u0003פתחה\u0004 לאחר \u0003תשעה\u0004 ימים נקיים, שמא יומיים הראשונים הם מימי זיבתה, ותשעה האחרונים, שבעה מהם היו ימי נידתה, והשנים האחרונים תחילת ימי זיבתה, וצריכה תשעה ימים נוספים כדי להשלים אחד עשר ימי זיבתה עד שתגיע לפתח נידתה."],["אמרה: \u0003\"שנים עשר\u0004 ימים טמא ראיתי\" — \u0003פתחה\u0004 (תחילת ימי נידתה) הוא לאחר \u0003שמונה\u0004 ימים נקיים, שמא שני הימים הראשונים שראתה בהם היו מימי זיבתה, והשבעה שאחריהם היו מימי נידתה, וכשראתה שלושה ימים נוספים בימי זיבתה, נותרו לה עוד שמונה ימים עד סוף ימי זיבתה.","אמרה: \u0003\"שלשה עשר\u0004 ימים טמא ראיתי\" — \u0003פתחה\u0004 לאחר \u0003שבעה\u0004 ימים נקיים, ולא יותר, מפני שגם אם שני הימים הראשונים שראתה בהם היו הימים האחרונים הראויים לזיבתה, והשבעה שאחריהם הם ימי נידתה, נמצא שארבעה הימים האחרונים שראתה בימי זיבתה, ושבעה נקיים שהיא צריכה לספור אחריהם כדין זבה, משלימים לאחד עשר ימי זיבה, ולמחרת הרי זה פתח נידתה.","ונמצא \u0003שאין פתח בטועה פחות משבעה ולא יתר על שבעה עשר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר אהבה לרבה: למה לי כולי האי\u0004 \u0005[כל זה],\u0006 לשם מה צריכה הטועה למנות שבעה עשר יום? \u0003תימני שבעה ותשתרי\u0004 \u0005[תמנה שבעה\u0006 ימים נקיים \u0005ו\u0006לאחריהם \u0005תהיה מותרת\u0006 לבעלה\u0005]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: שבעה עשר ימים אלה לא באו להתירה לבעלה, אלא כדי \u0003לתקונה\u0004 \u0005[לתקן אותה]\u0006 \u0003לידי נדה ופתחה קאמרינן\u0004 \u0005[אומרים אנו],\u0006 שאם תדע מתי ימי נידתה ותראה שלושה ימים או מעט יותר — לא תצטרך למנות עוד שבעה נקיים ולהביא קרבן, כדין ספק זבה, אלא תשלים את שבעת ימי נידתה ותטהר. וכן אם תראה בימי זיבתה יום או יומיים — לא תצטרך לשמור שבעה ימים כנידה, אלא יום אחד ותטהר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003כל\u0004 הנשים \u0003הטועות\u0004 שראו דם ואינן יודעות אם בימי נידתן או בימי זיבתן — נידונות כ\u0003זבות, מביאות קרבן\u0004 של זבה \u0003ואינו נאכל\u0004 מפני הספק, \u0003חוץ מ\u0004זאת שראתה שלושה עשר יום, ששנינו בברייתא לעיל ש\u0003פתחה שבעה, ו\u0004זאת שראתה שנים עשר יום, ש\u0003פתחה שמונה, ש\u0004אלו \u0003מביאות קרבן\u0004 ודאי \u0003ונאכל.\u0004","ותמהים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003כל הטועות זבות\u0004 הן? והרי יש רק חשש שמא הן זבות! \u0003ותו\u0004 \u0005[ועוד],\u0006 מי שראתה \u0003יום אחד\u0004 או \u0003שני ימים בת איתויי\u0004 \u0005[הבאת]\u0006 \u0003קרבן היא?\u0004 והרי רק זבה שראתה שלושה ימים חייבת בקרבן!","\u0003אלא\u0004 כך צריך לשנות בברייתא: \u0003כל זבות\u0004 \u0003הטועות,\u0004 כלומר, כל הנשים שראו דם שלושה ימים לפחות, אלא שאינן יודעות אם הן בימי זיבתן או בימי נידתן — מונות שבעה נקיים ונטהרות בשמיני, ו\u0003מביאות קרבן\u0004 \u0003ואינו נאכל,\u0004 מפני הספק, שמא לא היו זבות. \u0003חוץ מ\u0004הרואה שלשה עשר יום ש\u0003פתחה\u0004 לאחר \u0003שבעה, ו\u0004הרואה שנים עשר יום ש\u0003פתחה שמונה, שמביאות קרבן\u0004 ודאי \u0003ונאכל,\u0004 מפני שבוודאי ראו שלושה ימים בימי זיבתן.","יש נגעי צרעת שהכהן קובע מיד לטהרם או לטמאם באופן מוחלט, ויש נגעים שהכהן צריך להסגירם כדי לקבוע מה דינם. ועל כך נאמר כי \u0003אין בנגעים\u0004 הסגר שהוא \u0003פחות משבוע אחד, ולא יתר על שלשה שבועות.\u0004","ומבארים: מה ששנינו במשנה שאין הסגר שהוא פחות משבוע, מתייחס ל\u0003נגעי אדם,\u0004 שיש בהם נגעים שאם הוסגרו — דינם מוכרע באופן סופי לאחר שבוע של הסגר, והם צרעת השחין (ויקרא יג, יח—כג) וצרעת המכוה (שם כד—כח). ומה ששנינו: \u0003ולא יתר על שלשה שבועות,\u0004 כוונתו ל\u0003נגעי בתים,\u0004 שיש שצריך להסגירם שלשה שבועות עד שיוכרע דינם.","ובהקשר זה \u0003אמר רב פפא:\u0004 מה שנאמר \u0003\"צדקתך כהררי אל\"\u0004 (תהילים לו, ז) — \u0003אלו נגעי אדם,\u0004 שאדם הנענש בצרעת, כשה' עושה עמו צדקה הריהו לוקה בצרעת השחין או המכוה, ודינו מתברר בתוך שבוע בלבד, ומה שנאמר שם: \u0003\"משפטיך תהום רבה\"\u0004 — \u0003אלו נגעי בתים,\u0004 שלפעמים נמשך הסגרם עד שלושה שבועות.","ושואלים: \u0003פשטיה דקרא במאי כתיב\u0004 \u0005[פשוטו של מקרא במה נאמר]?\u0006 \u0003אמר רב יהודה: אלמלא צדקתך כהררי אל\u0004 — \u0003מי יוכל לעמוד לפני משפטיך תהום רבה. רבה אמר: צדקתך כהררי אל\u0004 — \u0003מפני שמשפטיך תהום רבה.\u0004","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה חולקים הם]?\u0006 ומשיבים: \u0003ב\u0004מחלוקתם של \u0003ר' אלעזר ור' יוסי בר' חנינא,\u0004 כיצד נוהג הקדוש ברוך הוא במידת \"רב חסד\", \u0003דאיתמר\u0004 \u0005[שנאמר],\u0006 \u0003ר' אלעזר אמר: כובש,\u0004 נוטל את העוונות מכף החובה ומסתירם, וממילא מכריעה כף הזכות, \u0003ר' יוסי בר' חנינא אמר: נושא,\u0004 מגביה את כף העוונות כדי שתכריע כף הזכות;","\u0003רבה\u0004 סבור \u0003כר' אלעזר,\u0004 שה' כובש את העוונות ומשליכם לתהום (\"משפטיך תהום רבה\"), ומפני כך צדקתו כהררי אל. ורב יהודה סבור \u0003כר' יוסי בר' חנינא,\u0004 שה' מגביה למעלה את כף העוונות, ואם לא צדקה זאת, שהיא כהררי אל — לא יכול האדם לעמוד בפני משפטי ה', שהיו מכריעים את דינו לתהום רבה.","\u0003אין פוחתין מארבעה חדשים המעוברים,\u0004 בני שלושים יום, \u0003בשנה, ולא נראה יתר על שמונה\u0004 (כפי שיבואר בגמרא). \u0003שתי הלחם\u0004 שמקריבים בחג השבועות, ונאכלים בו ביום על ידי הכהנים, \u0003אין נאכלין פחות משנים,\u0004 כלומר, לא לפני היום השני לאפייתם, שכיון שאין אפייתם דוחה את החג — הריהי נעשית בערב החג, \u0003ולא יתר על שלשה,\u0004 כלומר, לא לאחר היום השלישי לאפייתם, והוא במקרה שערב החג חל בשבת, שאז יש להקדים את האפייה ליום שישי. \u0003לחם הפנים אין נאכל פחות מתשעה,\u0004 כלומר, לא לפני היום התשיעי לאפייתו. שהואיל ואין אפייתו דוחה את השבת, הריהו נאפה בערב שבת, ולאחר שהוא מונח על שולחן הפנים משבת לשבת אוכלים אותו הכהנים בשבת, שהיא היום התשיעי לאפייתו. \u0003ולא\u0004 נאכל \u0003יתר על\u0004 היום ה\u0003אחד עשר\u0004 לאפייתו, שאם חלים שני ימים טובים של ראש השנה לפני השבת הריהו נאפה ביום רביעי בשבוע, ערב ראש השנה.","\u0003אין קטן נימול פחות משמונה\u0004 כלומר, לא לפני היום השמיני ללידתו, כמפורש בתורה (ויקרא יב, ג), \u0003ולא יתר על שנים עשר\u0004 ימים מלידתו. שאם נולד בין השמשות (ספק יום ספק לילה) הריהו נימול ביום התשיעי לספיקו, שמא נולד למחרת. ואם נולד בין השמשות של ערב שבת — נימול בעשירי לספיקו, שהוא יום ראשון שלאחר השבת הבאה. שכן אינו נימול ביום שישי הבא — שמא נולד בשבת, ואין זה יומו השמיני, אלא השביעי, ואינו נימול בשבת הבאה — שמא נולד ביום שישי, וזהו יומו התשיעי, ומילה שלא בזמנה אינה דוחה את השבת, ולכן נדחה לאחר השבת. ואם חלו שני ימים טובים של ראש השנה לאחר השבת — הריהו נדחה ליום שלישי בשבוע, שהוא היום השנים עשר ללידתו, מפני שמילה שלא בזמנה אינה דוחה יום טוב.","שואלים, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 מה ששנינו במשנה: \"ו \u0003לא נראה יתר על שמנה\"? אמר רב הונא: לא נראה לחכמים\u0004 שראוי \u0003לעבר יתר על שמונה\u0004 חודשים בשנה. ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003תשעה\u0004 חודשים ש\u0003לא\u0004 מעברים — ש\u0003אם כן\u0004"],["\u0003קדים אתי סיהרא תלתא יומי\u0004 \u0005[מקדים ובא הירח\u0006 של חודש תשרי \u0005שלושה ימים\u0006 לפני ראש השנה\u0005],\u0006 שהרי שנה נשלמת בששה חודשים חסרים וששה חודשים מלאים. וכשמעברים שלושה חודשים יתרים ייראה הירח שלושה ימים לפני ראש השנה, וירננו האנשים על בית הדין שעושה כרצונו ואינו מתחשב כלל במולד הלבנה, והלא \u0003השתא נמי קא קדים אתי תרי יומי\u0004 \u0005[עכשיו גם כן,\u0006 כשמעברים רק שמונה חודשים בשנה, \u0005מקדים הוא\u0006 הירח \u0005ובא שני ימים\u0006 לפני ראש השנה\u0005]!\u0006","ומשיבים: \u0003כדאמר\u0004 \u0005[כשם שאמר]\u0006 \u0003רב משרשיא\u0004 בישוב קושיה אחרת: \u0003כגון שהיתה שנה מעוברת, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש ליישב באופן דומה ולומר: \u0003כגון שהיתה שנה שלפניה מעוברת\u0004 בחודש נוסף, \u0003ועיבור שנה\u0004 היה \u0003חודש\u0004 חסר. ובמקרה זה, \u0003דל ירחא מליא בהדי ירחא חסירא\u0004 \u0005[הורד חודש מלא\u0006 משנה זו \u0005כנגד החודש החסר\u0006 מהשנה הקודמת\u0005],\u0006 ונמצא שרק שבעה חודשים מעוברים משפיעים על המולד של ראש השנה הבא, ולא שמונה. ושואלים: \u0003ואכתי חד יומא\u0004 \u0005[ו\u0006הרי \u0005עדיין\u0006 יראה המולד החדש \u0005יום אחד\u0006 לפני ראש השנה\u0005]!\u0006 ומשיבים: \u0003לא אדעתייהו דאינשי\u0004 \u0005[אין\u0006 זה \u0005על דעתם של האנשים],\u0006 אין הם שמים לב להפרש של יום אחד, ולא יבואו לרנן על בין דין בגללו. עד כאן דנה הגמרא בהסברו של רב הונא לדברי המשנה \"אין נראה יתר על שמונה\" — שאין נראה לחכמים לעבר יותר משמונה חודשים בשנה, בדומה למה ששנינו בתחילה: \"אין פוחתין מארבעה חודשים המעוברים בשנה\".","\u0003עולא אמר:\u0004 כוונת המשנה היא ש\u0003לא נראה לחכמים לחסר יתר על שמונה\u0004 חודשים, \u0003ומאי טעמא קאמר\u0004 \u0005[ומה טעם\u0006 הדין הקודם \u0005הוא אומר]:\u0006 \u0003מה טעם אין פוחתים מארבעה חדשים המעוברים בשנה\u0004 — \u0003משום\u0004 ש\u0003לא נראה לחכמים לחסר יתר על שמונה\u0004 חודשים בשנה, כלומר, לעשות תשעה חודשים חסרים, ושלושה חודשים מעוברים.","ושואלים: \u0003מאי שנא תשעה דלא\u0004 \u0005[במה שונה שלא\u0006 עושים \u0005תשעה\u0006 חודשים חסרים\u0005]\u0006 — מפני ש\u0003אם כן\u0004 נוספו שלושה חודשים חסרים על הראוי, וכך כשיגיע ראש השנה \u0003מייתרא סיהרא תלתא יומי\u0004 \u0005[מתייתר,\u0006 מתאחר מולד \u0005הירח\u0006 \u0005שלושה ימים]\u0006 לאחר ראש השנה, והלא \u0003השתא נמי קא מייתרא תרי יומי\u0004 \u0005[עכשיו גם כן,\u0006 כשמחסרים שמונה חודשים במקום ששה, \u0005מתייתר,\u0006 מתאחר מולד הלבנה \u0005שני ימים]\u0006 לאחר ראש השנה!","ומשיבים: \u0003כדאמר\u0004 \u0005[כשם שאמר]\u0006 \u0003רב משרשיא\u0004 בישוב קושיה אחרת: \u0003כגון שהיתה שנה מעוברת, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש ליישב באופן דומה ולומר: \u0003כגון שהיתה שנה שלפניה מעוברת,\u0004 והיה החודש הנוסף מלא, \u0003דל ירחא חסירא בהדי ירחא מליא\u0004 \u0005[הורד חודש חסר\u0006 משנה זו \u0005כנגד החודש המלא\u0006 מהשנה הקודמת\u0005],\u0006 ונמצא שרק שבעה חודשים חסרים משפיעים על המולד של ראש השנה הבא.","ושואלים: \u0003ואכתי איכא חד יומא\u0004 \u0005[ו\u0006הרי \u0005עדיין יש יום אחד]\u0006 שהירח מתעכב לאחר ראש השנה, וירננו אנשים על בית הדין! ומשיבים, \u0003סברי\u0004 \u0005[סבורים\u0006 האנשים\u0005]:\u0006 \u0003איתחזויי איתחזי ואנן לאו אדעתין\u0004 \u0005[\u0006הירח החדש \u0005נראה\u0006 לבית הדין אתמול, \u0005ואנו לא שמנו לב].\u0006"],["ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה הם חולקים]\u0006 רב הונא ועולא, שנחלקו בפירוש משנתנו, האם מדובר בשמונה חודשים מלאים או חסרים? ומשיבים: \u0003ב\u0004מספר ימי החודש של \u0003עיבור שנה, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003כמה\u0004 ימים בחודש \u0003עיבור\u0004 ה\u0003שנה? שלשים\u0004 יום, \u0003רבן שמעון בן גמליאל אומר: חודש,\u0004 בן עשרים ותשעה יום. רב הונא שפירש שמשנתנו עוסקת בשמונה חודשים מלאים בשנה, סבור כרבן שמעון בן גמליאל, ולפיכך, אם השנה הקודמת היתה מעוברת בחודש חסר, הרי גם אם עושים בשנה זו שמונה חודשים מלאים — יקדים המולד את ראש השנה ביום אחד בלבד. ואילו עולא סבור כחכמים, שחודש העיבור לעולם מלא, ולפיכך אין אפשרות לשמונה חודשים מלאים בשנה, מפני שכך מקדים המולד את ראש השנה ביומיים. ולכן פירש משנתנו בשמונה חודשים חסרים.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטת רב הונא ממה ששנינו בברייתא: \u0003אין עצרת\u0004 (חג השבועות) \u0003חלה אלא ביום הנף,\u0004 כלומר, באותו יום מימי השבוע שחל בו ששה עשר בניסן, יום הנפת העומר. \u0003ואין ראש השנה\u0004 הבא \u0003חלה אלא או ב\u0004אותו יום בשבוע שחל בו \u0003יום הנף, או לאור עיבורו,\u0004 כלומר, למחרתו. ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003עולא,\u0004 ש\u0003שמונה\u0004 חודשים \u0003חסירין\u0004 בשנה \u0003עבדינן\u0004 \u0005[עושים אנו],\u0006 אבל שמונה חודשים \u0003מעוברין לא עבדינן\u0004 \u0005[אין אנו עושים]\u0006 — \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה\u0006 את מה ששנינו בברייתא\u0005],\u0006 כיצד?","\u0003שניהן חסר,\u0004 כלומר, כשהופכים בשנה זו שני חודשים (שכרגיל הם מלאים) לחסרים, ואז עושים אחד מהם בחדשי הקיץ, כגון סיון — מקדים ראש השנה ביום אחד, ואז הוא חל \u0003ב\u0004אותו יום בשבוע שחל בו \u0003יום הנף.\u0004","ואם היתה השנה כסדרה, \u0003אחד מלא ואחד חסר\u0004 — חל ראש השנה \u0003לאור עיבורו,\u0004 כלומר, למחרת יום הנף.","\u0003אלא ל\u0004שיטת \u0003רב הונא\u0004 ש\u0003אמר: עבדינן\u0004 \u0005[עושים אנו]\u0006 שמונה חודשים \u0003מעוברין\u0004 בשנה, \u0003הא זימנין דמשכחת\u0004 \u0005[הרי פעמים שאתה מוצא]\u0006 שראש השנה חל באותו יום בשבוע שהוא \u0003לאור אור עיבורו,\u0004 כלומר, יומיים לאחר יום שחל בו יום הנף, ושלא כדברי הברייתא. שהרי כשהחודשים כסדרם, אחד מלא ואחד חסר, יחול ראש השנה לאור עיבורו. וכשהופכים שני חודשים חסרים בשנה לחודשים מלאים, ועושים אחד מהם בקיץ (בין יום הנף לראש השנה), יחול ראש השנה יום אחד מאוחר מהרגיל!","ומשיבים, \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך רב הונא: ול\u0004שיטת \u0003עולא מי ניחא\u0004 \u0005[האם נוחה\u0006 הברייתא\u0005]?\u0006 והרי גם לשיטתו, \u0003שמונה\u0004 מלאים \u0003הוא דלא עבדינן\u0004 \u0005[שאין אנו עושים],\u0006 \u0003הא\u0004 \u0005[אבל]\u0006 \u0003שבעה\u0004 מלאים \u0003עבדינן\u0004 \u0005[אנו עושים].\u0006 והרי גם כשעושים רק \u0003שבעה\u0004 חודשים מלאים, \u0003זימנין דלא עבדינן בסיתוא ועבדינן בקייטא\u0004 \u0005[פעמים שאין אנו עושים\u0006 את החודש המלא הנוסף \u0005בחורף, ואנו עושים\u0006 אותו \u0005בקיץ],\u0006 בין יום הנף לראש השנה, \u0003והא הוה\u0004 \u0005[והרי\u0006 גם במקרה זה \u0005חל]\u0006 ראש השנה באותו יום בשבוע שחל \u0003לאור אור עיבורו\u0004 (יומיים לאחר יום הנף), ומדוע לא הזכירה הברייתא גם אופן זה?","\u0003אלא\u0004 יש לומר כי \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 כשיטת \u0003אחרים היא,\u0004 החולקים על משנתנו, וסבורים כי אפילו שבעה חדשים מלאים אין עושים; \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003אחרים אומרים:\u0004 חודשי השנה הולכים כסדרם לעולם, אחד מלא ואחד חסר, וכך יש בשנה שלוש מאות חמישים וארבעה ימים, חמישים שבועות מלאים ועוד ארבעה ימים. ולפי זה לעולם \u0003אין בין עצרת לעצרת,\u0004 כלומר, בין היום בשבוע שחלה בו העצרת בשנה שעברה לבין היום בשבוע שחלה בו העצרת בשנה זו, \u0003ו\u0004כן \u0003אין בין ראש השנה לראש השנה, אלא ארבעה ימים בלבד, ואם היתה שנה מעוברת\u0004 ונוסף עליה חודש, שהוא בן עשרים ותשעה יום (ארבעה שבועות ויום אחד) — יש \u0003חמשה\u0004 ימים בין עצרת שבשנה זו לעצרת שבשנה שאחריה.","ומקשים: \u0003סוף סוף,\u0004 כשאתה הולך לדרך זו, הרי \u0003ל\u0004שיטת \u0003אחרים,\u0004 מה ששנינו בברייתא שראש השנה יחול \u0003ב\u0004אותו יום שחל בו \u0003יום הנף\u0004 — \u0003לא משכחת לה\u0004 \u0005[אין אתה מוצא אותה],\u0006 שהרי לשיטתם לעולם אין מחסרים חודש נוסף בקיץ, ואם כן לעולם יבוא ראש השנה רק למחרתו!","אמר רב משרשיא: ייתכן הדבר לשיטת אחרים, \u0003כגון שהיתה שנה\u0004 זו \u0003מעוברת, ו\u0004חודש אדר שנוסף כ\u0003עיבור\u0004 ה\u0003שנה\u0004 היה בן \u0003שלשים יום,\u0004 וכך נמצא ראש השנה מתעכב יום נוסף, ויש הפרש של ששה ימים בין ראש השנה הקודם וראש השנה הבא. ומכיוון שלשיטת אחרים אין בין ראש השנה לראש השנה אלא חמישה ימים, יש להפוך אחד מחודשי הקיץ המלאים לחודש חסר, ואז \u0003דל ירחא לבהדי ירחא\u0004 \u0005[הורד חודש\u0006 חסר שעשית בקיץ \u0005כנגד חודש\u0006 העבור\u0005],\u0006 שהיה מלא, וכך נשמרת המסגרת. וחיסור זה של יום אחד מחודשי הקיץ מביא לכך \u0003דמשכחת לה\u0004 \u0005[שמוצא אתה את\u0006 ראש השנה\u0005]\u0006 חל \u0003ב\u0004אותו יום בשבוע שחל בו \u0003יום הנף,\u0004 יום אחד מוקדם מן הרגיל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר אהבה לרבא\u0004 בתמיהה: החכם המכונה \u0003\"אחרים\", מנינא אתא לאשמועינן\u0004 \u0005[מנין\u0006 הימים שבין ראש השנה לראש השנה \u0005בא להשמיענו]?\u0006 די היה שיאמר באופן עקרוני, שאין משנים כלל מסדר החודשים אחד מלא ואחד חסר, וממילא היינו יודעים שאין בין עצרת לעצרת אלא ארבעה ימים בלבד! אמר לו רבא: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר נוסף \u0005זה הוא משמיע לנו],\u0006 \u0003דלא בעינן\u0004 \u0005[שאין אנו צריכים]\u0006 להתחשב בכך ש\u0003מצוה לקדש על פי הראיה,\u0004 אלא כשהחודש צריך להיות חסר לפי סדר החודשים — מקדשים את החודש הבא ביום השלושים, גם אם לא נראתה הלבנה.","ועוד \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא\u0004 על שיטת \"אחרים\": כיצד ייתכן שההפרש בין שנה לשנה הוא לעולם בן ארבעה ימים? והלא שנת הלבנה היא שלוש מאות חמישים וארבעה ימים, ועוד שמונה שעות, ושמונה מאות ושבעים וששה חלקי שעה (מתוך אלף ושמונים), \u0003ו\u0004לפי זה, \u0003האיכא יומא דשעי\u0004 \u0005[הרי\u0006 בכל שלוש שנים \u0005יש יום\u0006 נוסף \u0005ש\u0006הצטבר מתוספת שמונה \u0005השעות\u0006 שבכל שנה\u0005],\u0006 \u0003ו\u0004כן יש \u0003יומא דתלתין שני\u0004 \u0005[יום ש\u0006נוסף לכל \u0005שלושים שנה],\u0006 ומהצטברות שמונה מאות ושבעים וששה החלקים הנוספים שבכל שנה! ומשיבים: \u0003כיון דליתיה בכל שתא לא קא חשיב\u0004 \u0005[כיוון ש\u0006יום זה \u0005אינו\u0006 נוסף \u0005בכל שנה אין הוא מחשיב\u0006 אותו בברייתא\u0005].\u0006 ושבים למחלוקת רב הונא ועולא בפירוש משנתנו.","ומעירים: \u0003ואף שמואל סבר לה\u0004 \u0005[סבור באותה\u0006 מחלוקת\u0005]\u0006 \u0003כרב הונא,\u0004 שעושים שמונה חודשים מלאים בשנה, ש\u0003אמר שמואל: אין שנת לבנה פחותה משלש מאות וחמשים ושתים יום, ולא יתירה על שלש מאות וחמשים וששה יום,\u0004","\u0003הא כיצד?\u0004 כאשר שני חודשים שבדרך כלל הם חסרים נעשים \u0003שניהם מלאין\u0004 — שנת הלבנה היא בת שלוש מאות וחמישים ו\u0003ששה\u0004 יום. כאשר שני חודשים שבדרך כלל הם מלאים נעשים \u0003שניהם חסירין\u0004 — היא בת שלוש מאות וחמישים ו\u0003שנים\u0004 יום. וכאשר החודשים כסדרם \u0003אחד מלא ואחד חסר\u0004 — מנין הימים שבשנה זו הוא שלוש מאות וחמישים ו\u0003ארבעה\u0004 יום. הרי שהוא סבור ששנה יכולה להיות בת שני חודשים מלאים נוספים, ובסך הכל שמונה חודשים מלאים.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטה זו, ממה ששנינו בברייתא: אמר \u0003\"הריני נזיר כימות החמה\"\u0004 — \u0003מונה נזירות שלש מאות וששים וחמשה ימים, כמנין ימות החמה.\u0004 אמר: \"הריני נזיר \u0003כימות הלבנה\"\u0004 — \u0003מונה נזירות שלש מאות וחמשים וארבעה ימים כמנין ימות הלבנה. ואם איתא, זימנין דמשכחת לה ששה\u0004 \u0005[ואם יש\u0006 מקום לשיטה שמעברים שמונה חודשים בשנה, \u0005פעמים שאתה מוצא\u0006 בשנת הלבנה שלוש מאות וחמישים ו\u0005ששה\u0006 ימים\u0005]!\u0006","ומשיבים: \u0003בנדרים הלך אחר לשון בני אדם ורוב שנים,\u0004 וכוונת הנודר היתה בוודאי לשנה המצויה, שהיא בת שלוש מאות וחמישים וארבעה ימים.","ומוסיפים: \u0003ואף רבי סבר לה\u0004 \u0005[סבור באותה\u0006 מחלוקת\u0005]\u0006 \u0003כרב הונא,\u0004 שאפשר לעשות שמונה חודשים מלאים בשנה, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003מעשה ועשה רבי כרב הונא תשעה\u0004 חודשים \u0003חסירים\u0004 בשנה, \u0003ו\u0004למרות זאת \u0003נראה חודש\u0004 (הירח החדש) \u0003בזמנו,\u0004 כלומר, ביום המיועד לראש השנה ולא אחר כך, \u0003והיה רבי תמיה ואומר: עשינו תשעה חסירין, ונראה חודש בזמנו! אמר לפניו ר' שמעון בר רבי: שמא שנה מעוברת היתה\u0004 השנה הקודמת,"],["\u0003ו\u0004החודש שנוסף ל\u0003עיבור\u0004 ה\u0003שנה\u0004 היה מלא, בן \u0003שלשים\u0004 יום, ו\u0003אישתקד\u0004 (שנה שעברה), שני חודשים שכרגיל הם חסרים \u0003עשינו\u0004 את \u0003שניהם מלאין, דל תלתא לבהדי תלתא, וקם ליה בדוכתיה\u0004 \u0005[הורד שלושה\u0006 חודשים מלאים אלו \u0005כנגד שלושה\u0006 חודשים חסרים נוספים שעשינו השנה, \u0005ועמד לו\u0006 הירח \u0005במקומו,\u0006 בזמנו\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי לר' שמעון בנו: \u0003נר ישראל,\u0004 מאיר עיני חכמים, אמנם \u0003כן הוה\u0004 \u0005[היה].\u0006","\u0003אין פוחתין מעשרים ואחת תקיעות\u0004 של חצוצרות \u0003במקדש\u0004 בכל יום, שלוש (תקיעה תרועה תקיעה) לפתיחת שערי העזרה, תשע (שלוש סדרות של תקיעה תרועה תקיעה) בשעה שהיו הלויים אומרים שיר של יום בזמן הקרבת נסכי תמיד של שחר, ותשע בתמיד של ערב, \u0003ולא מוסיפין על ארבעים ושמנה\u0004, שבערב שבת שחל בסוכות הוסיפו עליהן שתים עשרה תקיעות לניסוך המים, ותשע למוספים, ושלוש להפסיק את העם ממלאכה, ושלוש להבדיל בין חול לקודש.","בזמן שהלויים אומרים שירה ומלווים אותם בנגינה בכלי שיר \u0003אין פוחתין משני נבלים,\u0004 \u0003ולא מוסיפין על ששה. אין פוחתין משני חלילין, ולא מוסיפין על שנים עשר\u0004 חלילים. \u0003ובשנים עשר יום בשנה החליל מכה\u0004 (מנגן) \u0003לפני המזבח\u0004 כשהלויים אומרים שירה על הקרבן: \u0003ב\u0004זמן \u0003שחיטת פסח ראשון,\u0004 בארבעה עשר בניסן, \u0003וב\u0004זמן \u0003שחיטת פסח שני,\u0004 בארבעה עשר באייר, \u0003ו\u0004ב\u0003יום טוב הראשון של פסח, וביום טוב של עצרת\u0004 (שבועות), \u0003ובשמונת ימי החג. ולא היה מכה באבוב\u0004 (בחליל) \u0003של נחשת, אלא באבוב של קנה, מפני שקולו ערב; ולא היה מחלק\u0004 ומסיים את פרקי הנגינה \u0003אלא באבוב יחידי, מפני שהוא מחליק\u0004 ומסיים \u0003יפה\u0004 את הנגינה.","\u0003ועבדי כהנים היו\u0004 המנגנים, אלו \u0003דברי רבי מאיר; ר' יוסי אומר:\u0004 ישראלים היו, מ\u0003משפחת בית פגרים ובית ציפרא מ\u0004העיר \u0003עמאום,\u0004 ו\u0003היו\u0004 אלו משפחות מיוחסות, שהיו \u0003משיאין\u0004 את בנותיהם \u0003ל\u0004משפחות \u0003כהונה; ר' חנינא בן אנטיגנוס אומר: לוים היו\u0004 המנגנים.","שנינו במשנה שאין פוחתים מעשרים ואחת תקיעות במקדש ולא מוסיפים על ארבעים ושמונה תקיעות. ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' יהודה\u0004 היא, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא בעניין זה], \u0003ר' יהודה אומר: לא יפחות משבע\u0004 תקיעות, ו\u0003לא יוסיף על שש עשרה\u0004 כלומר, שליש ממספר התקיעות שנמנו במשנתנו.","ומבררים: \u0003במאי קמיפלגי\u0004 \u0005[במה הם חולקים]?\u0006 \u0003ר' יהודה סבר\u0004 \u0005[סבור]:\u0006 סדר תקיעות של \u0003תקיעה תרועה ותקיעה,\u0004 שבו היו תוקעים לדעת הכל בכל פעם — \u0003חדא\u0004 \u0005[\u0006מצוה \u0005אחת]\u0006 \u0003היא, ורבנן סברי\u0004 \u0005[סבורים]:\u0006 מצות \u0003תקיעה לחוד, ו\u0004מצות \u0003תרועה לחוד, ו\u0004מצות \u0003תקיעה\u0004 שלאחריה \u0003לחוד,\u0004 ולכן המניינים שמנו חכמים גדולים פי שלושה מהמניינים של ר' יהודה.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור לדבריו\u0005]\u0006 של \u0003ר' יהודה?\u0004 ומשיבים: \u0003כתיב\u0004 \u0005[נאמר]\u0006 בפרשת החצוצרות: \u0003\"ותקעתם תרועה\"\u0004 (במדבר י, ו), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 מיד אחר כך באותו פסוק: \u0003\"תרועה יתקעו לכם\" שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003תקיעה תרועה ותקיעה\u0004 שנזכרו לחילופין בפסוק זה ברצף אחד — \u0003חדא\u0004 \u0005[\u0006מצוה \u0005אחת]\u0006 \u0003היא.\u0004 ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 שאינם סבורים כן, מה הם למדים מכתוב זה? ומשיבים: הכתוב \u0003ההוא, לפשוטה לפניה ופשוטה לאחריה הוא דאתא\u0004 \u0005[שבא],\u0006 כלומר, ללמדנו שלפני כל תרועה יש תקיעה (\"ותקעתם תרועה\") וגם לאחריה (\"תרועה יתקעו\").","ושואלים: \u0003ורבנן מאי טעמא\u0004 \u0005[וחכמים, מה טעם]\u0006 הם מחשיבים כל אחת בפני עצמה? ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ובהקהיל את הקהל תתקעו ולא תריעו\"\u0004 (שם ז), \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 שסדר של \u0003תקיעה תרועה ותקיעה חדא\u0004 \u0005[\u0006מצוה \u0005אחת]\u0006 \u0003היא, אמר רחמנא עביד פלגא דמצוה\u0004 \u0005[\u0006האם \u0005אומרת התורה לעשות חצי מצוה]?\u0006 אלא מכאן שתקיעה היא מצוה בפני עצמה, וסדר של תקיעה תרועה תקיעה נחשב לשלש מצוות. ושואלים: \u0003ור' יהודה,\u0004 מה הוא עונה על דבריהם? ומשיבים: אותה תקיעה שנזכרה בענין זה, \u0003סימנא בעלמא\u0004 \u0005[סימן בלבד]\u0006 \u0003הוא\u0004 לכנס את הקהל, ואינה מצוה.","ומעירים: \u0003כמאן אזלא הא\u0004 \u0005[כ\u0006דעת \u0005מי הולכת\u0006 הלכה \u0005זו]\u0006 ש\u0003אמר רב כהנא: אין בין תקיעה לתרועה ולא כלום,\u0004 כלומר שלא יפסיק בין התקיעה לתרועה, ובין התרועה לתקיעה, \u0003כמאן\u0004 \u0005[כמי]?\u0006 \u0003כ\u0004דעת \u0003ר' יהודה,\u0004 שסדר זה נחשב למצוה אחת, וממילא נאסר להפסיק בה. ותמהים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005],\u0006 ומדוע היה צורך לבאר זאת!","ומשיבים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 הלכה זו אפילו כרבנן אתיא \u0005[כ\u0006שיטת \u0005חכמים באה],\u0006 \u0003ו\u0004לא באה ללמד שאין להפסיק ביניהן כלל, אלא \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' יוחנן\u0004 ש\u0003אמר:\u0004 \u0003שמע\u0004 בראש השנה \u0003תשע תקיעות, בתשע שעות ביום,\u0004 כל אחת בשעה אחרת — \u0003יצא\u0004 ידי חובתו מן התורה, ולהשמיענו שאסור להפסיק בשהייה גדולה ביניהן, על כן \u0003קא משמע לן\u0004 \u0005[משמיע הוא לנו]\u0006 שהלכה זו נאמרה לשיטת ר' יהודה.","ושואלים: \u0003ואימא הכי נמי\u0004 \u0005[ואמור כך גם כן]\u0006 שהיא כחכמים! ומשיבים: \u0003אם כן, מאי\u0004 \u0005[מה היא]\u0006 לשון \u0003\"ולא כלום\"?\u0004 שלשון זו משמעה שאסור להפסיק אפילו בשהייה קטנה ביותר, ומכאן שהלכה זו היא כדעת ר' יהודה.","שנינו במשנה: \u0003שנים עשר יום בשנה מכה בחליל\u0004 לפני המזבח: בשחיטת פסח ראשון, ובשחיטת פסח שני, וביום טוב הראשון של פסח, וביום טוב של עצרת, ובשמונת ימי החג\u0003.\u0004 ושואלים: \u0003מאי שנא הני\u0004 \u0005[במה שונים אלו]\u0006 מימים אחרים? ומשיבים: \u0003הואיל\u0004 וימי שמחה הם, \u0003ו\u0004כל \u0003יחיד גומר בהן את\u0004 \u0003ההלל.\u0004","ש\u0003אמר ר' יוחנן משום ר' שמעון בן יהוצדק:\u0004 אלו \u0003שמונה עשר ימים שהיחיד גומר בהן את ההלל: שמונה ימי החג\u0004 (סוכות), \u0003ושמונה ימי חנוכה, ויום טוב הראשון של פסח, ויום טוב הראשון של עצרת; ובגולה,\u0004 שעושים שני ימים טובים מספק, הם \u0003עשרים ואחד\u0004 ימים: \u0003תשעה ימי החג, ושמונה ימי חנוכה, ושני ימים טובים של פסח, ושני ימים טובים של עצרת.\u0004","ושואלים: \u0003מאי שנא בחג דאמרינן כל יומא\u0004 \u0005[במה שונה\u0006 הדין \u0005בחג\u0006 הסוכות \u0005שאומרים אנו\u0006 הלל \u0005כל יום],\u0006 \u0003ומאי שנא בפסח דלא אמרינן\u0004 \u0005[ובמה שונה\u0006 הדין \u0005בפסח שאיננו אומרים]\u0006"],["\u0003כל יומא\u0004 \u0005[כל יום]?\u0006 ומשיבים: ימי ה\u0003חג חלוקין בקרבנותיהן,\u0004 שהרי מספר הפרים שמקריבים למוסף מתמעט כל יום מימי החג (ראה במדבר כט, יב—לח), ומפני החידוש שיש בכל אחד מן הימים אומרים בו הלל, ואילו ימי ה\u0003פסח אין חלוקין בקרבנותיהן\u0004 זה מזה, ולכן גומרים את ההלל רק ביום הראשון של פסח, מפני שבו יש חידוש ביחס לימים שלפניו.","ושואלים: \u0003שבת\u0004 ש\u0003חלוקה בקרבנותיה\u0004 מימי השבוע \u0003לימא\u0004 \u0005[שיאמר\u0006 בה הלל\u0005]!\u0006 ומשיבים: שבת \u0003לא איקרי\u0004 \u0005[לא נקראת]\u0006 \u0003\"מועד\",\u0004 והלל אומרים רק בימים שנקראו מועד, שיש בהם שמחה מיוחדת.","ושואלים: \u0003ראש חודש\u0004 \u0003דאיקרי\u0004 \u0005[שנקרא]\u0006 \u0003\"מועד\" לימא\u0004 \u0005[שיאמר\u0006 בו הלל\u0005]!\u0006 ומשיבים: ראש חודש \u0003לא איקדיש\u0004 \u0005[הוקדש]\u0006 \u0003ב\u0004איסור \u0003עשיית מלאכה,\u0004 ואומרים הלל רק במועדים חגיגיים במיוחד האסורים בעשיית מלאכה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"השיר יהיה לכם כליל התקדש חג\"\u0004 (ישעיה ל, כט), כלומר, שהשיר (ההלל) על הגאולה יהיה כהלל הנאמר בליל חג הפסח שבכל שנה. ומ\"התקדש\" למדים ש\u0003לילה המקודש לחג\u0004 כלומר, שאסור במלאכה — \u0003טעון שירה\u0004 (הלל), \u0003ו\u0004לילה (או יום) \u0003שאין מקודש לחג\u0004 — \u0003אין טעון שירה.\u0004","ושואלים: \u0003ראש השנה ויום הכיפורים דאיקרו\u0004 \u0005[שנקראו]\u0006 \u0003\"מועד\" ואיקדוש\u0004 \u0005[ונתקדשו]\u0006 \u0003בעשיית מלאכה, לימא\u0004 \u0005[שיאמר\u0006 בהם הלל\u0005]!\u0006 ומשיבים: אין אומרים בהם הלל \u0003משום\u0004 דברי \u0003ר' אבהו,\u0004 ש","\u0003אמר ר' אבהו, אמרו מלאכי השרת לפני הקדוש ברוך הוא: רבונו של עולם, מפני מה אין ישראל אומרים שירה\u0004 (הלל) \u0003לפניך בראש השנה וביום הכפורים? אמר להן: אפשר, מלך יושב על כסא הדין, וספרי חיים וספרי מתים פתוחין לפניו, וישראל אומרים שירה לפני?\u0004","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003חנוכה דלא הכי ולא הכי\u0004 \u0005[שלא כך ולא כך],\u0006 שאין בו קרבן מיוחד, ולא נתקדש באיסור מלאכה, \u0003וקאמר\u0004 \u0005[ואומר\u0006 היחיד הלל\u0005]!\u0006 ומשיבים: טעם אמירת ההלל בחנוכה אינו משום הקדושה שיש בו, אלא \u0003משום ניסא\u0004 \u0005[הנס]\u0006 שהיה באותם ימים. ושואלים: אם כן, \u0003פורים דאיכא ניסא לימא\u0004 \u0005[שיש\u0006 בו \u0005נס, שיאמר\u0006 הלל\u0005]!\u0006 \u0003אמר ר' יצחק: לפי שאין אומרים שירה על נס שבחוצה לארץ.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב נחמן בר יצחק: והרי יציאת מצרים\u0004 ש\u0003נס שבחוצה לארץ הוא, ואמרינן\u0004 \u0005[ואומרים אנו]\u0006 עליו \u0003הלל!\u0004 ומשיבים: הטעם הוא \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בבריתא\u0005]:\u0006 \u0003עד שלא נכנסו ישראל לארץ\u0004 — \u0003הוכשרו\u0004 (ראויות היו) \u0003כל הארצות לומר שירה\u0004 על נס שאירע בהן, \u0003משנכנסו לארץ\u0004 — \u0003לא הוכשרו\u0004 שאר \u0003כל\u0004 ה\u0003ארצות לומר שירה.\u0004","\u0003רב נחמן אמר\u0004 טעם אחר: \u0003קרייתה זו היא הלילא\u0004 \u0005[קריאת\u0006 המגילה \u0005היא ההלל]\u0006 של פורים. \u0003רבא אמר\u0004 טעם אחר: \u0003בשלמא התם\u0004 \u0005[נניח שם],\u0006 בנס יציאת מצרים, יכולים אנו לומר בהלל \u0003\"הללו עבדי ה' \"\u0004(תהלים קיג,א) — \u0003ולא עבדי פרעה,\u0004 מזכירים אנו את הנס של היציאה משעבוד מצרים, אבל \u0003הכא\u0004 \u0005[כאן],\u0006 בפורים, האם ניתן לומר \u0003הללו עבדי ה'\u0004 — \u0003ולא עבדי אחשורוש?\u0004 והלא גם לאחר הנס, \u0003אכתי\u0004 \u0005[עדיין]\u0006 \u0003עבדי אחשורוש אנן\u0004 \u0005[אנו]! ושואלים,\u0006","\u0003ול\u0004הסברו של \u0003רב נחמן\u0004 ש\u0003אמר: קרייתה זו היא הלילא\u0004 \u0005[קריאת\u0006 המגילה \u0005זו היא\u0006 אמירת \u0005הלל],\u0006 כיצד אומרים הלל על נס פורים שהיה בחוצה לארץ? \u0003התניא\u0004 \u0005[\u0006ו\u0005הרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003משנכנסו לארץ\u0004 — \u0003לא הוכשרו כל ארצות לומר שירה!\u0004 ומשיבים: \u0003כיון שגלו\u0004 מהארץ — \u0003חזרו להיתירן הראשון,\u0004 לומר שירה גם על נס שבחוצה לארץ.","שנינו במשנה: החליל מכה לפני המזבח... ו\u0003לא היה מכה באבוב של נחושת\u0004 אלא באבוב של קנה, מפני שקולו ערב. ותמהים: \u0003פתח\u0004 \u0005[פותח]\u0006 התנא \u0003בחליל ומסיים באבוב! אמר רב פפא: היינו חליל היינו אבוב, ואמאי קרי ליה\u0004 \u0005[ומדוע קורא לו\u0006 התנא\u0005]\u0006 \u0003חליל? דחלי קליה\u0004 \u0005[\u0006מפני \u0005שמתוק קולו]\u0006 לשמיעה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003אבוב היה במקדש, חלק היה, דק היה\u0004 בדפנותיו, \u0003של קנה היה, ומימות משה\u0004 רבינו \u0003היה. צוה המלך וציפוהו זהב, ולא היה קולו ערב, נטלו את צפויו והיה קולו ערב כמות שהיה.\u0004 וכן \u0003צלצול\u0004 (מצלתיים) \u0003היה במקדש, של נחושת היה, והיה קולו ערב, ונפגם, ושלחו חכמים והביאו אומנין מאלכסנדריא של מצרים ותקנוהו, ולא היה קולו ערב, נטלו את תיקונו והיה קולו ערב כמות שהיה\u0004 קודם שתיקנוהו.","וכן \u0003מכתשת היתה במקדש, של נחושת היתה, ומימות משה היתה, והיתה מפטמת\u0004 (היו רוקחים בה) את הבשמים לצורך הקטורת, \u0003נתפגמה והביאו אומנין מאלכסנדריא של מצרים ותיקנוה, ולא היתה מפטמת כמו שהיתה, נטלו את תיקונה והיתה מפטמת כמו שהיתה\u0004 קודם שתיקנוה.","\u0003אלו שני כלים\u0004 של נחושת (צלצול ומכתשת) \u0003נשתיירו ממקדש ראשון, ונתפגמו ולא היה להם ארוכה\u0004 (רפואה), כלומר, לא הועיל להם התיקון, \u0003ועליהם,\u0004 על כלי הנחושת שמזמן בית ראשון, \u0003אמר דוד:\u0004 \"כל הכלים האלה אשר עשה חירם למלך שלמה בית ה' \u0003נחשת ממורט\"\u0004 (מלכים א ז, מה), וכן נאמר בכתוב המקביל \u0003\"נחושת ממורק\"\u0004 (דברי הימים ב ד, טז), כלומר, מלוטש ומבריק, \u0003ועליהם\u0004 (על הצלצול והמכתשת) \u0003הוא אומר\u0004 ברשימת הכלים שהעלה עזרא לירושלים: \u0003\"וכלי נחשת מצהב שנים חמודות מזהב\"\u0004 (עזרא ח, כז).","ואגב מביאים מה שנחלקו \u0003רב ושמואל\u0004 בפירוש הביטוי \"שנים חמודות מזהב\", \u0003חד\u0004 \u0005[אחד]\u0006 \u0003אמר: כל אחד ואחד שקול כשנים של זהב, וחד\u0004 \u0005[ואחד]\u0006 \u0003אמר:\u0004 \u0003שניהם שקולין כאחד של זהב. תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף\u0004 בברייתא: \u0003שניהם שקולין כאחד של זהב.\u0004","ועוד \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 אחרת בפירוש ביטוי זה, \u0003ר' נתן אומר: שניים\u0004 (כפולים) \u0003היו, שנאמר: שנים, אל תיקרי \"שנים\" אלא \"שניים\".\u0004","\u0003תני\u0004 \u0005[שנה\u0006 בברייתא\u0005]\u0006 \u0003רבן שמעון בן גמליאל\u0004 אומר: מעין ה\u0003שילוח היה מקלח מים ב\u0004פתח שגודלו \u0003כ\u0004מטבע הקרוי \u0003איסר, צוה המלך והרחיבוהו כדי שיתרבו מימיו, ונתמעטו, וחזרו ומיעטוהו והיה מקלח מים\u0004 כמו שהיה, וכל זה בא \u0003לקיים מה שנאמר: \"אל יתהלל חכם בחכמתו ואל יתהלל גבור בגבורתו\"\u0004 (ירמיה ט, כב), שלא יחשוב האדם שכל דבר הוא מסוגל לעשות על ידי חכמתו.","\u0003וכן היה רבן שמעון בן גמליאל אומר\u0004 בענייני כלי הנגינה שבמקדש: כלי נגינה הנקרא \u0003הרדולים לא היה במקדש.\u0004 ומבררים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003הרדולים? אמר אביי: טבלא גורגדנא\u0004 (מעין פעמון). וטעם הדבר שלא היה במקדש — \u0003מפני שקולו ערב ומערבב את הנעימה.\u0004","\u0003אמר רבא בר שילא אמר רב מתנה אמר שמואל: מגריפה היתה במקדש,\u0004"],["\u0003עשרה נקבים היו בה,\u0004 ו\u0003כל אחד ואחד\u0004 מהם \u0003מוציא עשרה מיני זמר, נמצאת כולה מוציאה מאה מיני זמר. במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 המגריפה \u0003היא אמה\u0004 ברוחבה, \u0003וגבוה אמה, וקתא\u0004 (ידית) \u0003יוצא הימנה,\u0004 חלולה \u0003ועשרה נקבים היו בה,\u0004 ו\u0003כל אחד\u0004 מהם \u0003מוציא מאה מיני זמר, נמצאת כולה מוציאה אלף מיני זמר. אמר רב נחמן בר יצחק, וסימניך,\u0004 לזכור מי אמר כל דבר: \u0003מתניתא גוזמא\u0004 \u0005[הברייתא\u0006 מדברת בלשון \u0005גוזמה],\u0006 שדרך הברייתא להפליג במספרים.","שנינו במשנה שהמנגנים \u0003עבדי כהנים היו\u0004 לדברי ר' מאיר, לדעת ר' יוסי היו ישראלים מיוחסים, ואילו לדברי ר' חנינא בן אנטיגנוס היו לויים. ומציעים: \u0003לימא בהא קמיפלגי\u0004 \u0005[\u0006האם \u0005נאמר\u0006 ש\u0005בזה חולקים הם],\u0006 \u0003דמאן דאמר\u0004 \u0005[שמי שאומר]\u0006 \u0003עבדים היו, קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003עיקר\u0004 מצות \u0003שירה\u0004 שנצטוו בה הלויים היא \u0003בפה, ו\u0004ניגון ב\u0003כלי לבסומי קלא הוא דעבידא\u0004 \u0005[לבשם,\u0006 להמתיק, \u0005את קול\u0006 השירה \u0005הוא שעשוי],\u0006 ואין מניעה שפסולים לעבודה יעשו זאת; \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003לוים היו, קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003עיקר שירה\u0004 שנצטוו בה הלויים היא גם \u0003בכלי,\u0004 ומי שאינו לוי אסור בכך?","ודוחים: \u0003ותסברא\u0004 \u0005[ו\u0006כי \u0005יכול אתה לסבור\u0006 כך\u0005]?!\u0006 אם כן \u0003ר' יוסי,\u0004 האומר שהיו אלה ישראלים מיוחסים, \u0003מאי קסבר\u0004 \u0005[מה הוא סבור]?\u0006 \u0003אי קסבר\u0004 \u0005[אם סבור הוא]\u0006 ש\u0003עיקר שירה בפה\u0004 — במנגנים \u0003עבדים סגיא\u0004 \u0005[מספיק],\u0006 ומדוע הצריך ישראלים מיוחסים? \u0003אי קסבר\u0004 \u0005[אם סבור הוא]:\u0006 \u0003עיקר שירה\u0004 גם \u0003בכלי\u0004 — מנגנים \u0003לוים בעינן\u0004 \u0005[צריכים אנו]!\u0006","אלא \u0003לעולם קסבר\u0004 \u0005[סבור]\u0006 כל אחד מהם כי \u0003עיקר שירה בפה,\u0004 ומעיקר הדין הכל כשרים לנגן בכלי, \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה האם \u0003מעלין מדוכן ליוחסין ולמעשרות קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 כלומר, האם מי שעומד על הדוכן ומנגן נחשב כבן משפחה מיוחסת להתחתן עמו, וכן האם הוא נחשב בוודאות כלוי לתת לו מעשר ראשון,","\u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003עבדים היו, קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003אין מעלין מדוכן לא ליוחסין ולא למעשרות,\u0004 ולכן יכלו המנגנים להיות עבדים; \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003לוים היו, קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003מעלין מדוכן בין ליוחסין בין למעשרות,\u0004 ולכן רק לויים הורשו לנגן; \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 \u0003ישראלים היו, קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003מעלין מדוכן ליוחסין,\u0004 ולכן אין עבדים מנגנים, \u0003ולא\u0004 מעלין \u0003למעשרות,\u0004 ולכן אפשר בישראל, ואין צריך לויים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003השיר מעכב את הקרבן,\u0004 שאם לא שרו הלויים בשעת הקרבת קרבן הציבור — לא יצאו ידי חובת הקרבן, אלו \u0003דברי ר' מאיר; וחכמים אומרים: אינו מעכב.\u0004","\u0003מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור בכתוב\u0005]\u0006 לדבריו של \u0003ר' מאיר?\u0004 ומסבירים: ש\u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"ואתנה את הלוים נתנים לאהרן ולבניו מתוך בני ישראל\u0004 לעבוד את עבודת בני ישראל באהל מועד \u0003ולכפר על בני ישראל\"\u0004 (במדבר ח, יט), הרי שעשה הכתוב את עבודת הלויים (בשיר) ככפרה הנעשית על ידי הכהנים בזריקת הדם על המזבח, \u0003מה כפרה\u0004 שנעשית בכהנים \u0003מעכבת, אף שירה\u0004 שנעשית בלויים בעת הקרבת הקרבן \u0003מעכבת.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה יענו על כך? ומשיבים: המקרא \u0003ההוא\u0004 בא \u0003לאידך\u0004 \u0005[ל\u0006דין \u0005אחר]\u0006 שאמר \u0003ר' אלעזר,\u0004 ש\u0003אמר ר' אלעזר: מה כפרה,\u0004 זריקת הדם, זמנה \u0003ביום,\u0004 ולא בלילה — \u0003אף שירה\u0004 זמנה \u0003ביום,\u0004 ולא בלילה.","\u0003אמר רב יהודה אמר שמואל: מנין,\u0004 מהו המקור \u0003לעיקר\u0004 מצות ה\u0003שירה\u0004 במקדש \u0003מן התורה? שנאמר\u0004 ביחס לבן שבט לוי הבא אל המקדש: \"ושרת בשם ה' אלהיו ככל אחיו הלויים העומדים שם\" (דברים יח, ז), ו\u0003איזהו שירות ש\u0004יש \u0003ב\u0004הזכרת \u0003שם\u0004 ה' — \u0003הוי אומר: זה שירה,\u0004 שמהללים בה את שם ה'.","ושואלים \u0003ואימא\u0004 \u0005[ואמור]\u0006 כי השירות בשם ה' הוא \u0003נשיאות כפים\u0004 (ברכת כהנים), שיש בה הזכרת שם ה'! ומשיבים: \u0003מדכתיב\u0004 \u0005[ממה שנאמר]:\u0006 \"בעת ההוא הבדיל ה' את שבט הלוי... \u0003לשרתו ולברך בשמו\"\u0004 (שם י, ח), \u0003מכלל\u0004 הדברים אתה למד ש\u0003ברכת כהנים\u0004 היא דבר נפרד, ו\u0003לאו\u0004 \u0005[לא]\u0006 \u0003שירות היא.\u0004","\u0003רב מתנה אמר,\u0004 עיקרה של השירה הוא \u0003מהכא\u0004 \u0005[מכאן]:\u0006 \u0003\"תחת אשר לא עבדת את ה' אלהיך בשמחה ובטוב לבב\"\u0004 (דברים כח, מז), ו\u0003איזו היא עבודה ש\u0004נעשית \u0003בשמחה ובטוב לבב? הוי אומר: זה שירה,\u0004 שאין שירה אלא מתוך שמחת הלב. ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שעבודה זו היא העמל ב\u0003דברי תורה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"פקודי ה' ישרים משמחי לב\"\u0004 (תהילים יט, ט)! ומשיבים: \u0003\"משמחי לב\" איקרי\u0004 \u0005[נקראים]\u0006 דברי התורה בפסוק זה, \u0003\"טוב\" לא איקרי\u0004 \u0005[אינם נקראים].\u0006","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שזו הבאת \u0003בכורים, דכתיב\u0004 \u0005[שנאמר]\u0006 בה: \u0003\"ושמחת בכל הטוב\"\u0004 (דברים כו, יא)! ומשיבים: \u0003\"טוב\" איקרי\u0004 \u0005[נקראים],\u0006 \u0003\"טוב לבב\" לא איקרי\u0004 \u0005[אינם נקראים].\u0006","ובעקבות דברי שמואל, \u0003אמר רב מתנה: מנין לביכורים שטעונין שירה\u0004 כשמביאים אותם למקדש? \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר בגזירה שווה\u0005]\u0006 \u0003\"טוב\" \"טוב\" מהכא\u0004 \u0005[מכאן],\u0006 שנאמר בשירה: \"בשמחה ובטוב לבב\", ובביכורים נאמר: \"ושמחת בכל הטוב\".","ושואלים: \u0003איני\u0004 \u0005[האמנם]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: מנין שאין אומרים שירה אלא על היין? שנאמר: \"ותאמר להם הגפן החדלתי את תירושי המשמח אלהים ואנשים\"\u0004 (שופטים ט, יג), \u0003אם אנשים משמח\u0004 היין, \u0003אלהים במה\u0004 הוא \u0003משמח? מכאן שאין אומרים שירה אלא על היין,\u0004 ושירת הלויים היא המשמחת אלהים. והלא היו מביאים ביכורים מן הפירות, ולא מן היין!","ומשיבים: \u0003משכחת לה כדתני\u0004 \u0005[מוצא אתה אותה,\u0006 שתיאמר שירה על ביכורים של יין, \u0005כמו ששנה]\u0006 \u0003ר' יוסי:\u0004 נאמר בענין הביכורים \"ולקחת מראשית כל פרי האדמה אשר תביא מארצך\" (דברים כו, ב), וממה שנאמר \"פרי האדמה\" אתה למד ש\u0003פרי אתה מביא, ואי\u0004 (ואין) \u0003אתה מביא משקין;\u0004 ואולם אם \u0003הביא ענבים ודרכן, מנין\u0004 שיצא ידי חובתו? \u0003תלמוד לומר: \"תביא\",\u0004 ומלה זו, שאינה נצרכת לגופה, באה לרבות הבאה נוספת, של יין.","ומביאים מקורות נוספים מן הכתובים לשירת הלויים במקדש. \u0003חזקיה אמר, מהכא\u0004 \u0005[מכאן]:\u0006 \u0003\"וכנניהו שר הלוים ישור במשא כי מבין הוא\"\u0004 (דברי הימים א טו, כב), \u0003אל תיקרי \"ישור\" אלא: \"ישיר\".\u0004","החכם \u0003בלווטי אמר\u0004 בשם \u0003ר' יוחנן, מהכא\u0004 \u0005[מכאן]:\u0006 נאמר לגבי הלויים \u0003\"לעבוד עבדת עבודה\"\u0004 (במדבר ד, מז)\u0003, איזהו עבודה שצריכה\u0004 להיעשות עם \u0003עבודה\u0004 אחרת? \u0003הוי אומר: זו שירה,\u0004 שנעשית בזמן עבודת ההקרבה.","\u0003ר' יצחק אמר, מהכא\u0004 \u0005[מכאן]:\u0006 \"הרנינו לאלקים עוזנו... \u0003שאו זמרה ותנו תף כנור נעים עם נבל\"\u0004 (תהילים פא, ג). \u0003רב נחמן בר יצחק אמר, מהכא\u0004 \u0005[מכאן]:\u0006 \u0003\"הם ישאו קולם ירנו בגאון ה' צהלו מים\"\u0004 (ישעיה כד, יד).","\u0003ותנא מייתי לה מהכא\u0004 \u0005[והתנא מביא אותה מכאן]:\u0006 \u0003\"ולבני קהת לא נתן כי עבודת הקדש עליהם בכתף ישאו\"\u0004 (במדבר ז, ט), \u0003ממשמע שנאמר \"בכתף\", איני יודע ש\"ישאו\"? מה תלמוד\u0004 (צריך) \u0003לומר \"ישאו\"? אין \"ישאו\" אלא לשון שירה, וכן הוא אומר: \"שאו זמרה ותנו תף\"\u0004 (תהילים פא, ג), \u0003ואומר: \"ישאו קולם ירנו\u0004 בגאון ה' צהלו מים\" (ישעיה כד, יד), ומכאן שהלויים שרים במקדש.","\u0003חנניא בן אחי ר' יהושע אמר, מהכא\u0004 \u0005[מכאן]\u0006 מקור לשירת הלויים, שנאמר: \u0003\"משה ידבר והאלהים יעננו בקול\"\u0004 (שמות יט, יט),"],["שציווהו ה' \u0003על עסקי קול,\u0004 כלומר, על שירה. \u0003רב אשי אמר, מהכא\u0004 \u0005[מכאן]\u0006 מקור לשירה על הקרבן: \u0003\"ויהי כאחד למחצצרים ולמשררים להשמיע קול אחד\u0004 להלל ולהודות לה' \" (דברי הימים ב ה, יג), ומכאן שיחד עם החצוצרות שציותה התורה לתקוע בהם על הקרבנות (במדבר י, י) יש גם שירה.","\u0003ר' יונתן אמר, מהכא\u0004 \u0005[מכאן]\u0006 מקור לשירת הלויים על הקרבן, שנאמר לכהנים ביחס ללויים: \"ואל המזבח לא יקרבו \u0003ולא ימותו גם הם גם אתם\"\u0004 (במדבר יח, ג), הרי שהוקשו זה לזה, \u0003מה אתם\u0004 הכהנים מצווים \u0003בעבודת מזבח,\u0004 בהקרבה — \u0003אף הם\u0004 הלויים מצווים \u0003בעבודת מזבח,\u0004 בשירה שעל הקרבן.","ומעירים, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 על פסוק זה: \u0003\"ולא ימותו גם הם גם אתם\", אתם\u0004 הכהנים, אם עבדתם \u0003ב\u0004עבודה \u0003שלהם\u0004 של הלויים, בשירה, \u0003והם\u0004 הלויים שעבדו \u0003ב\u0004עבודת ההקרבה \u0003שלכם\u0004 — \u0003במיתה\u0004 בידי שמים. אבל \u0003הם\u0004 הלויים שהחליפו \u0003ב\u0004עבודות \u0003שלהם,\u0004 כגון בין שירה לבין הגפת השערים במקדש — \u0003אינן ב\u0004חיוב \u0003מיתה אלא באזהרה,\u0004 במצות לא תעשה בלבד.","ומביאים מה ש\u0003אמר אביי\u0004 בענין זה, \u0003נקיטינן\u0004 \u0005[מוחזקים אנו]:\u0006 לוי שתפקידו \u0003משורר, ששיער\u0004 (שעבד כשוער) \u0003ב\u0004מקומו \u0003של חבירו\u0004 — נידון \u0003במיתה, שנאמר: \"והחנים לפני המשכן קדמה לפני אהל מועד\u0004 מזרחה משה ואהרן ובניו שומרים משמרת המקדש למשמרת בני ישראל \u0003והזר הקרב יומת\"\u0004 (במדבר ג, לח), ויש לשאול: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003זר? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003זר ממש,\u0004 ישראל — \u0003הכתיב חדא זימנא\u0004 \u0005[הרי\u0006 כבר \u0005נאמר\u0006 הדבר \u0005פעם אחת]\u0006 לפני כן (שם י)! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005אין]\u0006 הכוונה ללוי בעבודת חבירו, שהוא \u0003זר\u0004 לענין \u0003אותה עבודה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על אביי ממה ששנינו בברייתא: \u0003משורר ששיער ומשוער ששורר\u0004 — \u0003אינן במיתה אלא באזהרה!\u0004","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003מעשה בר' יהושע בר חנניה\u0004 הלוי \u0003שהלך לסייע בהגפת דלתות אצל ר' יוחנן בן גודגדא,\u0004 שהיה גם הוא לוי, \u0003אמר לו: בני, חזור לאחוריך, שאתה מן המשוררים ולא מן המשוערים;\u0004 ומעתה,","\u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא בזה הם חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם\u0006 זה, ר' יוחנן, \u0005סבור]:\u0006 בעונש \u0003מיתה היא, ו\u0004לכן \u0003גזרו בה רבנן\u0004 \u0005[חכמים],\u0006 שאסור לסייע לחבירו שמא יעשה גם כן בעצמו. \u0003ומר סבר\u0004 \u0005[וחכם\u0006 זה \u0005סבור]:\u0006 רק ב\u0003אזהרה היא, ולא גזרו בה\u0004 לסייע לאחר?","ודוחים: לא, \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 ב\u0003אזהרה היא, מר סבר\u0004 \u0005[חכם\u0006 זה \u0005סבור]:\u0006 \u0003מסייע\u0004 לחברו \u0003גזרו ביה רבנן\u0004 \u0005[גזרו בו חכמים],\u0006 \u0003ומר סבר\u0004 \u0005[וחכם\u0006 זה \u0005סבור]:\u0006 \u0003לא גזרו ביה רבנן\u0004 \u0005[לא גזרו בו חכמים].\u0006","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבי אבין: עולת נדבת ציבור\u0004 האם \u0003טעונה שירה או אינה טעונה שירה?\u0004 וצדדי השאלה: \"ותקעתם בחצוצרות על \u0003עלתיכם\"\u0004 (במדבר י, י) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 וכוונתה בכך לומר: \u0003אחת עולת חובה ואחת עולת נדבה? או דלמא\u0004 \u0005[שמא]\u0006 אין כאן ריבוי מיוחד של הכתוב, אלא: ותקעתם בחצוצרות על \u0003עולותיכם דכולהו\u0004 \u0005[של כל]\u0006 \u0003ישראל קאמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 והרי פרשה זאת עוסקת בקרבנות הציבור.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה שנאמר: \u0003\"ויאמר חזקיהו להעלות העולה על המזבח, ובעת החל העולה החל שיר ה' והחצוצרות על ידי כלי שיר דוד מלך ישראל\"\u0004 (דברי הימים ב כט, כז), ולשון \"ויאמר\" מורה כי הדבר לא היה פשוט מתחילה, ורק לאחר מכן הועלתה העולה בליווי השירה. ויש לברר: \u0003האי שירה מאי עבידתה\u0004 \u0005[שירה זו מה מעשיה,\u0006 מה עניינה\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיתה זו שירה של \u0003עולת חובה, למה לי אימלוכי\u0004 \u0005[להימלך]\u0006 האם להעלות עולה זו? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר ב\u0003עולת נדבה?\u0004 ומכאן שאומרים שירה על עולת נדבת ציבור.","\u0003אמר רב יוסף: לא, עולת ראש חודש הוה\u0004 \u0005[היתה],\u0006 שהיא עולת חובה, \u0003וקא מיבעיא להו\u0004 \u0005[ונשאלה להם\u0006 השאלה\u0005]\u0006 \u0003מי הוקבע\u0004 \u0005[האם נקבע]\u0006 \u0003ראש חדש בזמנו,\u0004 באותו יום, שהיה היום השלושים לחודש הקודם, \u0003דליקרב\u0004 \u0005[שיקרב\u0006 הקרבן\u0005],\u0006 \u0003או לא\u0004 נקבע באותו יום, וראש החודש למחרת. ונתברר כי בית דין קידשו את החודש, ולכן הקריבו את העולה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003ומי מצית אמרת הכי\u0004 \u0005[והאם יכול אתה לומר כך],\u0006 שהיה זה בראש החודש? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 בתחילת אותו ענין: \u0003\"ביום ששה עשר לחדש הראשון\" וגו'\u0004 (שם יז), ולאחר מכן נאמר הכתוב שאנו עוסקים בו: \u0003\"ויאמר חזקיהו להעלות העולה על המזבח\"\u0004 (שם, יז—כז)!","\u0003אלא אמר רמי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב ייבא: כבש הבא עם\u0004 מנחת \u0003העומר,\u0004 הקריבה ביום ששה עשר לחדש הראשון, \u0003קמיבעיא להו\u0004 \u0005[נסתפק להם]\u0006 האם יש להקריבו. והספק היה \u0003מי קבע\u0004 \u0005[האם נקבע]\u0006 \u0003ראש חדש בזמנו,\u0004 והיום כבר ששה עשר בניסן, \u0003דליקריב\u0004 \u0005[שיקרב]\u0006 הכבש עם מנחת העומר, \u0003או לא.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אויא:\u0004 כיצד ייתכן שהסתפקו בכך? \u0003וליחזי\u0004 \u0005[ושיראה]\u0006 \u0003פסח היכי עביד\u0004 \u0005[כיצד,\u0006 באיזה יום, \u0005עשה]?\u0006 \u0003מצה היכי אכיל\u0004 \u0005[איך,\u0006 באיזה יום \u0005אכל]?\u0006","\u0003אלא אמר רב אשי:\u0004 אף שמדובר היה בכבש הבא עם מנחת העומר, מה שנמלכו בחזקיהו לא היה בגלל ספק, אלא \u0003מידי דהוה אשליחא דציבורא דממליך\u0004 \u0005[כמו שהוא בשליח הציבור שנמלך]\u0006 בשולחיו לפני שהוא ניגש להתפלל. ומעירים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכך,\u0006 להסבר זה\u0005],\u0006 \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמדובר היה ב\u0003עולת חובה\u0004 רגילה, של קרבן התמיד, מה שנמלכו בחזקיהו היה \u0003מידי דהוה אשליחא דציבורא דממליך\u0004 \u0005[כמו שהוא הדין בשליח ציבור שנמלך].\u0006 על כל פנים לא נפתרה השאלה האם עולת נדבת ציבור טעונה שירה.","ואומרים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא, \u0003רבי יוסי אומר: מגלגלין זכות ליום זכאי וחובה ליום חייב.\u0004 כיצד?","\u0003אמרו: כשחרב הבית\u0004 בית המקדש \u0003בראשונה, אותו היום תשעה באב היה, ומוצאי שבת\u0004 (יום ראשון) \u0003היה, ומוצאי שביעית\u0004 (שנה ראשונה לאחר השמיטה) \u0003היתה, ומשמרתו\u0004 (משמר הכהנים) \u0003של יהויריב היתה, והיו כהנים ולוים עומדים על דוכנן ואומרים שירה, ומה שירה אמרו? \"וישב עליהם את אונם וברעתם יצמיתם\"\u0004 (תהלים צד, כג), \u0003ולא הספיקו לומר\u0004 את סוף המקרא \u0003\"יצמיתם ה' אלהינו\" עד שבאו גוים\u0004 לתוך המקדש \u0003וכבשום, וכן\u0004 אירע \u0003בשניה,\u0004 בחורבן הבית השני.","ויש לשאול: \u0003האי שירה מאי עבידתיה\u0004 \u0005[שירה זו מה מעשיה\u0006 כאן\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיתה זו שירה של \u0003עולת חובה, מי הואי\u0004 \u0005[האם היתה]\u0006 באותו זמן? והרי שנינו כי \u0003בשבעה עשר בתמוז,\u0004 שלושה שבועות קודם לכן, כבר \u0003בטל\u0004 קרבן חובה של \u0003התמיד,\u0004 מפני שלא היו להם כבשים מחמת המצור! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר ב\u0003עולת נדבה,\u0004 ומכאן ששרים גם על עולת נדבה!","ודוחים: \u0003ותסברא\u0004 \u0005[ו\u0006כי \u0005יכול אתה לסבור\u0006 כך\u0005]?\u0006 \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003עולת חובה\u0004 לקרבן התמיד \u0003דלא הואי\u0004 \u0005[שלא היתה]\u0006 להם, \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 \u0003עולת נדבה דהואי\u0004 \u0005[שהיתה]\u0006 בהמה להקרבה? ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה]:\u0006 \u0003בן בקר אקראי בעלמא\u0004 \u0005[במקרה בלבד]\u0006 \u0003הוא דאיתרמיא להו\u0004 \u0005[שנזדמן להם]\u0006 באותה שעה, אבל כבשים לקרבן התמיד (ראה במדבר כח, ג) לא היו. ומכל מקום, משמע מכאן שהלויים צריכים לומר שירה על עולת נדבת ציבור.","\u0003אמר רבא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב אשי: ותסברא\u0004 \u0005[ו\u0006כי \u0005יכול אתה לסבור\u0006 כן\u0005]\u0006 שהלויים קיימו באותה שעה את מצות השירה הקבועה לקרבנות היום? הלא \u0003שירה דיומיה\u0004 \u0005[השיר\u0006 הקבוע \u0005של אותו יום]\u0006 שחרב בו המקדש, היא \u0003\"לה' הארץ ומלואה\"\u0004 (תהילים כד, א), שהיה זה יום ראשון, ואילו מה ששרו אז \u0003\"וישב עליהם את אונם\"\u0004 — \u0003בשיר דארבעה\u0004 \u0005[של\u0006 יום \u0005רביעי]\u0006 \u0003בשבת הוא! אלא\u0004 צריך לומר ש\u0003אילייא בעלמא הוא דנפל להו בפומייהו\u0004 \u0005[קינה בלבד היא שנפלה להם בפיהם],\u0006 ולא היתה זו שירה שנאמרת על קרבן.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \"לויים \u0003עומדין על דוכנן\" קתני\u0004 \u0005[הוא שונה]\u0006 בברייתא, במקום בו אומרים שירה על הקרבן, ליד המזבח! ומשיבים: יש להסביר את הדבר \u0003כ\u0004דברי \u0003ריש לקיש,\u0004 ש\u0003אמר: אומר\u0004 (אומרים) הלויים שירה על הדוכן \u0003שלא על הקרבן\u0004 כשרוצים בכך. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אנו סבורים, יש לפתור את שאלת רבין ולומר כי \u0003בעולת נדבה נמי לימא\u0004 \u0005[גם כן יאמרו]\u0006 שירה, בתורת רשות! ומשיבים: אם יאמרו שירה על עולת נדבה בתורת רשות \u0003נפיק מינה חורבא\u0004 \u0005[תצא מכך תקלה],\u0006 שיבואו להקל בשירה של עולת חובה, שיסברו שאף היא אינה אלא רשות. ולא נפתרה איפוא שאלת ר' אבין.","ושואלים: \u0003מאי הוה עלה\u0004 \u0005[מה היה עליה]\u0006 על שאלה זו? כיצד נפתרה? ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב כהנא:\u0004 נאמר \"וביום שמחתכם ובמועדיכם ובראשי חדשיכם ותקעתם בחצוצרות \u0003על עלתיכם ועל זבחי שלמיכם\"\u0004 (במדבר י, י) — הוקשו העולות והשלמים שבפסוק זה, העוסק בשירה על הקרבן:","\u0003מה\u0004 \u0003עולה\u0004 היא \u0003קודש קדשים\u0004 — \u0003אף שלמים\u0004 האמורים במקרא זה הם \u0003קודש קדשים,\u0004 כלומר, כבשי שלמים שמביאים הציבור עם שתי הלחם בשבועות, שהם קדשי קדשים. \u0003ומה שלמים\u0004 אלה \u0003קבוע להם זמן\u0004 בחג שבועות, \u0003אף עולה\u0004 שטעונה שירה היא דוקא זו ש\u0003קבוע לה זמן,\u0004 אבל עולת נדבה, שלא קבוע לה זמן — אין עליה שירה."],["\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים: \u0003נסכים הבאים\u0004 וקרבים על המזבח \u0003בפני עצמן,\u0004 ולא עם הקרבן, האם \u0003טעונין שירה\u0004 של הלויים בשעת הניסוך \u0003או אין טעונין שירה?\u0004 וצדדי השאלה: \u0003כיון\u0004 ש\u0003אמר\u0004 ר' \u0003שמואל בר נחמני אמר ר' יונתן: מנין שאין אומרים שירה אלא על היין\u0004 — \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 שירה עליהם, \u0003או דלמא\u0004 \u0005[שמא]:\u0006 \u0003על אכילה ושתיה\u0004 של מזבח כלומר, זבח ונסכים — \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 שירה, על \u0003שתייה לחודה לא אמרינן\u0004 \u0005[אין אנו אומרים]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו, \u0003ר' יוסי אומר: מגלגלין זכות ליום זכאי וכו'\u0004 אמרו כשחרב הבית בראשונה אותו היום תשעה באב היה ומוצאי שבת היה (יום ראשון) וכו' והיו לויים עומדים על דוכנן ואומרים שירה.","ויש לשאול: \u0003האי\u0004 \u0005[אותה]\u0006 \u0003שירה\u0004 ששרו אז \u0003מאי עבידתיה\u0004 \u0005[מה מעשיה,\u0006 מה עניינה\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיתה זו שירה של \u0003עולת חובה,\u0004 קרבן התמיד — \u0003מי הוה\u0004 \u0005[האם היה\u0006 להם כבש להקרבה\u0005]?\u0006 הלא \u0003בשבעה עשר בתמוז בטל התמיד! ואלא\u0004 תאמר שהיתה זו \u0003עולת נדבה\u0004 — \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003רב מרי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב כהנא דלא צריכא\u0004 \u0005[ש\u0006עולת נדבה \u0005אינה צריכה]\u0006 שירה, כפי שהבאנו בעמוד הקודם! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 היתה זו שירה על \u0003נסכין\u0004 שבאו בפני עצמם, ומכאן שאומרים עליהם שירה.","\u0003אמר רבא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003רב אשי: ותסברא\u0004 \u0005[וכי יכול אתה לסבור כן],\u0006 שהיתה זו שירה על הקרבן? הלא \u0003שירה דיומיה\u0004 \u0005[של אותו יום]\u0006 שחרב המקדש, שהיה יום ראשון בשבוע, היא \u0003\"לה' הארץ ומלואה\"\u0004 (תהלים כד, א), ושיר זה היו צריכים לשיר על המזבח. ואילו הפסוק ששרו \u0003\"וישב עליהם את אונם\"\u0004 (שם צד, כג) — \u0003בשירה דארבעה בשבא\u0004 \u0005[של רביעי בשבת]\u0006 \u0003הוא! אלא אילייא בעלמא הוא דנפל להו בפומייהו\u0004 \u0005[קינה בלבד הוא שנפלה להם בפיהם],\u0006 ולא היתה זו שירה על קרבן, ואין להוכיח מכאן.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"עומדים על דוכנן\" קתני\u0004 \u0005[\u0006הוא \u0005שונה]\u0006 בברייתא זו, כלומר, המקום בו היו אומרים שירה על הקרבן! ומשיבים: יש להסביר זאת \u0003כ\u0004דברי \u0003ריש לקיש,\u0004 ש\u0003אומר ריש לקיש: אומר\u0004 הלוי \u0003שירה\u0004 בתורת רשות, \u0003שלא על הקרבן.\u0004 ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 כיון שיכול להגיד שירה שלא על הקרבן, \u0003בנסכים\u0004 הבאים בפני עצמם \u0003נמי לימא\u0004 \u0005[גם כן שיאמר]\u0006 שירה, ונפתור כך את שאלת הגמרא! ומשיבים: אם יעשו כן \u0003נפיק מיניה חורבא\u0004 \u0005[תצא מזה תקלה],\u0006 שיבואו להקל בשירה של נסכים הבאים עם הקרבן, שיסברו שגם היא אינה אלא רשות.","ודנים \u0003גופא\u0004 \u0005[לגופו]\u0006 של מה שהזכרנו, \u0003ר' יוסי אומר: מגלגלין זכות ליום זכאי\u0004 וחובה ליום חייב. כשחרב הבית בראשונה אותו היום תשעה באב היה, ומוצאי שבת היה, ומוצאי שביעית היתה (השנה הראשונה לאחר השמיטה) \u0003וכו'.\u0004","ושואלים: שנחרב הבית \u0003בראשונה, במוצאי שביעית מי משכחת לה\u0004 \u0005[האם מוצא אתה אותה]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"בעשרים וחמש שנה לגלותנו, בראש השנה בעשור לחדש, בארבע עשרה שנה אחר אשר הוכתה העיר\u0004 וכו' היתה עלי יד ה' \"(יחזקאל מ, א). ויש לברר: \u0003איזו היא שנה שראש השנה\u0004 שלה הוא \u0003בעשור לחדש? הוי אומר: זה\u0004 שנת ה\u0003יובל,\u0004 המתחילה ביום הכיפורים.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 כי \u0003בחד\u0004 \u0005[בראשון]\u0006 \u0003בשבוע,\u0004 בשנה הראשונה למחזור שנות השמיטה, \u0003חרוב\u0004 \u0005[נחרב]\u0006 הבית — לא ייתכן ששנת היובל היתה השנה הארבע עשרה לחורבן, כפי שהנביא מתאר בפסוק זה, שהרי אם נמנה \u0003מחד\u0004 \u0005[מראשון]\u0006 \u0003בשבוע לחד\u0004 \u0005[לראשון]\u0006 \u0003בשבוע\u0004 שאחריו — \u0003תמני\u0004 \u0005[שמונה]\u0006 שנים הם (כולל שנת החורבן עצמה), ועד \u0003לחד בשבוע אחרינא\u0004 \u0005[לראשון בשבוע הבא],\u0006 כלומר, לשנת היובל, הבאה לאחר שנת שמיטה (השנה הארבעים ותשע) — בסך הכל \u0003חמש עשרה\u0004 שנים \u0003הוויין\u0004 \u0005[הן],\u0006 ולא ארבע עשרה!","\u0003אמר רבינא,\u0004 כוונת הנביא היא: \u0003בארבע עשרה שנה אחר שנה שהוכתה העיר,\u0004 כלומר, שנת החורבן עצמה (שהיתה השנה השלושים ושש למנין שנות אותו יובל) אינה נמנית במנין ארבע עשרה השנים.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 ששנת היובל היתה ארבע עשרה שנה לאחר שנת החורבן, מה שנאמר בפסוק זה \u0003\"בעשרים וחמש שנה\u0004 לגלותנו\" אינו מדוייק, שהרי \u0003עשרים ושש הויין\u0004 \u0005[הן]! שהרי\u0006 \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003גלו ב\u0004שנת \u0003שבע\u0004 לנבוכדנצר, \u0003גלו\u0004 \u0003בשמונה\u0004 לשלטונו,","\u0003גלו בשמונה עשרה,\u0004 \u0003גלו בתשע עשרה.\u0004","ומעתה, כשאתה מחשב \u0003משב\u0004 \u0005[משבע]\u0006 שנים לנבוכדנצר, שאז החלה הגלות, \u0003ועד תמני סרי\u0004 \u0005[\u0006שנת \u0005שמונה עשרה],\u0006 שאז חרב הבית — \u0003חד סרי\u0004 \u0005[אחת עשרה\u0006 שנה\u0005]\u0006 הן, בלא שנת החורבן עצמה, \u0003ו\u0004עוד \u0003חמש עשרה\u0004 שנה, משנת החורבן עצמה עד שנת היובל — \u0003עשרים ושית הויא\u0004 \u0005[עשרים ושש\u0006 שנים \u0005הן],\u0006 ולא עשרים וחמש!","ומשיבים, \u0003אמר לך\u0004 \u0005[יכול היה לומר לך]\u0006 \u0003רבינא: ולדידך מי ניחא\u0004 \u0005[ולשיטתך,\u0006 ששנת החורבן היתה מכלל ארבע עשרה השנים שעד היובל, \u0005האם נוח הדבר]?\u0006 \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003גלו נמי\u0004 \u0005[גם כן]\u0006 \u0003בתשע עשרה\u0004 שנה, ואז היה החורבן, כפי פשט הכתובים, ואם כן, כשאנו מונים \u0003משב ועד תשסרי\u0004 \u0005[משבע ועד תשע עשרה]\u0006 — \u0003תרתי סרי\u0004 \u0005[שתים עשרה\u0006 שנה\u0005]\u0006 הן, \u0003ו\u0004עוד \u0003ארבע סרי\u0004 \u0005[עשרה]\u0006 שנה, אם כן \u0003עשרים ושית הויין\u0004 \u0005[עשרים ושש הן]!\u0006 \u0003אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר]\u0006 כדי לפרש את הדבר לשיטתך? שחשבון \"עשרים וחמש שנה לגלותנו\" הוא \u0003לבר משתא\u0004 \u0005[חוץ מן השנה]\u0006 ש\u0003גלו בה,\u0004 כלומר, השנה השביעית, ויש אחת עשרה שנה עד החורבן שבשנת תשע עשרה (בלא שנת החורבן עצמה), \u0003לדידי נמי לבר משתא\u0004 \u0005[לשיטתי,\u0006 שמונים ארבע עשרה שנה לאחר שנת החורבן, \u0005גם כן\u0006 יש לפרש שחשבון עשרים וחמש השנים הוא \u0005חוץ מהשנה]\u0006 ש\u0003גלו בה,\u0004 והוא כולל אחת עשרה שנה משבע עד שמונה עשרה (שנת החורבן) ועוד ארבע עשרה שנה, הרי עשרים וחמש.","ומתקשים: \u0003מכל מקום\u0004 שנת \u0003תשסרי\u0004 \u0005[תשע עשרה]\u0006 \u0003ל\u0004דעת \u0003רבינא קשיא\u0004 \u0005[קשה],\u0006 שהרי כפי פשט הכתובים, באותה שנה אירע החורבן, וכך לא תיתכן שנת היובל בשנת העשרים וחמש לגלותנו, כלומר בשנה השביעית. שהרי גם אם אין מונים את שנת הגלות עצמה, וגם לא את שנת החורבן — יש אחת עשרה שנה בין השביעית לתשע עשרה, ועוד חמש עשרה שנה (כולל שנת החורבן עצמה) — הרי עשרים ושש!","ומשיבים: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 ש\u0003שלש גליות\u0004 שונות \u0003הוי\u0004 \u0005[היו]?\u0006 לא כך הכוונה, אלא שתי גלויות היו: \u0003גלו בשבע לכיבוש\u0004 כלומר, לנצחון נבוכדנצר על \u0003יהויקים, שהיא\u0004 שנת \u0003שמונה לנבוכד נצר,\u0004 וכן \u0003גלו\u0004 לאחר אחת עשרה שנה, \u0003בשמונה עשרה לכיבוש יהויקים, שהיא תשע עשרה לנבוכד נצר.\u0004 ולאחר החורבן (שהוא בשנת שמונה עשרה) ועד ליובל — עברו עוד ארבע עשרה שנים, ובסך הכל עשרים וחמש שנים.","\u0003דאמר מר\u0004 \u0005[שאמר החכם]:\u0006 \u0003שנה ראשונה\u0004 של מלכותו \u0003כיבש\u0004 נבוכדנצר את העיר \u0003נינוה,\u0004 בירת אשור,"],["שנה \u0003שניה עלה וכיבש יהויקים.\u0004","וממשיכים לדון בברייתא ששנינו בה: כשחרב הבית בראשונה אותו היום תשעה באב היה, ומוצאי שבת היה, ומוצאי שביעית היה, \u0003וכן\u0004 היה \u0003ב\u0004פעם ה\u0003שניה,\u0004 כשחרב הבית השני.","ושואלים: \u0003ו\u0004פעם \u0003שניה במוצאי שביעית מי משכחת לה\u0004 \u0005[האם מוצא אתה אותה]?\u0006 \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003בית שני כמה קם\u0004 \u0005[עמד]\u0006 — \u0003ארבע מאה\u0004 \u0005[מאות]\u0006 \u0003ועשרים\u0004 שנה; וכשאתה מתחיל למנות את שנות היובל מתחילת בנין הבית, \u0003ארבע מאה\u0004 \u0005[מאות]\u0006 שנה הן \u0003תמניא יובלי\u0004 \u0005[שמונה יובלות]\u0006 של חמישים שנה, \u0003ארבסרי\u0004 \u0005[ארבע עשרה]\u0006 שנים נוספות הן עוד \u0003תרי שבוע\u0004 \u0005[שתי שמיטות],\u0006 \u0003פשו להו שית\u0004 \u0005[נותרו להם שש\u0006 שנים\u0005]\u0006 למנין ארבע מאות ועשרים, \u0003הוה ליה בשיתא בשבוע\u0004 \u0005[נמצא\u0006 שמנין ארבע מאות ועשרים נשלם \u0005בשנה השישית לשמיטה],\u0006 וכשהבית חרב בשנה שלאחר מכן, היה זה בשביעית, ולא במוצאי שביעית!","ודוחים: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו כשיטת מי היא]?\u0006 שיטת \u0003רבי יהודה היא,\u0004 ש\u0003אמר: שנת חמשים עולה לכאן ולכאן\u0004 ליובל זה וליובל זה, כלומר, אינה נמנית לעצמה, אלא היא השנה הראשונה ליובל הבא (ולשמיטה הבאה), וכך יש בכל יובל ארבעים ותשע שנים. ומעתה, כשאתה רוצה לחשב באיזו שנה משנות שמיטה היה החורבן, לאחר שאתה מונה שמונה מחזורים של יובל בן ארבעים ותשע שנה (שבע שמיטות מלאות), \u0003אייתי תמניא מתמניא יובלי\u0004 \u0005[הבא\u0006 עוד \u0005שמונה\u0006 שנים \u0005משמונה יובלות]\u0006 שלא מנית לשיטה זו, כדי להשלים למנין ארבע מאות שנה, \u0003והני שית\u0004 \u0005[ו\u0006הוסף עליהם \u0005אותן שש]\u0006 שנים הבודדות שנותרו ממנין השנים של עשרים השנה הנוספות — \u0003הוי ארביסר\u0004 \u0005[הרי זה ארבע עשרה]\u0006 שנים, שתי שמיטות שלמות. \u0003אישתכח\u0004 \u0005[נמצא]\u0006 ש\u0003במוצאי שביעית,\u0004 בשנה הראשונה למנין השמיטה, \u0003חרוב\u0004 \u0005[חרב]\u0006 הבית.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' יהודה\u0004 אתה מפרש את הדבר, אם כן בחורבן הבית \u0003ב\u0004פעם ה\u0003ראשונה לא משכחת לה\u0004 \u0005[אין אתה מוצא אותה]\u0006 שיהא זה בשנה הראשונה לשמיטה, כפי ששנינו בברייתא זו שאנו דנים בה! \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003שבעה עשר יובלות מנו ישראל משנכנסו לארץ ועד שיצאו\u0004 ממנה בחורבן הבית הראשון, לאחר שמונה מאות וחמישים שנה, \u0003ואי\u0004 (ואין) \u0003אתה יכול לומר\u0004 שמיד \u0003משעה שנכנסו\u0004 לארץ \u0003מנו, שאם אתה אומר כן\u0004 — \u0003נמצא בית חרב בתחילת יובל, ו\u0004באופן זה \u0003אי\u0004 (אין) \u0003אתה מוצא\u0004 מה שאמר הנביא ששנת היובל שהוא עומד בה היא \u0003\"בארבע עשרה שנה אחר אשר הכתה העיר\"\u0004 (יחזקאל מ, א).","\u0003אלא צא\u0004 (הוצא) \u0003מהם שבע\u0004 שנים \u0003שכיבשו\u0004 את הארץ \u0003ושבע\u0004 שנים \u0003שחילקו\u0004 אותה ביניהם, שעדיין לא החל אז מנין שנות היובל, \u0003ו\u0004אז \u0003אתה מוצא\u0004 ששנת היובל היתה \u0003\"בארבע עשרה שנה אחר אשר הכתה העיר\".\u0004","\u0003ואי\u0004 \u0005[ואם]\u0006 לשיטת \u0003רבי יהודה,\u0004 ששנת החמישים עולה לתחילת היובל הבא, כשאתה רוצה לחשב באיזו שנה משנות השמיטה היה החורבן, ואתה מונה שבעה עשר מחזורים של יובל בן ארבעים ותשע שנים, \u0003אייתי שבסרי משבסרי יובלי\u0004 \u0005[הבא\u0006 עוד \u0005שבע עשרה\u0006 שנים \u0005משבע עשרה יובלות],\u0006 כדי להשלים למנין שמונה מאות וחמשים שנה, \u0003שדי אהני\u0004 \u0005[הטל,\u0006 הוסף \u0005על אלה],\u0006 \u0003הוה ליה בתלתא בשבוע\u0004 \u0005[\u0006נמצא ש\u0005היה זה בשנה השלישית של השמיטה],\u0006 שהרי בשבע עשרה שנה יש שתי שמיטות מלאות ועוד שלוש שנים!","ומשיבים: \u0003הנך שני דאגלינהו\u0004 \u0005[אותן השנים שהגלה אותם]\u0006 \u0003סנחריב\u0004 את עשרת השבטים \u0003עד דאתא\u0004 \u0005[שבא]\u0006 \u0003ירמיה אהדרינהו\u0004 \u0005[והחזיר אותם]\u0006 — \u0003לא קחשיב להו\u0004 \u0005[אינו מונה אותם]\u0006 במנין שנות היובל, שהרי אין היובל נוהג אלא כשכל שבטי ישראל במקומם. אלא משעה שהחזירם החל מנין חדש, ולאחר שלושים ושש שנים, במוצאי שביעית, חרב הבית.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003לעולם\u0004 תפרש שברייתא זו שאנו דנים בה כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא, הסבורים כי שנת היובל נמנית לעצמה, \u0003וכי קתני\u0004 \u0005[וכאשר הוא שונה]\u0006 \u0003\"וכן בשניה\"\u0004 — אין מדובר על כך שהיה הדבר במוצאי שביעית (שהרי כאמור, היה זה בשנה השביעית), אלא \u0003אשארא\u0004 \u0005[על שאר\u0006 הפרטים\u0005]\u0006 מדובר, שהיה זה בתשעה באב ובמוצאי שבת (יום ראשון).","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר],\u0006 שלא כל הפרטים המתוארים בחורבן בית ראשון, היו גם בחורבן הבית השני, \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך],\u0006 מה ששנינו שהיתה באותה שעה \u0003משמרתו של יהויריב\u0004 במקדש, בחורבן הבית \u0003בשניה מי הואי\u0004 \u0005[האם היתה]?\u0006","\u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 רק \u0003ארבע משמרות עלו מן הגולה\u0004 לאחר חורבן הבית הראשון: \u0003ידעיה וחרים פשחור ואימר. עמדו נביאים שביניהם וחלקום לעשרים וארבע משמרות,\u0004 כמו בזמן הבית הראשון, וכל משמר נתחלק לששה, וכתבו את שמות כל עשרים וארבעה המשמרות על פתקים, \u0003בללום\u0004 \u0003ונתנום בקלפי, בא ידעיה ונטל חלקו\u0004 \u0003וחלק חביריו\u0004 למשמר, וביחד \u0003שש\u0004 משמרות,"],["\u0003בא\u0004 כהן ממשמר \u0003חרים ונטל חלקו וחלק חביריו שש, וכן\u0004 עשה כהן ממשמר \u0003פשחור, וכן\u0004 עשה כהן ממשמר \u0003אימר.\u0004 ו\u0003התקינו נביאים שביניהם שאפילו\u0004 משמר \u0003יהויריב,\u0004 שהוא \u0003ראש\u0004 (ראשון) בסדר ה\u0003משמרות\u0004 שהיו בזמן הבית הראשון, \u0003עולה\u0004 לארץ — \u0003לא ידחה\u0004 משמר \u0003ידעיה ממקומו, אלא ידעיה\u0004 ישאר \u0003עיקר, ו\u0004משמר \u0003יהויריב טפל לו,\u0004 משמש עמו, אבל אין המשמר קרוי על שמו. ואם כן לא ייתכן שחרב הבית השני בזמן משמרת יהויריב! \u0003אלא\u0004 מכאן אתה למד שההשוואה של חורבן בית שני לראשון נאמרה \u0003אשארא\u0004 \u0005[על שאר\u0006 הדברים\u0005]\u0006 שהוזכרו בברייתא, שהיה זה בתשעה באב ובמוצאי שבת, אבל לא על מה שנאמר שהיה זה במוצאי שביעית.","\u0003רב אשי אמר:\u0004 חורבן הבית השני אירע אף הוא במוצאי שביעית. ואף שלפי מנין ארבע מאות ועשרים שנה עמד הבית עד השנה השישית לשמיטה, \u0003הנך שית שני\u0004 \u0005[אותן שש שנים]\u0006 משעה שנבנה הבית \u0003עד דסליק\u0004 \u0005[שעלה]\u0006 \u0003עזרא ומקדיש\u0004 \u0005[וקידש\u0006 את הארץ למנין שמיטות ויובלות\u0005]\u0006 \u0003לא קא חשיב להו\u0004 \u0005[לא מחשיב אותן]\u0006 ר' יוסי בברייתא במנין השמיטות. ומניין שעזרא עלה לאחר שש שנים?","\u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"באדין בטלת עבידת בית אלהנא די בירושלם\u0004 והות בטלא עד שנת תרתין למלכות דריוש מלך פרס\" (עזרא ד, כד) \u0005[באותה עת בטלה עבודת בית אלהינו שבירושלים והיתה בטלה עד שנת שנים למלכות דריוש מלך פרס\u0006\u0005],\u0006 ונמצא שהשנה השניה לדריוש היא השנה הראשונה לבנין הבית. \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ושיציא ביתא דנא עד יום תלתא לירח אדר דהיא שנת שית למלכות דריוש מלכא\"\u0004 \u0005[ונגמר הבית הזה עד היום השלישי לחודש אדר, שהיא השנה השישית למלכות דריוש המלך],\u0006 כלומר, בשנה החמישית לבנין הבית.","\u0003ותנא\u0004 \u0005[ושנה\u0006 החכם בברייתא\u0005]:\u0006 \u0003באותו זמן לשנה הבאה עלה עזרא וגלותו עמו, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויבא ירושלם בחדש החמישי היא השנה השביעית למלך\"\u0004 (עזרא ז, ח), לאחר שש שנים של בנין הבית, והחלו למנות שמיטות רק בתשרי שאחריו. ונמצא שמנו שמיטות רק בארבע מאות וארבע עשרה השנים האחרונות שעמד בית שני, ונמצאת שנתו האחרונה שנת שמיטה, וחורבנו במוצאי שביעית.","\u0003גופא\u0004 \u0005[\u0006דנים \u0005לגופה]\u0006 של אותה ברייתא שהזכרנו: \u0003שבעה עשר יובלות מנו ישראל משנכנסו לארץ ועד שיצאו, ואי אתה יכול לומר משנכנסו\u0004 מיד \u0003מנו, שאם אתה אומר משנכנסו מנו, נמצא בית חרב בתחלת יובל\u0004, כלומר, בשנה שהיובל חל בה, \u0003ואי\u0004 (ואין) \u0003אתה מוצא\u0004 מה שאמר הנביא שהוא עומד בשנת היובל \u0003\"בארבע עשרה שנה אחר אשר הכתה העיר\"\u0004 (יחזקאל מ, א), אלא הוצא מהם שבע שכיבשו ושבע שחילקו, ואתה מוצא אותן ארבע עשרה שנים קודם שהתחילו למנות.","ושואלים: \u0003שבע\u0004 שנים \u0003שכיבשו מנלן\u0004 \u0005[מנין לנו]?\u0006 ומשיבים: \u0003דקאמר\u0004 \u0005[שאמר]\u0006 \u0003כלב\u0004 בן יפונה ליהושע: \u0003\"בן ארבעים שנה\u0004 אנכי \u0003בשלח אתי משה עבד ה' מקדש ברנע לרגל את הארץ\u0004 וגו' \u0003ועתה\u0004 הנה \u0003אנכי היום בן חמש ושמונים\u0004 שנה\" (יהושע יד, ז—י),","\u0003ואמר מר\u0004 \u0005[החכם\u0006 בברייתא\u0005]:\u0006 ב\u0003שנה ראשונה\u0004 ליציאת מצרים \u0003עשה משה משכן,\u0004 ובשנה \u0003שניה הוקם המשכן ושלח מרגלים,\u0004 וכך \u0003כי עבור\u0004 \u0005[כאשר עברו]\u0006 את ה\u0003ירדן\u0004 בכניסתם לארץ, שלושים ושמונה שנה לאחר שחזרו המרגלים, \u0003כלב בר כמה הוי\u0004 \u0005[בן כמה היה]\u0006 — \u0003בר תמנן נכי תרתין\u0004 \u0005[בן שמונים פחות שתים],\u0006 ואילו \u0003כי קא מפליג נחלות קאמר\u0004 \u0005[כאשר מחלק\u0006 יהושע \u0005את הנחלות\u0006 לאחר הכיבוש \u0005אומר]\u0006 לו כלב: \u0003\"בן חמש ושמונים שנה אנכי\"\u0004 (שם), \u0003אישתכח\u0004 \u0005[נמצא]\u0006 ש\u0003שבע\u0004 שנים \u0003כיבשו.\u0004","ושואלים: \u0003ושבע שחילקו מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003מ\u0004כיון ש\u0003שבע\u0004 שנים \u0003כיבשו\u0004 יש לומר כי \u0003שבע\u0004 שנים \u0003חילקו. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 צריך אתה לומר כן \u0003מדלא משכחת להו\u0004 \u0005[ממה שאין אתה מוצא אותם]\u0006 את \u0003\"ארבע עשרה שנה אחר אשר הכתה העיר\"\u0004 (יחזקאל מ, א) בשנת היובל (ראה לעיל יב,א), אלא אם כן אתה מפרש ששבע שנים נוספות חילקו את הארץ, ורק לאחר ארבע עשרה שנה החלו למנות יובלות.","\u0003אין פוחתין מששה טלאים המבוקרין,\u0004 הבדוקים ממום, \u0003בלשכת הטלאים\u0004 שבמקדש, \u0003כדי\u0004 (שיש בהם די) \u0003ל\u0004קרבנות הציבור של \u0003שבת ול\u0004שני \u0003ימים טובים של ראש השנה\u0004 הסמוכים לו, \u0003ומוסיפין\u0004 טלאים בדוקים בלשכה \u0003עד עולם\u0004 (ללא הגבלה). \u0003אין פוחתין\u0004 במקדש \u0003משתי חצוצרות\u0004 ו\u0003מתשעה כנורות\u0004 לצורך שירת הלויים, \u0003ומוסיפין\u0004 עליהם אם ירצו \u0003עד עולם, והצלצל\u0004 (מצילתיים) היה \u0003לבד,\u0004 ואין מוסיפים עליו.","שנינו כי ששה טלאים הם לצורך קרבנות הציבור של שבת ושני ימים טובים של ראש השנה. ותוהים: והרי הטלאים הנצרכים ל\u0003תמידין ומוספין\u0004 של שבת וראש השנה \u0003טובא הוו\u0004 \u0005[רבים הם],\u0006 וכיצד די בששה!","ומשיבים: \u0003תנא בעלמא קאי\u0004 \u0005[התנא\u0006 \u0005באופן כללי הוא מדבר],\u0006 בכל השנה כולה, \u0003ואתמידין לחודיה קאי\u0004 \u0005[ועל\u0006 המנין הנצרך ל\u0005תמידים\u0006 של כל שלושה ימים \u0005בלבד הוא עומד],\u0006 \u0003ומאי\u0004 \u0005[ומה]\u0006 ששנה \u0003\"כדי לשבת ולימים טובים\u0004 של ראש השנה\" — \u0003סימנא בעלמא\u0004 \u0005[סימן בלבד\u0006 הוא\u0005]\u0006 לזכור שמדובר במספר טלאים הנצרכים לשלושה ימים, ולא פחות. \u0003והכי קאמר\u0004 \u0005[וכך הוא אומר]\u0006 התנא: \u0003אין פוחתין מששה טלאים\u0004"],["\u0003המבוקרים בלשכת הטלאים,\u0004 כל אחד מהם מבוקר \u0003ארבעה ימים קודם שחיטה,\u0004 וכשנוטלים שני טלאים בכל יום, ומביאים שניים חדשים ומבקרים אותם — יש תמיד ששה טלאים בלשכה, כמספר התמידים של שלושה ימים. \u0003ומני\u0004 \u0005[ו\u0006כשיטת \u0005מי היא\u0006 המשנה\u0005]?\u0006 כשיטת \u0003בן בג בג היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003בן בג בג אומר: מנין לתמיד שטעון ביקור\u0004 ממומים \u0003ארבעה ימים קודם שחיטה?\u0004 \u0003תלמוד לומר:\u0004 \"את קרבני לחמי לאשי ריח ניחוחי \u0003תשמרו להקריב לי במועדו\"\u0004 (במדבר כח, ב), \u0003ולהלן,\u0004 בקרבן הפסח, \u0003הוא אומר:\u0004 \"בעשור לחדש הזה ויקחו להם איש שה לבית אבות... \u0003והיה לכם למשמרת עד ארבעה עשר יום לחדש הראשון\"\u0004 (שמות יב, ג—ו), \u0003מה להלן\u0004 הפסח \u0003טעון ביקור ארבעה ימים קודם שחיטה,\u0004 מעשור לחודש עד ארבעה עשר בחודש, יום שחיטתו, \u0003אף כאן\u0004 התמיד \u0003טעון ביקור ארבעה ימים קודם שחיטה.\u0004","","ואומרים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן],\u0006 שאין מדובר במשנה בקרבנות של שבת וראש השנה, אלא בסימן בלבד, \u0003דקתני\u0004 \u0005[ש\u0006הרי \u0005הוא שונה]:\u0006 \u0003\"כדי\u0004 (די הצורך) \u0003לשבת\u0004 ולימים טובים של ראש השנה\", \u0003ולא קתני\u0004 \u0005[ואינו שונה]\u0006 \u0003\"לשבת\u0004 ולימים טובים של ראש השנה\", שמשמעו — לצורך אותם ימים, ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","נאמר במשנה שאין פוחתים \u0003משתי חצוצרות ומוסיפין\u0004 עד עולם. ושואלים: \u0003ועד כמה\u0004 חצוצרות מוסיפים? \u0003אמר רב הונא, ואמרי לה\u0004 \u0005[ויש ד'דאומרים]\u0006 ש\u0003אמר רב זבדי אמר רב הונא: עד מאה ועשרים, שנאמר: \"ועמהם כהנים למאה ועשרים מחצרים בחצוצרות\"\u0004 (דברי הימים ב ה, יב).","שנינו במשנה שאין פוחתים \u0003מתשעה כנורות\u0004 ומוסיפים עד עולם, \u0003וצלצל\u0004 (מצלתיים) \u0003לבד\u0004 (יחידי). ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שאין מנגנים אלא בצלצל אחד? \u0003אמר רב אסי, דאמר קרא\u0004 \u0005[שאמר הכתוב]:\u0006 \u0003\"ואסף במצלתים להשמיע\"\u0004 (דברי הימים א טז, ה), כלומר, לוי אחד. ושואלים: והלא \u0003מצלתים תרי הוו\u0004 \u0005[שנים הם],\u0006 ומדוע נאמר במשנה \"צלצל\"? ומשיבים: \u0003כיון דחדא עבידתא עבדי\u0004 \u0005[שמעשה אחד הם עושים]\u0006 כשמכים זה בזה, \u0003וחד גברא עביד בהו\u0004 \u0005[ואדם אחד עושה,\u0006 מנגן \u0005בהם],\u0006 \u0003קרי להו חד\u0004 \u0005[קורא להם\u0006 כלי \u0005אחד].\u0006","\u0003אין פוחתין משנים עשר לוים\u0004 ש\u0003עומדין על הדוכן\u0004 הסמוך למזבח ושרים, \u0003ומוסיפין עד עולם\u0004 (כמה שירצו). \u0003אין\u0004 הלוי \u0003הקטן נכנס לעזרה\u0004 שבמקדש \u0003לעבודה, אלא בשעה שהלוים אומרים בשיר,\u0004 כדי ללוותם בשירתם. \u0003ולא היו\u0004 הקטנים אומרים (מנגנים) \u0003בנבל ובכנור, אלא בפה, כדי ליתן תבל\u0004 (תבלין, טעם טוב) \u0003בנעימה\u0004 (במנגינה) על ידי קולותיהם הדקים והצלולים. ר' אליעזר בן יעקב אומר: \u0003אין\u0004 הקטנים \u0003עולין למנין\u0004 של שנים עשר העומדים על הדוכן, \u0003ואין עולין\u0004 \u0003לדוכן, אלא בארץ היו עומדין וראשיהן\u0004 נראים \u0003בין רגלי הלוים, וצערי הלוים היו נקראין.\u0004","","שנינו במשנה כי אין פוחתין משנים עשר לויים עומדים על הדוכן לשיר. ושואלים: \u0003הני\u0004 \u0005[\u0006שנים עשר \u0005אלה]\u0006 \u0003כנגד מי\u0004 הם? \u0003אמר רב פפא:\u0004 מספר השרים הוא \u0003כנגד\u0004 מספר המנגנים שאין פוחתים מהם, שהם \u0003תשעה כנורות ושני נבלים וצלצל אחד,\u0004 כפי שנאמר במשניות הקודמות. וכן מצאנו שם שמספר השרים היה שנים עשר, \u0003שנאמר:\u0004 \"מלומדי שיר לה'... \u0003הוא ובניו ואחיו שנים עשר\"\u0004 (דברי הימים א כה, ז—ט).","שנינו במשנה: \u0003אין הקטן נכנס לעזרה לעבודה אלא בשעה שהלוים\u0004 אומרים בשיר. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר ר' יוחנן, דאמר קרא\u0004 \u0005[שאמר הכתוב]:\u0006 \u0003\"ויעמד ישוע בניו ואחיו קדמיאל ובניו בני יהודה כאחד לנצח על\u0004 עשה \u0003המלאכה ה' עבודת בית ה'\u0004 בבית האלהים\" (ראה עזרא ג, ט), כלומר, האבות עם הבנים, גדולים וקטנים כאחד, היו מלווים את העבודה בשיר.","שנינו במשנה שאותם לויים קטנים \u0003לא היו אומרים לא בנבל ולא בכנור, אלא בפה\u0004 כדי ליתן תבל בנעימה. ומעירים: \u0003למימרא\u0004 \u0005[\u0006יש \u0005לומר,\u0006 ללמוד\u0005]\u0006 מלשון המשנה ש\u0003נבל\u0004 הוא כלי \u0003לחוד, וכנור\u0004 כלי \u0003לחוד\u0004 הוא. ושואלים: \u0003לימא מתניתין\u0004 \u0005[\u0006האם \u0005לומר\u0006 ש\u0005משנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' יהודה\u0004 היא? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר: כנור של מקדש של שבעת נימין\u0004 (מיתרים) \u0003היה, שנאמר: \"שבע שמחות\u0004 את \u0003פניך\u0004 נעימות בימינך נצח\" (תהלים טז, יא), \u0003אל תיקרי \"שובע\" אלא: \"שבע\",\u0004 ויש ללמוד משם שהנעימות של הכינור (שנאמר: \"כנור נעים\", שם פא, ג) שהיו מנגנים בו לפני ה', היו בכינור של שבעה מיתרים. \u0003ו\u0004כינור \u0003של ימות המשיח\u0004 יהיה של \u0003שמונה\u0004 נימים, \u0003שנאמר: \"למנצח על השמינית\u0004 מזמור לדוד\" (תהילים יב, א), ויש ללמוד משם שאת הזמירות שינגנו בימות משיח בן דוד, ינגנו \u0003על נימא שמינית\u0004 שיוסיפו לכינור.","","והכינור \u0003של עולם הבא\u0004 יהיה של \u0003עשר\u0004 נימים, \u0003שנאמר:\u0004 \"מזמור שיר ליום השבת... \u0003עלי עשור ועלי נבל עלי הגיון בכנור\"\u0004 (תהילים צב, א—ד), שבשבת שלעתיד לבוא, שהיא העולם הבא, ינגנו ב\"עשור\", שהוא הנבל והוא הכנור. \u0003ו\u0004כן הוא \u0003אומר: \"הודו לה' בכנור בנבל עשור זמרו לו שירו לו שיר חדש\"\u0004 (תהילים לג, ב—ג), שבכנור שהוא נבל עשור ישירו את השיר החדש שלעולם הבא. הרי שר' יהודה סבור שכנור ונבל הוא אותו הכלי!","","ומשיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו היא כשיטת \u0003ר' יהודה,\u0004 יש להסביר כי \u0003לעולם הבא, איידי דנפישי נימין דידיה\u0004 \u0005[כיון שמרובים הנימים שלו,\u0006 של הכנור\u0005],\u0006 \u0003נפיש קליה\u0004 \u0005[מרובה קולו]\u0006 \u0003כי\u0004 \u0005[כמו]\u0006 \u0003נבל,\u0004 לכן \u0003קרי ליה\u0004 \u0005[קורא לו]\u0006 לזה של עתיד לבוא \u0003נבל,\u0004 אבל באמת שני כלים הם, כפי ששנינו במשנתנו. שנינו במשנה, \u0003ר' אליעזר בן יעקב אומר: אין עולין\u0004 הלויים הקטנים \u0003מן המנין כו'\u0004 וצערי הלוים היו נקראין. ומעירים, \u0003תנא\u0004 \u0005[שנה\u0006 החכם בברייתא\u0005]:\u0006 \u0003וסועדי\u0004 (עוזרי) \u0003הלוים היו נקראין,\u0004 כלומר, שהיו מסייעים ללויים בקולם. ושואלים: \u0003ותנא דידן\u0004 \u0005[והתנא שלנו]\u0006 מדוע אינו קורא להם כך? ומשיבים: \u0003כיון דהני קטין קלייהו\u0004 \u0005[שאלה,\u0006 הקטנים, \u0005דק קולם]\u0006 \u0003והני עב קלייהו\u0004 \u0005[ואלה,\u0006 המבוגרים, \u0005עבה קולם],\u0006 \u0003הני מקטטי והני לא מקטטי\u0004 \u0005[אלה,\u0006 הקטנים, \u0005מקטינים\u0006 את קולם, עושים את קולם דק ויפה, \u0005ואלה\u0006 המבוגרים \u0005אינם יכולים להקטין\u0006 את קולם\u0005],\u0006 לכן \u0003קרי להו\u0004 \u0005[קורא להם]\u0006 \u0003צערי\u0004 הלויים, על שהיו מצערים אותם.","","","\u0003יש בערכין\u0004 צדדים \u0003להקל ולהחמיר, וב\u0004מקדיש \u0003שדה אחוזה\u0004 (נחלת אבות) בארץ ישראל, יש צדדים \u0003להקל ולהחמיר, ובשור המועד שהמית העבד\u0004 יש צדדים \u0003להקל ולהחמיר,\u0004 וכן \u0003באונס ובמפתה ובמוציא שם רע\u0004 יש צדדים \u0003להקל ולהחמיר,\u0004 כפי שיבואר במשניות בהמשך הפרק. ומפרטים: \u0003יש בערכין להקל ולהחמיר, כיצד? אחד שהעריך,\u0004 כלומר, שאמר על מי שהוא בן עשרים ועד ששים שנה: \"ערך פלוני עלי\", בין \u0003את הנאה שבישראל,\u0004 ששוויו רב אילו היה נמכר כעבד, \u0003ו\u0004בין \u0003את הכעור שבישראל,\u0004 ששוויו מועט — \u0003נותן\u0004 את הערך הקצוב בתורה, \u0003חמשים סלע\u0004 (ויקרא כז, ג), \u0003ו\u0004אולם \u0003אם אמר: \"הרי דמיו עלי\"\u0004 — \u0003נותן את שוויו,\u0004 כאילו היה נמכר כעבד בשוק. שנינו במשנה: \u0003יש בערכין להקל ולהחמיר, כיצד? אחד שהעריך\u0004 את הנאה שבישראל ואת הכעור שבישראל נותן חמישים סלע. ומדייקים מלשון המשנה: \u0003בישראל\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003בגוים\u0004 — לא, ושואלים: \u0003לימא מתניתין\u0004 \u0005[\u0006האם \u0005נאמר שמשנתנו]\u0006 היא ש\u0003לא\u0004 \u0003כ\u0004שיטת \u0003ר' מאיר,\u0004 הסבור שמעריכים את הגוי, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003גוי, ר' מאיר אומר: נערך\u0004 על ידי ישראל, \u0003אבל לא מעריך?\u0004 ומשיבים: יש לפרש את משנתנו \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהיא כשיטת \u0003ר' מאיר,\u0004 ויש לומר כי \u0003הוא הדין\u0004 ש\u0003אפילו\u0004 ב\u0003גוי נמי\u0004 \u0005[גם כן]\u0006 מדובר, \u0003אלא\u0004","","","",""]]};
